const MISSIONS=[
  {id:"M001",titre:"Accueillir un client et découvrir ses besoins",comp:"C1.2",comp_ref:"C1.2",objectif:"Dans cette mission, tu vas identifier les étapes d'un entretien de vente et repérer les techniques de découverte et d'argumentation utilisées chez LABORO.",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",palier:1,option:"commun",dossier:{l:"Sélection produits sport débutant — Showroom LABORO",rows:[["Chaussures running EasyRun","Prix : 149 € · Semelle Contagrip, crampons profonds · Terrain : forêt, sentiers humides · Poids : 298g · Pointures : 36 à 48 · Idéal débutant sport"],["Chaussures running Velocity","Prix : 139 € · Amorti DNA Loft, coussin généreux · Terrain : route et chemin plat · Poids : 287g · Pointures : 36 à 47 · Idéal début running mixte"],["Chaussures running EasyRun","Prix : 129 € · Semelle sport légère, polyvalente · Terrain : chemin et route · Poids : 275g · Pointures : 36 à 46 · Bon rapport qualité/prix"],["Chaussettes anti-ampoules","Prix : 14 € · Fibre mérinos, zone rembourrée plante · Anti-ampoules · Tailles S/M/L/XL"],["Gourde isotherme LABORO 750ml","Prix : 29 € · Souple, légère · Peut se glisser dans la poche d'un sac ou à la main"]]},contexte:"M. Vidal, 42 ans, entre dans le showroom LABORO d'Évry. Il cherche des chaussures pour débuter le sport. Il n'a aucun équipement. Romain Sauzet vous demande de le prendre en charge.",contexte_pvoc:"Nina Chevalier te demande de prendre en charge un appel entrant sur la ligne commerciale LABORO. M. Thomas Vidal appelle depuis son bureau — il a vu vos chaussures sport sur laboro-sport.fr et veut des conseils avant de commander en ligne. C'est ton premier entretien de vente à distance.",activites:[{t:"Observer et identifier",q:["1.1  Lis le contexte. Parmi ces 3 formules d'accueil, laquelle est la plus professionnelle ? Explique pourquoi en 1 phrase : A) 'Bonjour, c'est pour quoi ?' — B) 'Bonjour M. Vidal, bienvenue chez LABORO, je suis à votre disposition.' — C) 'Bonjour, vous cherchez quelque chose ?'","1.2  Une question ouverte ne peut pas se répondre par oui ou non. Dans cette liste, identifie les 2 questions ouvertes : A) 'Vous faites du sport ?' — B) 'Quel sport pratiquez-vous ?' — C) 'Vous avez un budget ?' — D) 'Quel est votre budget mensuel pour le sport ?'","1.3  Complète cette phrase de découverte des besoins pour M. Vidal : 'Bonjour M. Vidal, pour vous orienter vers le produit idéal, j'aurais besoin de mieux vous connaître. Quel type de ___ pratiquez-vous, et à quelle ___ ?'"]},{t:"Découvrir et reformuler",q:["2.1  M. Vidal te dit : 'Je cherche des chaussures pour commencer le sport, je n'y connais rien.' Reformule sa demande en 1 phrase pour lui montrer que tu as bien compris.","2.2  Parmi les produits du dossier, quel article semblerait le plus adapté à M. Vidal débutant ? Coche ton choix et donne UNE raison simple.","2.3  Comment prends-tu congé de façon professionnelle ? Complète : 'Au revoir M. Vidal, ___ votre achat. N'hésitez pas à ___ si vous avez des questions.'"]}],livrable:"Réponses aux questions guidées + reformulation des besoins du client",criteres:[{"c":"Connaissance des étapes de vente","i":"J'identifie correctement les phases de l'entretien de vente (accueil, découverte, argumentation, conclusion)"},{"c":"Repérage des techniques","i":"Je repère les questions ouvertes, les arguments CAB et les signaux d'achat dans la situation décrite"},{"c":"Posture professionnelle","i":"Je décris les attitudes attendues d'un(e) conseiller(ère) de vente chez LABORO"}],reflexivite:0},
  {id:"M002",titre:"Réaliser la veille concurrentielle LABORO",comp:"C1.1",comp_ref:"C1.1",objectif:"Dans cette mission, tu vas repérer les sources d'information commerciale utilisées chez LABORO et identifier les informations clés sur les produits, les prix et la concurrence.",comp_libelle:"Bloc 1 — Assurer la veille commerciale",palier:1,option:"commun",contexte:"Nina Chevalier vous demande de préparer une note de veille sur la concurrence de LABORO sur le segment running dans l'Essonne.",contexte_pvoc:"Nina Chevalier te demande de préparer une note de veille concurrentielle B2B avant la réunion commerciale de vendredi. Ta zone : les fournisseurs d'équipements sportifs en Essonne qui ciblent les CE et les clubs.",activites:[{t:"Observer la concurrence",q:["1.1  Regarde le dossier documentaire. Cite 2 concurrents de LABORO dans le sport et loisirs (nom + type de commerce).","1.2  Pour chacun de ces 2 concurrents, note UN point fort et UN point faible par rapport à LABORO.","1.3  Selon toi, sur quel point LABORO se différencie-t-il le mieux de ses concurrents ? Justifie en 1 phrase."]},{t:"Identifier les informations utiles",q:["2.1  Parmi ces informations sur un concurrent, laquelle est la plus utile pour LABORO ? A) La couleur de leur logo — B) Leurs prix sur les sneakers — C) Le prénom du gérant — D) Leurs horaires d'ouverture.","2.2  Complète cette phrase : La veille commerciale sert à surveiller ___ pour adapter ___.","2.3  Romain te demande de noter 3 informations à surveiller régulièrement sur les concurrents de LABORO. Lesquelles choisis-tu ?"]}],livrable:"Tableau de veille concurrentielle complété + points forts/faibles identifiés",criteres:[{"c":"Identification des sources","i":"Je cite au moins 2 sources d'information commerciale pertinentes pour LABORO"},{"c":"Compréhension des informations","i":"Je décris correctement les informations utiles issues des sources identifiées"},{"c":"Lien avec la situation LABORO","i":"Je relie les informations trouvées à la situation commerciale décrite"}],reflexivite:0},
  {id:"M003",titre:"Traiter la réclamation de Mme Renard",comp:"C2.2",comp_ref:"C2.3",objectif:"Dans cette mission, tu vas identifier les étapes de traitement d'une réclamation client et repérer les attitudes professionnelles adaptées.",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",palier:1,option:"commun",contexte:"Mme Renard se présente au showroom : elle a commandé un tapis de yoga sur laboro-sport.fr il y a 7 jours. Elle l'a reçu endommagé. Elle est mécontente et réclame un remboursement.",contexte_pvoc:"Mme Renard t'envoie un mail de réclamation suite à une commande passée sur laboro-sport.fr. Elle n'a pas reçu ses chaussures sport dans le délai annoncé et demande des explications. Romain Sauzet te dit : 'Réponds-lui par mail — et appelle-la ensuite pour finaliser.'",activites:[{t:"Identifier la réclamation",q:["1.1  Lis la situation. Quel est le problème exact de Mme Renard ? Résume en 1 phrase simple.","1.2  Parmi ces réactions face à une réclamation, laquelle est correcte ? A) Dire que c'est la faute du client — B) Écouter sans interrompre puis reformuler — C) Passer le client à un collègue tout de suite — D) Proposer un remboursement immédiat sans écouter.","1.3  Quels sont les droits de Mme Renard dans cette situation ? Cite-en 2 à partir du dossier."]},{t:"Proposer une solution",q:["2.1  Complète cette phrase d'empathie à dire à Mme Renard : 'Je comprends tout à fait votre ___, madame Renard. Je suis ___ de cet inconvénient.'","2.2  Parmi ces solutions, laquelle proposes-tu à Mme Renard et pourquoi ? A) Échange du produit — B) Avoir commercial — C) Remboursement — D) Bon de réduction.","2.3  Complete cette prise de conge : Madame Renard, nous vous presentons nos ___ pour cet incident. Votre ___ sera exchange des demain. N'hesitez pas a ___ si vous avez besoin."]}],livrable:"Analyse de la réclamation + solution proposée + formule de clôture rédigée",criteres:[{"c":"Connaissance des étapes ERESA","i":"J'identifie et nomme correctement les 5 étapes du traitement d'une réclamation"},{"c":"Attitude professionnelle","i":"Je décris les attitudes adaptées face à un client mécontent (écoute, empathie, calme)"},{"c":"Identification de la solution","i":"Je propose une solution réaliste et adaptée à la situation décrite"}],reflexivite:0},
  {id:"M005",titre:"Informer un client du statut de sa commande",comp:"C2.1",comp_ref:"C2.1",objectif:"Dans cette mission, tu vas identifier les étapes du traitement d'une commande chez LABORO et repérer les documents associés.",comp_libelle:"Bloc 2 — Assurer le suivi de la commande du produit et/ou du service",palier:1,option:"commun",dossier:{l:"Extrait LABORO Connect — Commande M. Bensalah",rows:[["Référence","CMD-2026-0847"],["Client","M. Karim Bensalah"],["Produit","Chaussures trail Grip X — taille 43"],["Date commande","Il y a 5 jours"],["Statut","Expédié hier — livraison prévue demain 9h-13h"],["Transporteur","notre transporteur partenaire — n° suivi : CP847291FR"]]},contexte:"M. Bensalah vous appelle car il n'a pas reçu de confirmation de livraison pour sa commande passée il y a 5 jours sur laboro-sport.fr.",contexte_pvoc:"M. Karim Bensalah t'appelle sur ta ligne directe. Il a passé commande sur laboro-sport.fr il y a 5 jours et n'a reçu aucune confirmation de livraison. Il est inquiet. Tu dois le renseigner à distance à partir de LABORO Connect.",activites:[{t:"Identifier les étapes de la commande",q:["1.1  Remets dans l'ordre ces étapes de finalisation d'une vente : A) Remettre le ticket de caisse — B) Encaisser le règlement — C) Vérifier la disponibilité du produit — D) Confirmer la commande au client.","1.2  Quels documents doit-on remettre à un client après un achat chez LABORO ? Cite-en au moins 2 à partir du dossier.","1.3  Mme Konaté veut payer en carte bancaire. Décris les 3 étapes de l'encaissement en point de vente en 3 phrases courtes."]},{t:"Informer le client",q:["2.1  Un client rappelle pour savoir où en est sa commande. Complète ce script d'appel : 'Bonjour M. ___, ici ___ de LABORO. Votre commande est ___, elle sera disponible le ___. Avez-vous des ___?'","2.2  Complete ce SMS : Bonjour ___, votre commande est prete a ___. Vous pouvez venir la ___ pendant nos horaires d'ouverture. A bientot, LABORO"]}],livrable:"Informations de suivi commande identifiées + message client complété",criteres:[{"c":"Identification des étapes","i":"Je décris les étapes du traitement d'une commande et les documents associés"},{"c":"Lecture des documents","i":"Je lis et décris correctement les documents commerciaux fournis (bon de commande, facture...)"},{"c":"Identification des anomalies","i":"Je repère les erreurs ou anomalies dans les documents fournis"}],reflexivite:0},
  {id:"M007",titre:"Finaliser la vente et remettre les documents",comp:"C1.3",comp_ref:"C1.3",objectif:"Dans cette mission, tu vas identifier les opérations à réaliser après une vente chez LABORO — bon de commande, suivi, remise de documentation.",comp_libelle:"Bloc 1 — Assurer l’exécution de la vente",palier:1,option:"commun",dossier:{l:"Commande M. Vidal à finaliser",rows:[["Produit 1","Chaussures running EasyRun — 149 € TTC"],["Produit 2","tapis de yoga 6mm — 59 € TTC"],["Mode de paiement","Carte bancaire"],["Livraison","À emporter"]]},contexte:"M. Vidal vient de décider d'acheter les Chaussures running EasyRun et un tapis de yoga LABORO. Romain Sauzet vous demande de finaliser la transaction et de prendre congé de façon professionnelle.",contexte_pvoc:"Tu viens de conclure par téléphone une vente de 12 chaussures sport avec le responsable achats du CE PSA Stellantis. Il faut maintenant finaliser la commande à distance : confirmer les modalités, envoyer le devis, organiser la livraison.",activites:[{t:"Identifier les étapes de l'encaissement",q:["1.1  Lis le dossier. Remets dans l'ordre ces étapes d'encaissement par carte bancaire : A) Le client compose son code — B) Tu announces le montant total — C) Tu insères la carte dans le terminal — D) Tu remets le ticket.","1.2  Parmi ces situations, laquelle nécessite de demander une pièce d'identité ? A) Paiement en carte bancaire — B) Paiement en chèque — C) Paiement en espèces — D) Paiement en bon d'achat.","1.3  Chez LABORO, quel est le délai légal de retour pour un produit défectueux ? Trouve la réponse dans le dossier."]},{t:"Préparer les documents et la prise de congé",q:["2.1  Quels documents dois-tu remettre à M. Vidal après son achat ? Fais la liste et explique en 1 mot l'utilité de chacun.","2.2  Complète cette prise de congé professionnelle : 'Voilà M. Vidal, voici votre ___ et votre ___. Nous espérons que ___ vous donnera entière satisfaction. N'hésitez pas à ___.'"]}],livrable:"Étapes de finalisation identifiées + documents et paiement maîtrisés",criteres:[{"c":"Identification des opérations post-vente","i":"Je décris les opérations à réaliser après une vente chez LABORO (bon de commande, suivi, remise de doc)"},{"c":"Connaissance des documents","i":"Je cite et décris les documents commerciaux utilisés lors de la finalisation d'une vente"},{"c":"Lien avec la relation client","i":"J'explique en quoi ces opérations contribuent à la satisfaction du client"}],reflexivite:0},
  {id:"M010",titre:"Analyser les résultats d'une enquête satisfaction",comp:"C2.3",comp_ref:"C2.4",objectif:"Dans cette mission, tu vas identifier les outils et indicateurs de mesure de la satisfaction client utilisés chez LABORO.",comp_libelle:"Bloc 2 — S’assurer de la satisfaction du client",palier:1,option:"commun",dossier:{l:"Résultats enquête satisfaction trimestrielle LABORO",rows:[["Répondants","118 clients"],["Très satisfaits","52"],["Satisfaits","37"],["Neutres","18"],["Insatisfaits","11"],["NPS","+12"],["Principal grief","Délais livraison e-commerce (38% des insatisfaits)"],["Second grief","Accueil téléphonique (29% des insatisfaits)"]]},contexte:"Marco Pellini vous remet les résultats complets de l'enquête satisfaction trimestrielle. Il vous demande une analyse et des propositions d'amélioration à présenter à Pascal Berruelle.",contexte_pvoc:"Marco Pellini te remet les résultats du sondage satisfaction mené auprès des 18 clients B2B de LABORO. Il te demande d'analyser les données, d'interpréter le NPS et de proposer 2 actions d'amélioration ciblées sur la relation client B2B.",activites:[{t:"Observer les resultats",q:["1.1  Lis le dossier. Quel est le taux de satisfaction globale de LABORO ? Trouve la reponse dans les donnees et note le chiffre.","1.2  Que signifie le NPS (Net Promoter Score) ? Parmi ces definitions, laquelle est correcte ? A) Le nombre de nouveaux clients — B) Un indicateur de satisfaction et recommandation — C) Le chiffre d'affaires mensuel — D) Le nombre de reclamations.","1.3  Parmi ces 3 insatisfactions clients relevees dans le dossier, laquelle te semble la plus urgente a traiter ? Justifie en 1 phrase."]},{t:"Identifier les actions",q:["2.1  Pour l'insatisfaction que tu as choisie, cite 2 actions concretes que LABORO pourrait mettre en place pour s'ameliorer.","2.2  Complete cette phrase : 'Mesurer la satisfaction client sert a ___ et a ___ afin de ___.'"]}],livrable:"Taux de satisfaction calculé + actions correctives identifiées",criteres:[{"c":"Identification des outils","i":"Je cite les outils de mesure de satisfaction utilisés chez LABORO (questionnaire, avis, NPS)"},{"c":"Lecture des résultats","i":"Je lis et décris correctement les résultats d'une enquête simple"},{"c":"Formulation d'une observation","i":"Je relève au moins un point fort et un point faible dans les résultats"}],reflexivite:0},
  {id:"M011",titre:"Traiter les messages et contacts entrants",comp:"C3.1",comp_ref:"C3.1",objectif:"Dans cette mission, tu vas identifier les informations clients disponibles chez LABORO et comprendre leur utilité dans la relation commerciale.",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",palier:1,option:"commun",contexte:"Marco Pellini vous confie la gestion des messages entrants de LABORO ce matin. Quatre contacts arrivent simultanément depuis des canaux différents.",contexte_pvoc:"Marco Pellini te confie la gestion des messages entrants B2B de LABORO ce matin : un mail de demande de devis d'un CE, un commentaire sur la page pro, un appel d'un club intéressé. Tu découvres comment on traite et qualifie un contact à distance — première approche du métier de la prospection (option B).",activites:[{t:"Observer et réagir aux messages",q:["1.1  Un client a laissé un avis Google 2 étoiles avec ce commentaire : 'Délai de livraison trop long, pas de nouvelles pendant 5 jours.' Parmi ces 4 réponses, laquelle est la plus professionnelle pour LABORO ? A) Ne pas répondre — B) 'Nous sommes désolés, ce n'est pas notre habitude. Nous vous contactons en privé.' — C) 'Vous avez tort, les délais sont indiqués sur notre site.' — D) 'Merci de votre retour.'","1.2  Quel est l'objectif d'une réponse à un avis négatif en ligne ? Coche les 2 bonnes réponses : A) Se justifier — B) Montrer que l'entreprise prend en compte les remarques — C) Attirer de nouveaux clients qui lisent les avis — D) Effacer le commentaire négatif.","1.3  Complète cette réponse type à un avis négatif : 'Bonjour ___, merci pour votre ___. Nous sommes ___ de cette situation. Notre équipe va ___ pour vous apporter une solution.'"]},{t:"Identifier les informations d'un prospect",q:["2.1  Mme Konaté rappelle — elle est intéressée par des équipements pour son club de sport. Quelles informations as-tu besoin de connaître avant de lui proposer quelque chose ? Coche les 4 plus importantes : A) Son prénom — B) Le type de sport pratiqué — C) Le nombre de membres — D) Son budget — E) Sa couleur préférée — F) La fréquence des achats.","2.2  Pour classer Mme Konaté comme prospect prioritaire, complète cette phrase : 'Mme Konaté est un bon prospect car elle a un ___ identifié, un ___ disponible, et une ___ d'achat concrète.'","2.3  Que dois-tu noter dans le fichier clients après cet appel ? Cite 3 informations essentielles."]}],livrable:"Réponses aux messages clients + informations prospects notées",criteres:[{"c":"Identification des informations clients","i":"Je cite les informations clés à collecter sur un client LABORO (nom, type, historique, préférences)"},{"c":"Compréhension de l'utilité","i":"J'explique à quoi servent ces informations dans la relation commerciale"},{"c":"Lecture du fichier clients","i":"Je lis correctement les données du fichier clients LABORO fourni"}],reflexivite:0},
  {id:"M012",titre:"Identifier et proposer les services associés",comp:"C2.1b",comp_ref:"C2.2",objectif:"Dans cette mission, tu vas identifier les services associés proposés par LABORO et comprendre leur rôle dans la relation client.",comp_libelle:"Bloc 2 — Mettre en œuvre le ou les services associés",palier:1,option:"commun",dossier:{l:"Services associés LABORO — tarifs en vigueur",rows:[["Livraison standard","transporteur partenaire 48h — 6,90 €"],["Livraison express","transporteur partenaire 24h — 12,90 €"],["Flocage textile","notre atelier de flocage — inclus dans le prix — délai 3 semaines"],["Broderie textile","notre atelier de flocage — +2 €/u — délai 4 semaines"],["Click and collect","Showroom Évry — gratuit — 2h si en stock"],["Garantie commerciale","Échange ou remboursement — 30 jours — inclus"]]},contexte:"Mme Konaté vient d'acheter 15 maillots personnalisables avec flocage pour l'équipe de football de son fils. Elle habite à Corbeil-Essonnes et ne peut pas revenir chercher la commande. Thomas Moreau vous demande de finaliser la vente et de l'informer de tous les services disponibles.",contexte_pvoc:"Le responsable achats du CE PSA Stellantis vient de commander 15 maillots flocage pour le challenge inter-services. Comme il ne peut pas se déplacer, Thomas Moreau te demande de finaliser la commande à distance et de l'informer de tous les services associés disponibles — une première approche de la relation client B2B (option B).",activites:[{t:"Identifier les services adaptes",q:["1.1  Mme Konaté achète 10 ballons de football pour son club. Parmi ces services, lesquels sont les 2 plus utiles à lui proposer ? A) Livraison a domicile — B) Gravure personnalisee — C) Extension de garantie — D) Flocage du nom du club — E) Emballage cadeau.","1.2  Un service associe est utile : A) Uniquement pour LABORO — B) Uniquement pour le client — C) Pour le client ET pour LABORO — D) Jamais. Coche la bonne reponse et donne 1 exemple.","1.3  Parmi ces moments, lequel est le meilleur pour proposer un service associe ? A) Avant meme que le client arrive — B) Pendant la vente, quand le client est interesse — C) Uniquement apres avoir encaisse."]},{t:"Informer le client",q:["2.1  Complete ce recapitulatif pour Mme Konaté : 'Madame Konaté, voici les services retenus : ___ pour un delai de ___, et ___ au tarif de ___. Livraison prevue le ___. '","2.2  Mme Konaté ne sera pas disponible le jour de la livraison. Laquelle de ces solutions proposes-tu ? A) Annuler la livraison — B) Proposer une autre date — C) Laisser le colis devant la porte.","2.3  Complete ce SMS de confirmation : 'Bonjour Mme Konaté, voici LABORO. Votre commande de ___ est confirmee. Livraison prevue le ___. Bonne journee !'"]}],livrable:"Services adaptés identifiés + récapitulatif et SMS complétés",criteres:[{"c":"Identification des services","i":"Je cite les services associés proposés par LABORO et décris leur utilité"},{"c":"Lien avec le produit","i":"Je fais le lien entre le produit vendu et les services associés pertinents"},{"c":"Compréhension des enjeux","i":"J'explique l'intérêt des services associés pour LABORO et pour le client"}],reflexivite:0},
  {id:"M013",titre:"Préparer une action de fidélisation",comp:"C3.2",comp_ref:"C3.2",objectif:"Dans cette mission, tu vas identifier les actions de fidélisation utilisées par LABORO et comprendre leur logique commerciale.",comp_libelle:"Bloc 3 — Contribuer à des actions de fidélisation de la clientèle et de développement de la relation client",palier:1,option:"commun",contexte:"LABORO organise sa soirée annuelle Rentrée Sportive dans 3 semaines. Nina Chevalier vous demande de sélectionner les clients à inviter en priorité et de préparer les invitations.",contexte_pvoc:"LABORO organise sa soirée annuelle Rentrée Sportive dans 3 semaines pour ses meilleurs clients B2B (CE, clubs). Nina Chevalier te demande de sélectionner les comptes à inviter en priorité et de préparer les invitations, dans une logique de fidélisation de la relation client à distance.",activites:[{t:"Sélectionner les clients à inviter",q:["1.1  LABORO organise une soirée fidélisation. Parmi ces critères, lesquels sont les plus importants pour choisir qui inviter ? Classe-les de 1 (le plus important) à 4 : A) CA annuel réalisé — B) Ancienneté client — C) Potentiel de développement — D) Fréquence d'achat.","1.2  Dans le fichier clients, identifie 2 clients B2B et 1 client B2C qui méritent d'être invités en priorité. Justifie chaque choix en 1 phrase.","1.3  Pourquoi est-il utile d'inviter aussi des clients B2C à une soirée fidélisation ? Donne 1 raison."]},{t:"Préparer l'invitation",q:["2.1  Complète ce mail d'invitation pour Isabelle Faure (CE PSA Stellantis) : 'Madame Faure, LABORO a le plaisir de vous inviter à ___ le ___. Au programme : ___. Votre présence nous ferait ___. Merci de confirmer avant le ___.'","2.2  Quel ton doit avoir un mail d'invitation B2B ? Coche les 2 bonnes réponses : A) Très formel et distant — B) Professionnel mais chaleureux — C) Familier et décontracté — D) Personnalisé et valorisant.","2.3  Quel est l'objectif principal d'une action de fidélisation pour LABORO ? Réponds en 1 phrase."]}],livrable:"Critères de sélection appliqués + invitation complétée",criteres:[{"c":"Identification des actions de fidélisation","i":"Je cite et décris au moins 3 actions de fidélisation utilisées par LABORO"},{"c":"Compréhension des enjeux","i":"J'explique pourquoi fidéliser un client est plus rentable qu'en conquérir un nouveau"},{"c":"Lien avec le contexte LABORO","i":"Je relie les actions identifiées à la clientèle sport & outdoor de LABORO"}],reflexivite:0},
  {id:"ACC1",titre:"Assurer l'accueil physique au showroom",comp:"ACC",comp_ref:"ACC",objectif:"Dans cette mission, tu vas identifier les composantes d'un accueil professionnel et les attitudes attendues chez LABORO.",comp_libelle:"Seconde — Découverte des métiers de l’accueil (famille relation client)",palier:1,option:"2nde",contexte:"C'est ton premier jour au showroom d'Évry. Romain Sauzet t'explique que l'accueil des visiteurs est la responsabilité de toute l'équipe. Ce matin, trois situations vont se présenter successivement.",activites:[{t:"Maîtriser les fondamentaux de l'accueil",q:["1.1  Lis le dossier. Complète cette formule d'accueil physique au showroom LABORO : 'Bonjour ___ / ___, bienvenue chez ___. Je suis ___, je suis à votre ___.'","1.2  Parmi ces attitudes, lesquelles sont professionnelles à l'accueil ? Coche les 3 bonnes : A) Sourire en regardant le client — B) Continuer à ranger sans s'arrêter — C) Se lever si on est assis — D) Dire 'C'est pour quoi ?' — E) Laisser le client regarder en restant disponible.","1.3  M. Fontaine entre et demande à voir le responsable. Romain est en réunion. Complète ta réponse : 'Bonjour M. Fontaine. M. Sauzet est ___ pour l'instant. Puis-je prendre votre ___ et lui faire passer votre ___?'"]},{t:"Gérer des situations d'accueil courantes",q:["2.1  Mme Konaté entre avec deux enfants, elle semble perdue. Parmi ces actions, laquelle fais-tu EN PREMIER ? A) Attendre qu'elle vienne te voir — B) L'approcher avec un sourire et lui demander si elle cherche quelque chose — C) Appeler un collègue — D) Lui tendre un catalogue.","2.2  Deux clients arrivent en même temps alors que tu es seul. Complète ta réaction : 'Bonjour ___ et ___. Je m'occupe de vous dans un ___. Monsieur/Madame, je suis à vous dans ___.'","2.3  Pourquoi l'accueil physique est-il important pour LABORO ? Donne 2 raisons en 2 phrases courtes."]}],livrable:"Formule d'accueil maîtrisée + réactions aux situations identifiées",criteres:[{"c":"Connaissance des standards","i":"Je décris les standards d'accueil professionnels attendus chez LABORO"},{"c":"Posture et attitudes","i":"Je décris les attitudes et la posture adaptées à un accueil professionnel"},{"c":"Gestion des situations courantes","i":"Je décris comment gérer les situations d'accueil les plus fréquentes chez LABORO"}],reflexivite:0},
  {id:"ACC2",titre:"Gérer l'accueil téléphonique de LABORO",comp:"ACC",comp_ref:"ACC",comp_libelle:"Seconde — Découverte des métiers de l’accueil (famille relation client)",objectif:"Dans cette mission, tu vas identifier les composantes d'un accueil professionnel et les attitudes attendues chez LABORO.",palier:1,option:"2nde",dossier:{l:"Annuaire interne LABORO — disponibilités ce matin",rows:[["Pascal Berruelle","PDG — En réunion jusqu'à 11h"],["Romain Sauzet","Resp. Commerce — Disponible"],["Nina Chevalier","Resp. Vente — En déplacement, rappelle après 14h"],["Marco Pellini","Resp. E-commerce — Disponible"],["Sophie Blanc","Commerciale — Avec un client"],["Thomas Moreau","Conseiller — En congé"]]},contexte:"Marco Pellini vous confie la permanence téléphonique du showroom ce matin de 9h à 12h. Quatre appels vont mettre à l'épreuve ta maîtrise de l'accueil téléphonique.",activites:[{t:"Maîtriser le décrochage téléphonique",q:["1.1  Lis le dossier. Remets dans l'ordre les éléments d'un décrochage professionnel : A) Ton prénom — B) Le nom de l'entreprise — C) Une formule de salutation — D) Une proposition d'aide. Donne l'ordre correct.","1.2  Appel 1 : M. Vidal demande si le Chaussures running EasyRun est disponible en taille 44. Tu ne le sais pas. Parmi ces réponses, laquelle est correcte ? A) 'Je ne sais pas.' — B) 'Oui bien sûr.' — C) 'Je vérifie et vous rappelle dans 10 minutes, c'est bien votre numéro le 06...' — D) 'Appelez plus tard.'","1.3  Appel 2 : Mme Faure veut passer une commande groupée pour le CE PSA. Quelles informations dois-tu noter ? Cite 4 éléments essentiels."]},{t:"Gérer les appels difficiles",q:["2.1  Un client mécontent rappelle pour la 3ème fois et veut Nina Chevalier. Elle est indisponible. Complète ta réponse : 'Bonjour M. ___, je comprends votre ___. Nina est ___ en ce moment. Je note votre ___ et elle vous ___ dès que possible. Puis-je prendre un message ?'","2.2  Parmi ces comportements au téléphone, lesquels sont à éviter ? Coche les 3 mauvaises pratiques : A) Prendre un message précis — B) Manger en parlant — C) Mettre en attente sans prévenir — D) Sourire en parlant — E) Parler trop vite.","2.3  Pourquoi est-il important de rappeler un client dans le délai promis ? Réponds en 1 phrase."]}],livrable:"Décrochage téléphonique maîtrisé + appels difficiles gérés",criteres:[{"c":"Connaissance des standards","i":"Je décris les standards d'accueil professionnels attendus chez LABORO"},{"c":"Posture et attitudes","i":"Je décris les attitudes et la posture adaptées à un accueil professionnel"},{"c":"Gestion des situations courantes","i":"Je décris comment gérer les situations d'accueil les plus fréquentes chez LABORO"}],reflexivite:0},
  {id:"ACC3",titre:"Gérer une situation difficile à l'accueil",comp:"ACC",comp_ref:"ACC",comp_libelle:"Seconde — Découverte des métiers de l’accueil (famille relation client)",objectif:"Dans cette mission, tu vas identifier les composantes d'un accueil professionnel et les attitudes attendues chez LABORO.",palier:1,option:"2nde",dossier:{l:"Charte de gestion des situations difficiles LABORO",rows:[["Client mécontent","Écouter sans interrompre, reformuler, proposer"],["File d'attente","Reconnaître chaque personne qui attend"],["Demande impossible","Proposer une alternative — jamais 'non' seul"],["Situation de tension","Rester calme, voix douce — ne jamais rentrer dans le conflit"]]},contexte:"C'est un samedi matin de forte affluence au showroom. Romain Sauzet est en réunion. Tu es en charge de l'accueil avec Thomas Moreau. Trois situations difficiles se présentent en même temps.",activites:[{t:"Identifier les bonnes réactions",q:["1.1  M. Bensalah attend depuis 20 minutes et commence à s'impatienter. Quelle est la MEILLEURE réaction ? A) L'ignorer car tu es occupé — B) Lui dire d'attendre encore — C) Le reconnaître du regard, lui sourire et lui signaler que tu t'occupes de lui dès que possible — D) Appeler un collègue sans rien lui dire.","1.2  Dans la gestion d'une situation tendue, remets ces étapes dans l'ordre : A) Proposer une solution — B) Écouter sans interrompre — C) Reformuler pour montrer que tu as compris — D) Remercier le client de sa patience.","1.3  Parmi ces phrases, lesquelles montrent de l'empathie ? Coche les 2 bonnes : A) 'C'est votre problème, pas le mien.' — B) 'Je comprends votre impatience.' — C) 'Ce n'est pas de ma faute.' — D) 'Je suis désolé pour l'attente.'"]},{t:"Gérer des situations concrètes",q:["2.1  Un groupe de jeunes entre, parle fort et touche les produits sans précaution. Complète ta réaction : 'Bonjour ! ___ chez LABORO. Si vous souhaitez ___ un produit, je suis là pour vous ___. Ces articles sont fragiles, merci de les ___.'","2.2  Quel est le but principal de bien gérer une situation difficile en magasin ? Coche la meilleure réponse : A) Faire partir le client rapidement — B) Préserver l'image de LABORO et fidéliser le client — C) Montrer qui est le responsable — D) Éviter les conflits à tout prix.","2.3  Cite 2 situations difficiles que tu pourrais rencontrer à l'accueil LABORO et pour chacune, la première chose à faire."]}],livrable:"Réactions professionnelles identifiées + situations concrètes traitées",criteres:[{"c":"Connaissance des standards","i":"Je décris les standards d'accueil professionnels attendus chez LABORO"},{"c":"Posture et attitudes","i":"Je décris les attitudes et la posture adaptées à un accueil professionnel"},{"c":"Gestion des situations courantes","i":"Je décris comment gérer les situations d'accueil les plus fréquentes chez LABORO"}],reflexivite:0},
  {id:"ACC4",titre:"Assurer l'accueil lors d'un événement LABORO",comp:"ACC",comp_ref:"ACC",comp_libelle:"Seconde — Découverte des métiers de l’accueil (famille relation client)",objectif:"Dans cette mission, tu vas identifier les composantes d'un accueil professionnel et les attitudes attendues chez LABORO.",palier:1,option:"2nde",dossier:{l:"Programme Journée Portes Ouvertes Running",rows:[["10h-12h","Accueil libre + présentation nouveautés — Thomas Moreau"],["12h-13h","Buffet sportif offert — Sophie Blanc"],["13h-15h","Ateliers conseils chaussures (groupes de 10) — Romain Sauzet"],["15h-17h","Accueil libre + ventes — Toi + Thomas"],["17h-18h","Remise des prix tirage au sort — Pascal Berruelle"]]},contexte:"LABORO organise sa journée Portes Ouvertes Running au showroom d'Évry. Pascal Berruelle vous confie la responsabilité de l'accueil. 80 personnes sont attendues entre 10h et 18h.",activites:[{t:"Préparer l'ouverture",q:["1.1  Voici une liste de tâches à faire avant l'ouverture à 10h. Identifie les 4 plus importantes pour l'accueil : A) Vérifier que l'entrée est propre — B) Allumer la caisse — C) Changer ses chaussures — D) Mettre de la musique — E) Vérifier que les étiquettes prix sont visibles — F) Préparer les sacs et papiers d'emballage.","1.2  À quelle heure minimum dois-tu arriver si l'ouverture est à 10h ? Justifie en 1 phrase.","1.3  Quel est l'état d'esprit idéal pour accueillir les premiers clients de la journée ? Décris-le en 2 phrases."]},{t:"Gérer un incident et faire un bilan",q:["2.1  À 15h30, une personne signale qu'elle ne se sent pas bien. Parmi ces actions, laquelle fais-tu EN PREMIER ? A) Appeler le 15 — B) L'installer confortablement et prévenir ton responsable — C) Continuer à travailler — D) Demander aux autres clients de partir.","2.2  En fin de journée, Pascal te demande ton bilan. Complète : 'Aujourd'hui j'ai accueilli environ ___ clients. Le point positif a été ___. Le point à améliorer est ___. Demain je vais ___.'","2.3  Pourquoi faire un bilan de fin de journée est-il utile pour progresser ? Réponds en 1 phrase."]}],criteres:[{"c":"Connaissance des standards","i":"Je décris les standards d'accueil professionnels attendus chez LABORO"},{"c":"Posture et attitudes","i":"Je décris les attitudes et la posture adaptées à un accueil professionnel"},{"c":"Gestion des situations courantes","i":"Je décris comment gérer les situations d'accueil les plus fréquentes chez LABORO"}],reflexivite:0},
  {id:"M004",titre:"Qualifier le Club Sportif Forêt de Sénart",comp:"C1.2",comp_ref:"C1.2",objectif:"Dans cette mission, tu vas conduire un entretien de vente structuré en appliquant les méthodes CAB et SONCAS dans un contexte LABORO.",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",palier:2,option:"commun",dossier:{l:"Fiche prospect — Club Sportif Forêt de Sénart",rows:[["Contact","Marc Girault, président"],["Membres","85 licenciés"],["Discipline","Trail et course nature"],["Besoins potentiels","Chaussures sport, vêtements, nutrition"],["Statut","Prospect tiède — contact Salon du Trail Paris"]]},contexte:"Nina Chevalier vous demande de qualifier le Club Sportif Forêt de Sénart et de réaliser la prise de contact téléphonique pour obtenir un rendez-vous.",contexte_pvoc:"Nina Chevalier te confie la qualification du Club Sportif Forêt de Sénart : identifier ses besoins et réaliser la prise de contact téléphonique pour décrocher un rendez-vous. C'est ta première approche de la prospection commerciale à distance (option B).",activites:[{t:"Préparer la prospection",q:["1.1  Identifier les 4 elements indispensables d'un plan d'appel : A) Accroche — B) Presentation — C) Decouverte — D) Conclusion. Dans quel ordre les utilises-tu ? Marc Girault.","1.2  Sélectionner 3 produits LABORO adaptés à un club sportif et justifier chaque choix."]},{t:"Construire la proposition commerciale",q:["2.1  Marc Girault est intéressé. Établir un devis pour 12 paires de Chaussures running EasyRun.","2.2  LABORO accorde 8% de remise à partir de 10 unités. Calculer HT, remise, total HT et TTC.","2.3  Rédiger le mail d'accompagnement du devis."]}],livrable:"Plan d'appel rédigé + 3 produits sélectionnés + devis calculé + mail rédigé",criteres:[{"c":"Découverte des besoins","i":"J'utilise des questions ouvertes adaptées au profil client pour identifier ses besoins"},{"c":"Argumentation structurée (CAB)","i":"Mon argumentation distingue caractéristique, avantage et bénéfice client"},{"c":"Traitement des objections","i":"Je traite au moins une objection avec méthode (écoute, reformulation, réponse, validation)"},{"c":"Conclusion de la vente","i":"Je propose une formule de conclusion adaptée à la situation"}],reflexivite:0},
  {id:"M006",titre:"Préparer et contribuer à une soirée de fidélisation",comp:"C3.2",comp_ref:"C3.2",objectif:"Dans cette mission, tu vas concevoir une action de fidélisation adaptée à un segment de clientèle LABORO.",comp_libelle:"Bloc 3 — Contribuer à des actions de fidélisation de la clientèle et de développement de la relation client",palier:2,option:"commun",dossier:{l:"Données CE Thales Group Massy",rows:[["Salariés","850"],["Budget sport CE","12 000 €/an"],["Achats LABORO","Maillots 40% · Running 25% · Fitness 20% · Randonnée 15%"],["Contact","Isabelle Faure, responsable CE"],["CA annuel","19 500 €"]]},contexte:"LABORO organise une soirée Rentrée Sportive pour ses 50 meilleurs clients. Nina Chevalier vous demande de prendre en charge la préparation, notamment pour le CE Thales.",contexte_pvoc:"Nina Chevalier prépare une opération de fidélisation clients B2B : elle invite 15 CE partenaires à une soirée showroom. Elle te demande de préparer la liste d'invités, les relances téléphoniques et de contribuer à l'animation ce soir-là.",activites:[{t:"Organiser l'événement",q:["1.1  Identifier dans le fichier clients les 5 clients B2B et 5 clients B2C prioritaires à inviter. Justifier tes critères.","1.2  Rédiger le mail d'invitation personnalisé pour Isabelle Faure.","1.3  Lister 5 actions à mener avant, pendant et après la soirée."]},{t:"Saisir les opportunités",q:["2.1  Le directeur du Club Sportif Sénart montre de l'intérêt pour les maillots personnalisés. Rédiger le script de vente au rebond.","2.2  8 clients ont commandé pour un CA de 4 200 € HT sur 38 présents. Calculer le taux de transformation et analyser."]}],livrable:"Sélection invités + mail Isabelle Faure + plan avant/pendant/après + script vente au rebond + calcul et analyse",criteres:[{"c":"Conception de l'action","i":"L'action de fidélisation proposée est cohérente avec le profil de la clientèle LABORO"},{"c":"Justification des choix","i":"Mes choix sont argumentés en lien avec les objectifs commerciaux de LABORO"},{"c":"Faisabilité","i":"L'action est réaliste dans le contexte d'une PME sport comme LABORO"}],reflexivite:0},
  {id:"M008",titre:"Gérer un retard de livraison",comp:"C2.1",comp_ref:"C2.1",objectif:"Dans cette mission, tu vas traiter une commande client en respectant les procédures LABORO et en vérifiant la cohérence des données.",comp_libelle:"Bloc 2 — Assurer le suivi de la commande du produit et/ou du service",palier:2,option:"commun",dossier:{l:"Situation — Mairie d'Évry-Courcouronnes",rows:[["Commande","50 ballons Pro Match T5 — 49 € TTC/u"],["Date commande","Il y a 10 jours"],["Livraison prévue","Ce vendredi"],["Problème","Fournisseur Pro Match : retard 8 jours — problème de stock"],["Événement client","Forum sportif municipal samedi prochain"],["Contact","David Chemin, responsable achats"]]},contexte:"Le fournisseur le fournisseur de ballons vous informe ce matin d'un retard de 8 jours. David Chemin attend la livraison pour un événement sportif municipal prévu samedi. Romain Sauzet vous demande de gérer la situation.",contexte_pvoc:"M. Lambert (Comité 91 Handball) t'appelle : sa commande de 30 ballons était prévue pour ce vendredi — jour de son tournoi — et le transporteur vient de l'informer d'un retard de 3 jours. Il est très mécontent. Tu dois gérer cet appel entrant à distance.",activites:[{t:"Analyser et trouver une solution",q:["1.1  Évaluer l'impact de ce retard pour le client et pour LABORO (commercial, financier, relationnel).","1.2  Identifier les solutions possibles pour honorer la commande dans les délais."]},{t:"Agir et communiquer",q:["2.1  Choisir la meilleure solution et la justifier.","2.2  Rédiger le mail à David Chemin annonçant le retard et proposant la solution.","2.3  Rédiger le mail de réclamation à le fournisseur de ballons pour obtenir un geste commercial."]}],livrable:"Solution choisie justifiée + mail client + mail fournisseur",criteres:[{"c":"Traitement correct","i":"Je traite la commande en respectant les procédures et les données fournies"},{"c":"Vérification des données","i":"Je vérifie la cohérence des informations (quantités, prix, délais)"},{"c":"Communication client","i":"Je rédige une réponse client claire et professionnelle"}],reflexivite:0},
  {id:"M009",titre:"Implanter et animer le rayon chaussures",comp:"C4A.2",comp_ref:"C4A.2",objectif:"Dans cette mission, tu vas proposer des actions d'amélioration de l'attractivité de l'espace commercial LABORO en justifiant tes choix.",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",palier:2,option:"AGEC",contexte:"Romain Sauzet vous confie la réorganisation du rayon chaussures avant l'opération \"Printemps du Sport\". Objectif : augmenter de 20% les ventes de chaussures sport.",activites:[{t:"Concevoir l'implantation",q:["1.1  Rappeler les principes de merchandising à appliquer (niveaux, zones, facing).","1.2  Proposer un plan d'implantation pour les 4 références chaussures du catalogue LABORO en justifiant chaque choix."]},{t:"Préparer la communication",q:["2.1  Rédiger l'affiche PLV de l'opération \"Printemps du Sport\".","2.2  Proposer 3 facteurs d'ambiance adaptés à l'événement en justifiant chaque choix.","2.3  Comment évaluer le succès de cette opération ? Proposer 2 indicateurs."]}],livrable:"Plan d'implantation justifié + affiche PLV rédigée + 3 facteurs d'ambiance + 2 indicateurs",criteres:[{"c":"Diagnostic structuré","i":"Mon diagnostic distingue clairement les points forts et les axes d'amélioration"},{"c":"Propositions concrètes","i":"Mes propositions d'amélioration sont précises, réalisables et justifiées"},{"c":"Cohérence avec l'identité LABORO","i":"Les améliorations proposées respectent le positionnement sport & outdoor de LABORO"}],reflexivite:0},
  {id:"M014",titre:"Concevoir une opération de prospection",comp:"B4.2",comp_ref:"C4B.2",objectif:"Dans cette mission, tu vas concevoir les supports d'une opération de prospection — argumentaire, plan de découverte, outils de suivi.",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",palier:2,option:"PVOC",dossier:{l:"Données prospection CE — Essonne",rows:[["Entreprises > 200 salariés","~85 en Essonne"],["Budget sport moyen CE","8 000 à 15 000 €/an"],["CA moyen CE client LABORO","18 700 € HT/an"],["Taux de transformation actuel","12%"],["Panier moyen 1ère commande","2 400 € HT"],["Délai moyen de décision","3 semaines"]]},contexte:"Nina Chevalier vous confie la conception complète d'une opération de prospection ciblant les comités d'entreprise de l'Essonne. Objectif : signer 3 nouveaux contrats CE. Budget : 400 €. Durée : 6 semaines.",activites:[{t:"Concevoir l'opération",q:["1.1  Définir précisément la cible de l'opération (critères, nombre de prospects à contacter, zone).","1.2  Fixer les objectifs quantitatifs. Combien de prospects faut-il contacter pour espérer signer 3 contrats ?","1.3  Choisir les 2 techniques de prospection les plus adaptées et justifier chaque choix."]},{t:"Planifier et budgéter",q:["Quelles actions sont prioritaires les 2 premieres semaines d'un lancement de rayon ? Propose 3 actions concretes avec leur ordre de priorite.","2.2  Établir le budget détaillé en ventilant les 400 €.","Parmi ces indicateurs, lesquels sont les plus utiles pour piloter un rayon ? Coche les 3 meilleurs : A) CA par ml — B) Couleur du mobilier — C) Taux de rotation des stocks — D) Nombre de visiteurs — E) Marge brute"]}],livrable:"Définition de la cible + objectifs calculés + planning 6 semaines + budget ventilé + 4 indicateurs",criteres:[{"c":"Construction de l'argumentaire","i":"Mon argumentaire est structuré, adapté à la cible et met en valeur l'offre LABORO"},{"c":"Plan de découverte","i":"Mes questions de découverte sont ouvertes, pertinentes et logiquement ordonnées"},{"c":"Outils de suivi","i":"Les outils de suivi proposés sont adaptés et exploitables"}],reflexivite:0},
  {id:"M023",titre:"Concevoir la stratégie de veille commerciale de LABORO",comp:"C1.1",comp_ref:"C1.1",objectif:"Dans cette mission, tu vas exploiter une veille commerciale pour formuler des recommandations argumentées sur le positionnement produit ou prix de LABORO.",comp_libelle:"Bloc 1 — Assurer la veille commerciale",palier:3,option:"commun",contexte:"Pascal Berruelle constate que LABORO réagit à la concurrence plutôt qu'elle n'anticipe. Il vous confie la mise en place d'un dispositif de veille commerciale permanent. Budget : 300 € par an.",contexte_pvoc:"Pascal Berruelle te demande de concevoir le dispositif de veille commerciale B2B de LABORO pour la prochaine année. La veille doit couvrir : concurrents, prospects, évolution du marché CE/clubs/collectivités en Essonne.",activites:[{t:"Concevoir le dispositif",q:["1.1  Définir les 4 axes de veille prioritaires pour LABORO et, pour chacun : les informations à surveiller, les sources, la fréquence de veille.","1.2  Sélectionner et évaluer 5 outils numériques (gratuits ou < 300 €/an) permettant d'automatiser cette veille. Pour chacun : ce qu'il surveille, son intérêt, sa limite.","1.3  Construire le tableau de bord de veille : pour chaque axe surveillé, préciser la source retenue, la fréquence et le responsable. Présenter le résultat sous forme de tableau."]},{t:"Mettre en œuvre et pérenniser",q:["2.1  Rédiger le guide de veille destiné à l'équipe : indiquer les éléments indispensables qu'il doit contenir (sources, fréquence, format de rendu, responsable, circuit de diffusion) et justifier leur présence.","2.2  Analyser le positionnement concurrentiel de LABORO et proposer 3 arguments différenciateurs face aux concurrents identifiés.","2.3  Rédiger la note de synthèse à Pascal Berruelle présentant le dispositif de veille mis en place : sources, fréquence, bénéfices attendus, coût."]}],livrable:"Tableau des 4 axes + évaluation 5 outils + tableau de bord LABORO Connect + guide de veille + 3 arguments + rapport stratégique",criteres:[{"c":"Exploitation complète des données","i":"J'exploite toutes les informations pertinentes du dossier sans omission majeure"},{"c":"Analyse argumentée","i":"Mon analyse distingue faits, interprétations et recommandations"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont concrètes, réalisables et adaptées à LABORO"},{"c":"Rigueur professionnelle","i":"Le vocabulaire utilisé est celui d'un(e) professionnel(le) du commerce"}],reflexivite_q:"Quelles informations du dossier t'ont été les plus utiles pour construire ton analyse ? Qu'aurais-tu cherché en plus si tu avais eu plus de temps ?",reflexivite:3},
  {id:"M024",titre:"Piloter une vente complexe en contexte omnicanal",comp:"C1.2",comp_ref:"C1.2",objectif:"Dans cette mission, tu vas mener une vente omnicanale complexe en adaptant ton argumentation au profil client et en gérant les objections avec méthode.",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",palier:3,option:"commun",contexte:"M. Fontaine, directeur d'un centre de remise en forme de 450 membres à Évry, a contacté LABORO par mail, Instagram et téléphone simultanément. Il cherche à équiper ses 8 moniteurs et créer un corner running pour ses adhérents. Budget : 8 000 €. Romain Sauzet vous demande de gérer cette vente de A à Z.",contexte_pvoc:"Tu pilotes une vente complexe à distance avec ArianeGroup Massy — un CE de 2 800 salariés. La négociation dure depuis 3 semaines, implique plusieurs interlocuteurs et un contrat annuel de 25 000 €. Pascal Berruelle te demande de finaliser.",activites:[{t:"Gérer la vente omnicanale",q:["1.1  Analyser le potentiel commercial de ce prospect (CA immédiat et CA potentiel sur 3 ans).","1.2  Définir la stratégie de réponse omnicanale — dans quel ordre répondre aux 3 canaux, quel message adapter à chaque canal.","1.3  Rédiger la réponse au mail de M. Fontaine avec une proposition de rendez-vous."]},{t:"Construire la proposition et former",q:["2.1  Préparer la proposition commerciale complète pour les 2 besoins identifiés en respectant le budget de 8 000 €.","2.2  Identifier les objections possibles lors du RDV et préparer une réponse argumentée pour chacune.","2.3  Rédiger la fiche de formation destinée à Thomas Moreau expliquant les 6 enseignements clés de cette vente complexe."]}],livrable:"Analyse du potentiel + stratégie omnicanale + mail rédigé + proposition commerciale + réponses aux objections + fiche de formation",criteres:[{"c":"Adaptation au profil client","i":"Mon approche est clairement différenciée selon le profil (B2C/B2B, SONCAS identifié)"},{"c":"Maîtrise des techniques","i":"J'applique CAB, SONCAS et traitement des objections de façon fluide et cohérente"},{"c":"Gestion de la complexité","i":"Je gère correctement les situations imprévues ou les clients difficiles"},{"c":"Argumentation omnicanale","i":"J'intègre la dimension omnicanale (site, réseaux, showroom) dans la démarche de vente"}],reflexivite_q:"Si tu devais présenter ta technique de vente à un jury professionnel, quels arguments aurais-tu mis en avant ? Qu'aurais-tu pu faire différemment pour mieux cerner les besoins du client ?",reflexivite:3},
  {id:"M025",titre:"Concevoir la politique de gestion des réclamations",comp:"C2.2",comp_ref:"C2.3",objectif:"Dans cette mission, tu vas gérer des situations de réclamation complexes de façon autonome, en préservant la relation client et l'image de LABORO.",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",palier:3,option:"commun",dossier:{l:"Bilan réclamations — trimestre en cours",rows:[["Réclamations livraison e-commerce","7 cas — 39%"],["Réclamations défauts produits","5 cas — 28%"],["Réclamations erreurs de commande","4 cas — 22%"],["Réclamations délais non respectés","2 cas — 11%"],["Coût moyen réclamation","45 €"],["Clients perdus suite réclamation mal gérée","3 — CA perdu estimé 4 200 €"]]},contexte:"Pascal Berruelle constate une hausse des réclamations de +64% ce trimestre. Le taux de satisfaction post-réclamation est de 61% (objectif 80%). Il vous confie la conception d'une politique de gestion professionnelle.",contexte_pvoc:"Pascal Berruelle te demande de concevoir la politique de gestion des réclamations B2B de LABORO — applicable à distance (mail, téléphone) et en face-à-face. Elle doit couvrir tous les types de clients : CE, clubs, collectivités.",activites:[{t:"Analyser et concevoir la politique",q:["1.1  Identifier les 3 dysfonctionnements majeurs et calculer l'impact financier de chacun.","1.2  Concevoir la politique de gestion des réclamations LABORO — procédure par type, délai max, responsable, niveau de geste commercial autorisé.","1.3  Proposer des indicateurs de suivi avec objectifs cibles et fréquence de mesure."]},{t:"Former et pérenniser",q:["2.1  Calculer le coût annuel des réclamations si le rythme actuel se maintient. Comparer avec le coût d'une politique de prévention.","2.2  Rédiger le guide de traitement des réclamations destiné à toute l'équipe.","2.3  Rédiger le rapport complet destiné à Pascal Berruelle."]}],livrable:"Analyse des 3 dysfonctionnements + politique complète + indicateurs + calcul coût/bénéfice + guide de traitement + rapport",criteres:[{"c":"Gestion autonome de la complexité","i":"Je gère la réclamation de bout en bout sans aide, même dans une situation difficile"},{"c":"Maîtrise de la méthode","i":"ERESA est appliquée avec fluidité — sans lecture du support"},{"c":"Qualité argumentative","i":"Mon argumentaire est structuré, professionnel et adapté au contexte"},{"c":"Préservation de l'image LABORO","i":"Ma gestion préserve la réputation et la relation commerciale de LABORO"},{"c":"Propositions d'amélioration","i":"Je propose des actions pour éviter la récidive de ce type de réclamation"}],reflexivite_q:"Qu'est-ce qui te paraît le plus difficile dans la gestion d'une réclamation complexe ? Comment la méthode ERESA t'a-t-elle aidé à structurer ta réponse ?",reflexivite:3},
  {id:"SA1",titre:"Proposer et gérer la livraison à domicile",comp:"C2.1b",comp_ref:"C2.2",comp_libelle:"Bloc 2 — Mettre en œuvre le ou les services associés",objectif:"Dans cette mission, tu vas identifier les services associés proposés par LABORO et comprendre leur rôle dans la relation client.",palier:1,option:"commun",dossier:{l:"Offre de livraison LABORO",rows:[["Standard transporteur partenaire 48h","6,90 €"],["Express transporteur partenaire 24h","12,90 €"],["Click & collect showroom Évry","Gratuit — 2h si en stock"],["Livraison poids > 30 kg","Sur devis — transporteur palettes"],["Zone de livraison","France métropolitaine + DOM"]]},contexte:"Marco Pellini vous demande de gérer les demandes de livraison de la journée sur laboro-sport.fr. Trois clients ont des situations différentes nécessitant un conseil personnalisé.",contexte_pvoc:"Un client B2B (Mairie d'Évry) passe une commande de matériel sportif sur laboro-sport.fr et demande la livraison directement au gymnase municipal. Nina Chevalier te demande de gérer l'ensemble du processus de livraison à distance.",activites:[{t:"Comprendre les services de livraison",q:["1.1  Lis le dossier. Quels modes de livraison LABORO propose-t-il ? Cite-les tous avec leur délai approximatif.","1.2  M. Bensalah commande un vélo de ville. Parmi ces options de livraison, laquelle proposes-tu et pourquoi ? A) Retrait en magasin sous 24h — B) Livraison à domicile sous 5 jours — C) Livraison express sous 48h.","1.3  Quel est le prix de la livraison à domicile chez LABORO ? Trouve la réponse dans le dossier."]},{t:"Gérer un retard de livraison",q:["2.1  La livraison du vélo de M. Bensalah est retardée de 3 jours. Dans quel ordre fais-tu ces actions ? A) Proposer une compensation — B) Contacter M. Bensalah — C) Vérifier la nouvelle date avec le transporteur — D) Informer Romain Sauzet.","2.2  Complète ce SMS à envoyer à M. Bensalah : 'Bonjour M. Bensalah, voici LABORO. Votre ___ prévu le ___ est retardé au ___. Nous vous présentons nos ___. En compensation, nous vous offrons ___. Cordiales salutations.'","2.3  Pourquoi est-il important de prévenir rapidement un client en cas de retard ? Donne 2 raisons."]}],livrable:"Modes de livraison identifiés + SMS de retard complété",criteres:[{"c":"Identification des services","i":"Je cite les services associés proposés par LABORO et décris leur utilité"},{"c":"Lien avec le produit","i":"Je fais le lien entre le produit vendu et les services associés pertinents"},{"c":"Compréhension des enjeux","i":"J'explique l'intérêt des services associés pour LABORO et pour le client"}],reflexivite:0},
  {id:"SA2",titre:"Coordonner une commande de textile personnalisé",comp:"C2.1b",comp_ref:"C2.2",objectif:"Dans cette mission, tu vas proposer et mettre en œuvre des services associés adaptés aux besoins du client dans le contexte LABORO.",comp_libelle:"Bloc 2 — Mettre en œuvre le ou les services associés",palier:2,option:"commun",dossier:{l:"Commande textile — CE PSA Stellantis",rows:[["Client","Isabelle Faure — CE PSA Stellantis"],["Produit","Maillot notre atelier de flocage polyester"],["Quantité","40 unités"],["Personnalisation","Logo PSA brodé poitrine + prénom floqué dos"],["Budget","≤ 35 € TTC/unité"],["Délai requis","3 semaines — événement sportif"],["Prestataire","notre atelier de flocage — délai standard 3 sem. broderie, 2 sem. flocage"]]},contexte:"Isabelle Faure commande 40 maillots personnalisés pour le challenge sportif annuel du CE PSA Stellantis. Nina Chevalier vous confie la coordination complète de cette commande.",contexte_pvoc:"Le CE PSA Stellantis commande 40 maillots flocage pour son tournoi inter-services. La commande est passée par mail. Tu dois coordonner à distance toutes les étapes : validation maquette, suivi notre atelier de flocage, confirmation livraison.",activites:[{t:"Comprendre la commande",q:["1.1  Lis le dossier. Quels articles Isabelle Faure souhaite-t-elle commander ? Liste les avec les quantites.","1.2  Quel est le budget total autorise pour cette commande ? Trouve la reponse dans le dossier.","1.3  Parmi ces informations, lesquelles sont indispensables avant de lancer la commande ? Coche les 3 plus importantes : A) Le nom du fournisseur — B) La quantite exacte — C) La couleur preferee du client — D) La date de livraison souhaitee — E) Le logo a imprimer."]},{t:"Suivre la commande",q:["2.1  La commande est confirmee. Dans quel ordre realises-tu ces actions ? Remets-les dans l'ordre : A) Envoyer la confirmation a Isabelle Faure — B) Verifier que le bon de commande est complet — C) Transmettre la commande au fournisseur — D) Noter la date de livraison prevue.","2.2  Complete ce SMS de confirmation a envoyer a Isabelle Faure : 'Bonjour Mme Faure, votre commande de ___ a bien ete ___ aupres de notre atelier de flocage. Livraison prevue le ___. Cordiales salutations, ___ LABORO.'"]}],livrable:"Articles commandés listés + SMS de confirmation complété",criteres:[{"c":"Proposition adaptée","i":"Je propose des services associés en cohérence avec les besoins du client"},{"c":"Argumentation","i":"Ma proposition est argumentée en termes de valeur ajoutée pour le client"},{"c":"Mise en œuvre","i":"Je décris correctement les modalités de mise en œuvre du service proposé"}],reflexivite:0},
  {id:"SA3",titre:"Évaluer et améliorer les services associés",comp:"C2.1b",comp_ref:"C2.2",objectif:"Dans cette mission, tu vas construire une offre de services associés argumentée, en lien avec la politique commerciale de LABORO.",comp_libelle:"Bloc 2 — Mettre en œuvre le ou les services associés",palier:3,option:"commun",dossier:{l:"Bilan services associés — semestre",rows:[["Livraisons gérées","187"],["Livraisons en retard","22 — taux 11,8%"],["Réclamations livraison","14 — délai moyen résolution 3,2 jours"],["Commandes textile perso","28"],["Erreurs flocage/broderie","3 — taux 10,7%"],["Satisfaction services","3,6/5"],["Coût des erreurs","Avoir moyen accordé : 180 €/erreur"]]},contexte:"Pascal Berruelle vous demande d'analyser les performances des services associés du semestre et de proposer un plan d'amélioration. Ces services représentent 18% du CA de LABORO.",contexte_pvoc:"Pascal Berruelle te demande d'évaluer la qualité des services associés proposés aux clients B2B de LABORO (livraison, textile personnalisé, installation) et de proposer des axes d'amélioration basés sur les retours clients.",activites:[{t:"Analyser les performances",q:["1.1  Identifier les 2 dysfonctionnements majeurs et calculer leur impact financier total sur le semestre.","1.2  Comparer le taux de satisfaction 3,6/5 à l'objectif LABORO de 4/5. Quels facteurs expliquent cet écart ?","1.3  Proposer un tableau de bord de suivi des services associés avec 5 indicateurs clés, leur formule et leur objectif cible."]},{t:"Construire le plan d'amélioration",q:["2.1  Pour chacun des 2 dysfonctionnements, proposer 2 actions correctives réalistes avec délai de mise en oeuvre et responsable.","2.2  Rédiger le rapport de synthèse destiné à Pascal Berruelle — 15 à 20 lignes — incluant le bilan, les causes et le plan d'action."]}],livrable:"Calcul impact financier × 2 + tableau de bord 5 indicateurs + 4 actions correctives + rapport de synthèse",criteres:[{"c":"Offre complète","i":"L'offre de services associés est complète et adaptée au profil du client"},{"c":"Argumentation experte","i":"Mon argumentation est convaincante et valorise l'expérience client globale"},{"c":"Faisabilité","i":"La mise en œuvre proposée est réaliste pour LABORO"}],reflexivite_q:"En quoi les services associés contribuent-ils à l'expérience client globale de LABORO ? Comment les valoriser sans que ça paraisse forcé ?",reflexivite:3},
  {id:"M015",titre:"Optimiser l'implantation du rayon chaussures",comp:"C4A.2",comp_ref:"C4A.2",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",objectif:"Dans cette mission, tu vas proposer des actions d'amélioration de l'attractivité de l'espace commercial LABORO en justifiant tes choix.",palier:2,option:"AGEC",dossier:{l:"Indicateurs rayon chaussures/sport — mois en cours",rows:[["CA rayon chaussures","8 200 € — +12% vs N-1"],["Produit le plus vendu","Chaussures running EasyRun — 34 unités"],["Produit en perte de vitesse","Chaussures running EasyRun — 4 unités"],["Taux de rupture","8% — objectif 0%"],["Panier moyen","162 €"],["Nombre de clients rayon","187 ce mois"]]},contexte:"Romain Sauzet prépare l'opération 'Printemps du Sport' pour booster les ventes d'avril. Il vous demande d'analyser les performances actuelles du rayon et de proposer une nouvelle implantation.",activites:[{t:"Analyser et diagnostiquer",q:["1.1  Analyser les indicateurs du rayon : identifier 2 points forts et 2 points d'amélioration.","1.2  À partir des données, quels produits placer en zone chaude et au niveau des yeux ? Justifie avec les règles du merchandising.","1.3  Le Chaussures running EasyRun stagne. Proposer 2 actions pour relancer ses ventes sans brader le prix."]},{t:"Concevoir et mettre en oeuvre",q:["2.1  Proposer un plan d'implantation pour les 4 références chaussures en précisant : zone, niveau et facing pour chacune.","2.2  Rédiger l'affiche PLV de l'opération Printemps du Sport (accroche + offre + durée).","2.3  Définir 2 indicateurs pour mesurer l'impact de la nouvelle implantation au bout de 4 semaines."]}],livrable:"Diagnostic 2+2 + plan d'implantation justifié + affiche PLV + 2 indicateurs",criteres:[{"c":"Diagnostic structuré","i":"Mon diagnostic distingue clairement les points forts et les axes d'amélioration"},{"c":"Propositions concrètes","i":"Mes propositions d'amélioration sont précises, réalisables et justifiées"},{"c":"Cohérence avec l'identité LABORO","i":"Les améliorations proposées respectent le positionnement sport & outdoor de LABORO"}],reflexivite:0},
  {id:"M016",titre:"Développer la clientèle du showroom",comp:"C4A.3",comp_ref:"C4A.3",objectif:"Dans cette mission, tu vas identifier les actions de développement de la clientèle mises en œuvre par LABORO et analyser leur pertinence.",comp_libelle:"Bloc 4A — Développer la clientèle",palier:2,option:"AGEC",dossier:{l:"Données attractivité showroom",rows:[["Visiteurs/semaine","~140"],["Taux de transformation","34%"],["Panier moyen","162 €"],["Clients fidèles (> 2 achats/an)","38%"],["Source de trafic n°1","Bouche à oreille 44%"],["Avis Google","4,1/5 — 118 avis"]]},contexte:"Romain Sauzet constate que le showroom d'Évry attire des visiteurs mais que le taux de transformation stagne à 34%. Il vous demande de proposer un plan de développement de la clientèle.",activites:[{t:"Diagnostiquer et cibler",q:["1.1  Analyser les données du showroom : identifier 2 opportunités de développement non exploitées.","1.2  Quelles actions permettraient d'améliorer le taux de transformation de 34% à 40% ? Proposer 3 actions concrètes."]},{t:"Planifier et budgéter",q:["2.1  Choisir 2 des 3 actions proposées et établir pour chacune : objectif, délai, responsable, coût estimé.","2.2  Rédiger la proposition à soumettre à Pascal Berruelle pour obtenir son accord — 10 à 15 lignes.","2.3  Comment mesurer l'efficacité de ces 2 actions au bout de 3 mois ? Proposer 2 indicateurs chiffrés."]}],livrable:"Diagnostic 2 opportunités + 3 actions + plan 2 actions + proposition Pascal + 2 indicateurs",criteres:[{"c":"Identification des actions","i":"Je décris correctement les actions de développement clientèle mises en œuvre par LABORO"},{"c":"Analyse de pertinence","i":"J'évalue la pertinence des actions en m'appuyant sur des critères explicites"},{"c":"Propositions d'amélioration","i":"Je propose au moins une amélioration concrète et justifiée"}],reflexivite:0},
  {id:"M017",titre:"Rechercher des informations pour prospecter",comp:"B4.1",comp_ref:"C4B.1",objectif:"Dans cette mission, tu vas identifier les sources d'information utiles à la prospection commerciale et comprendre les enjeux de la prospection B2B pour LABORO.",comp_libelle:"Bloc 4B — Rechercher et analyser les informations à des fins d’exploitation",palier:1,option:"PVOC",contexte:"Nina Chevalier vous demande de préparer une liste de prospects B2B à contacter pour développer le portefeuille clients de LABORO en Essonne. Vous devez identifier des entreprises et associations susceptibles d'acheter régulièrement des équipements sportifs.",activites:[{t:"Identifier les sources et collecter",q:["1.1  Lister 5 sources d'information utilisables pour trouver des prospects B2B en Essonne. Pour chaque source, indiquer quel type de prospect elle permet de trouver.","1.2  À partir de ces sources, identifier 3 prospects potentiels (autres que ceux déjà dans le fichier LABORO) avec pour chacun : nom, secteur, contact potentiel, besoins estimés."]},{t:"Qualifier et organiser",q:["2.1  Pour chacun des 3 prospects identifiés, appliquer la méthode BANT pour évaluer leur potentiel.","2.2  Classer les 3 prospects par ordre de priorité en justifiant. Lequel contacter en premier et pourquoi ?","2.3  Saisir les informations dans LABORO Connect — lister les champs à renseigner pour chaque prospect."]}],livrable:"5 sources listées + 3 prospects identifiés + qualification BANT + classement justifié + fiche LABORO Connect",criteres:[{"c":"Identification des sources","i":"Je cite les sources d'information utiles pour préparer une prospection B2B"},{"c":"Compréhension des enjeux","i":"J'explique pourquoi la prospection est essentielle pour le développement de LABORO"},{"c":"Lecture du fichier prospects","i":"Je lis et décris correctement les données du fichier prospects fourni"}],reflexivite:0},
  {id:"M018",titre:"Préparer un plan de prospection téléphonique",comp:"B4.2",comp_ref:"C4B.2",objectif:"Dans cette mission, tu vas identifier les étapes d'une opération de prospection et comprendre les outils utilisés par les commerciaux de LABORO.",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",palier:1,option:"PVOC",dossier:{l:"Fiche prospect — Comité dép. 91 Handball",rows:[["Contact","Pierre Lambert — responsable achats"],["Structure","Comité départemental 91 — 42 clubs affiliés"],["Besoins estimés","Ballons, filets, équipements d'entraînement"],["Budget estimé","5 000 à 10 000 €/an"],["Statut","Prospect froid — identifié forum sport Essonne"],["Dernier contact","Aucun pour l'instant"]]},contexte:"Nina Chevalier vous confie la prise de contact téléphonique avec Pierre Lambert du Comité 91 Handball. C'est votre premier appel — il ne vous connaît pas encore.",activites:[{t:"Préparer l'appel",q:["1.1  Quelles informations rassembler avant d'appeler Pierre Lambert pour être crédible et pertinent(e) ?","Un plan d'appel a 5 etapes. Remets dans l'ordre : A) Proposition — B) Accroche — C) Conclusion — D) Presentation — E) Decouverte"]},{t:"Anticiper et conclure",q:["2.1  Pierre Lambert dit : 'On travaille déjà avec Decathlon, ça me convient.' Rédiger ta réponse complète à cette objection.","2.2  Il accepte un rendez-vous. Rédiger le mail de confirmation du RDV envoyé dans l'heure.","2.3  Quelles informations saisir dans LABORO Connect immédiatement après l'appel ?"]}],livrable:"Plan d'appel rédigé + réponse à l'objection + mail de confirmation + mise à jour LABORO Connect",criteres:[{"c":"Identification des étapes","i":"Je décris correctement les étapes d'une opération de prospection"},{"c":"Connaissance des outils","i":"Je cite les outils utilisés par les commerciaux LABORO pour prospecter"},{"c":"Compréhension de l'argumentaire","i":"Je décris les éléments clés d'un argumentaire de prospection"}],reflexivite:0},
  {id:"M019",titre:"Concevoir un support de prospection",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas concevoir les supports d'une opération de prospection — argumentaire, plan de découverte, outils de suivi.",palier:2,option:"PVOC",dossier:{l:"Données pour l'offre clubs sportifs",rows:[["Remise clubs > 10 unités","8%"],["Remise clubs > 30 unités","12%"],["Remise clubs > 50 unités","15%"],["Délai livraison standard","48h"],["Service flocage","Inclus — délai 3 semaines"],["Carte fidélité LABORO PRO","Accès au showroom hors heures ouverture"]]},contexte:"Nina Chevalier vous demande de concevoir un e-mailing de prospection ciblant les clubs sportifs de l'Essonne qui ne sont pas encore clients de LABORO. Objectif : obtenir 5 RDV en 3 semaines.",activites:[{t:"Définir la cible et le message",q:["1.1  Définir précisément la cible de l'e-mailing — type de clubs, taille, zone géographique, critères d'exclusion.","1.2  Quel message clé différenciera LABORO de Decathlon aux yeux d'un responsable de club sportif ? Formuler 3 arguments principaux."]},{t:"Rédiger et planifier",q:["2.1  Rédiger l'e-mailing complet : objet (< 6 mots), accroche, corps du message, call-to-action, signature. Maximum 150 mots.","2.2  Définir 3 indicateurs pour mesurer l'efficacité de cet e-mailing avec leur formule et objectif cible.","2.3  Si le taux d'ouverture est de 22% et le taux de clic de 4%, combien de RDV espères-tu obtenir sur 200 envois ? Calcule et analyse."]}],livrable:"Définition cible + 3 arguments + e-mailing rédigé + 3 indicateurs + calcul de projection",criteres:[{"c":"Construction de l'argumentaire","i":"Mon argumentaire est structuré, adapté à la cible et met en valeur l'offre LABORO"},{"c":"Plan de découverte","i":"Mes questions de découverte sont ouvertes, pertinentes et logiquement ordonnées"},{"c":"Outils de suivi","i":"Les outils de suivi proposés sont adaptés et exploitables"}],reflexivite:0},
  {id:"M020",titre:"Mettre en oeuvre la prospection terrain",comp:"B4.3",comp_ref:"C4B.3",objectif:"Dans cette mission, tu vas mettre en œuvre une action de prospection téléphonique ou physique en appliquant les techniques LABORO.",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",palier:2,option:"PVOC",dossier:{l:"Tournée prospection — Massy/Palaiseau/Orsay",rows:[["RDV 9h00","MJC de Massy — Sport municipal — Camille Dufour"],["RDV 11h00","AS Palaiseau Football — 280 licenciés — M. Moreau"],["RDV 14h00","Lycée Blaise Pascal Orsay — Mme Roussel (déjà cliente)"],["RDV 16h00","CE Thales Massy — Isabelle Faure — 850 salariés"],["Budget déplacement","65 € (véhicule LABORO)"],["Objectif","2 devis signés ou confirmés"]]},contexte:"Nina Chevalier vous envoie faire votre première tournée de prospection terrain dans le secteur Massy-Palaiseau-Orsay. Vous avez 4 RDV dans la journée.",activites:[{t:"Préparer la tournée",q:["1.1  Pour chacun des 4 RDV, préparer une accroche personnalisée de 2-3 phrases adaptée au profil du contact.","1.2  Quels documents et supports emporter pour être efficace lors de ces 4 visites ?"]},{t:"Analyser et capitaliser",q:["2.1  Au RDV 11h, M. Moreau (AS Palaiseau) est intéressé par des maillots flocage pour 85 joueurs. Établir le devis rapidement et calculer le montant HT et TTC.","2.2  Mme Roussel (Lycée Pascal) commande à nouveau 15 ballons Pro Match T5. Comment transformes-tu ce contact en opportunité de vente additionnelle ?","2.3  En fin de tournée, rédiger le compte-rendu de visite pour Nina Chevalier — résultats obtenus, suites à donner, impression générale."]}],livrable:"4 accroches personnalisées + documents listés + devis AS Palaiseau + vente additionnelle Lycée + compte-rendu",criteres:[{"c":"Prise de contact structurée","i":"Ma prise de contact respecte les étapes (présentation, accroche, objet de l'appel)"},{"c":"Qualification réussie","i":"J'obtiens les informations clés pour qualifier le prospect"},{"c":"Gestion des objections","i":"Je traite les objections courantes (pas le temps, pas intéressé) avec méthode"}],reflexivite:0},
  {id:"M021",titre:"Assurer le suivi de la prospection",comp:"B4.4",comp_ref:"C4B.4",objectif:"Dans cette mission, tu vas analyser les résultats d'une action de prospection à partir des indicateurs fournis et identifier les écarts.",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",palier:2,option:"PVOC",dossier:{l:"Bilan prospection — 3 semaines d'opération",rows:[["Prospects contactés","28"],["RDV obtenus","9 — taux 32%"],["Devis envoyés","6"],["Devis signés","2 — CA : 3 400 € HT"],["Devis en attente","4 — CA potentiel 8 200 € HT"],["Relances effectuées","3 sur 4 en attente"],["Objectif initial","3 contrats signés"]]},contexte:"Nina Chevalier vous demande de faire le bilan de votre opération de prospection sur 3 semaines et de relancer les prospects qui n'ont pas encore répondu.",activites:[{t:"Analyser les résultats",q:["1.1  Calculer le taux de transformation prospects-clients. Comparer à l'objectif initial. L'opération est-elle un succès ? Justifie.","1.2  Pour les 4 devis en attente, proposer une stratégie de relance différenciée selon le délai écoulé depuis l'envoi du devis."]},{t:"Relancer et capitaliser",q:["2.1  Rédiger le mail de relance pour le CE Thales (devis de 4 800 € HT envoyé il y a 10 jours sans réponse).","2.2  Rédiger le rapport de fin d'opération pour Nina Chevalier — résultats, analyse des causes, recommandations pour la prochaine opération."]}],livrable:"Calcul taux de transformation + stratégie de relance différenciée + mail relance CE Thales + rapport",criteres:[{"c":"Calcul des indicateurs","i":"Je calcule correctement les indicateurs demandés"},{"c":"Analyse des écarts","i":"Mon analyse des écarts est structurée et s'appuie sur les données"},{"c":"Formulation de recommandations","i":"Je propose au moins 2 recommandations concrètes pour améliorer les résultats"}],reflexivite:0},
  {id:"M022",titre:"Valoriser l'offre LABORO face à la concurrence",comp:"B4.5",comp_ref:"C4B.5",objectif:"Dans cette mission, tu vas construire une offre commerciale argumentée adaptée à un client B2B de LABORO.",comp_libelle:"Bloc 4B — Valoriser les produits et/ou les services",palier:2,option:"PVOC",dossier:{l:"Comparatif LABORO vs concurrents sur le marché clubs",rows:[["Critère","LABORO","Decathlon Pro","SportRun Pro"],["Prix maillots flocage","28 €/u","24 €/u","31 €/u"],["Délai flocage","3 semaines","5 semaines","2 semaines"],["Remise clubs","8-15%","5-10%","7-12%"],["Conseil personnalisé","Oui — commercial dédié","Non","Partiellement"],["Livraison domicile","Oui 48h","Oui 72h","Non"],["Showroom physique","Évry — ouvert 6j/7","Non","Oui — Massy"]]},contexte:"Lors d'un RDV avec Marc Girault (Club Sportif Forêt de Sénart), il vous présente une offre de Decathlon Pro : maillots à 24 € l'unité, remise 10% dès 20 unités. Il hésite à choisir LABORO.",activites:[{t:"Analyser et préparer l'argumentation",q:["1.1  Analyser le comparatif. Sur quels critères LABORO est-il objectivement supérieur à Decathlon Pro ?","1.2  Marc Girault a besoin de 20 maillots flocage. Calculer le prix LABORO avec remise club et comparer à Decathlon Pro.","1.3  Construire la proposition de valeur LABORO en 5 arguments face à Decathlon Pro pour ce client-type."]},{t:"Défendre l'offre et conclure",q:["2.1  Marc Girault dit : 'LABORO c'est 80 € de plus pour la même chose.' Rédiger ta réponse argumentée complète.","2.2  Proposer une offre commerciale d'entrée de gamme qui permettrait de gagner Marc Girault sans sacrifier la marge."]}],livrable:"Analyse comparatif + calcul prix + 5 arguments de valeur + réponse à l'objection prix + offre d'entrée",criteres:[{"c":"Structure de l'offre","i":"Mon offre est complète et bien structurée (présentation, produits, prix, conditions)"},{"c":"Argumentation","i":"L'offre met en valeur les points forts de LABORO adaptés aux besoins du client"},{"c":"Présentation professionnelle","i":"La présentation est claire, professionnelle et adaptée à un client B2B"}],reflexivite:0},
  {id:"M026",titre:"Piloter l'exécution d'une vente complexe",comp:"C1.3",comp_ref:"C1.3",objectif:"Dans cette mission, tu vas gérer de façon autonome l'ensemble des opérations post-vente dans des situations complexes ou omnicanales.",comp_libelle:"Bloc 1 — Assurer l’exécution de la vente",palier:3,option:"commun",dossier:{l:"Commande Mairie d'Évry-Courcouronnes",rows:[["Commande","50 ballons Pro Match T5 + 20 filets + livraison"],["Montant","4 850 € HT"],["Mode de règlement","Bon de commande public — paiement 30 jours"],["Livraison","Gymnase municipal — date imposée : vendredi"],["Contact","David Chemin — responsable achats"],["Contraintes","Bons de livraison en 3 exemplaires, facture pro forma requise"]]},contexte:"Pascal Berruelle vous confie la gestion complète de la commande de la Mairie d'Évry. C'est un compte stratégique pour LABORO — aucune erreur n'est permise.",contexte_pvoc:"Tu pilotes l'exécution d'une commande complexe à distance pour le Lycée Blaise Pascal d'Orsay : 85 maillots flocage + 20 ballons, livraison à date imposée, bon de commande public, paiement 30 jours. Pascal Berruelle compte sur toi.",activites:[{t:"Sécuriser la transaction",q:["1.1  Quelles particularités d'une vente à une collectivité publique dois-tu connaître (bons de commande, délai de paiement, TVA) ?","1.2  Préparer la checklist complète des documents à fournir à la Mairie d'Évry pour cette commande.","1.3  Vérifier la disponibilité des 50 ballons Pro Match T5 en stock. Le stock actuel est de 31 unités. Comment gères-tu l'écart ?"]},{t:"Livrer et fidéliser",q:["2.1  Rédiger le mail de confirmation de commande et de livraison envoyé à David Chemin.","2.2  Comment transformer cette livraison en opportunité commerciale pour les prochains achats de la Mairie ?"]}],livrable:"Analyse vente collectivité + checklist documents + solution stock + mail confirmation + plan fidélisation",criteres:[{"c":"Gestion autonome","i":"Je gère l'ensemble des opérations post-vente de façon autonome, même dans des situations complexes"},{"c":"Maîtrise des procédures","i":"Toutes les procédures sont appliquées correctement et dans le bon ordre"},{"c":"Qualité des documents","i":"Les documents produits sont professionnels et sans erreur"},{"c":"Anticipation des problèmes","i":"Je repère et traite les anomalies avant qu'elles n'affectent la relation client"}],reflexivite_q:"Quelles procédures post-vente t'ont semblé les plus complexes à appliquer ? Comment éviter les erreurs dans ces étapes ?",reflexivite:3},
  {id:"M027",titre:"Manager la politique de réclamations",comp:"C2.2",comp_ref:"C2.3",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",objectif:"Dans cette mission, tu vas gérer des situations de réclamation complexes de façon autonome, en préservant la relation client et l'image de LABORO.",palier:3,option:"commun",dossier:{l:"Réclamations — mois en cours",rows:[["Total réclamations","18"],["Livraison e-commerce","7 — 39%"],["Défauts produits","5 — 28%"],["Erreurs commande","4 — 22%"],["Délais non respectés","2 — 11%"],["Délai moyen traitement","3,8 jours"],["Taux satisfaction post-réclamation","63% — objectif 80%"]]},contexte:"Pascal Berruelle vous demande de prendre en charge la gestion des réclamations du mois et de proposer un plan pour atteindre l'objectif de 80% de satisfaction post-réclamation.",contexte_pvoc:"Nina Chevalier te demande de concevoir et de mettre en oeuvre la politique de gestion des réclamations B2B de LABORO sur l'ensemble du portefeuille clients — CE, clubs, collectivités — en tenant compte des spécificités de la relation commerciale à distance.",activites:[{t:"Analyser et prioriser",q:["1.1  Identifier le dysfonctionnement prioritaire à traiter. Calculer son coût réel pour LABORO (impact CA, image, fidélisation).","1.2  Proposer une procédure standardisée de traitement des réclamations livraison — étapes, délais, responsables, compensations autorisées.","1.3  Concevoir un indicateur de pilotage hebdomadaire pour Pascal Berruelle."]},{t:"Mettre en oeuvre",q:["2.1  Rédiger le guide de traitement des réclamations destiné à toute l'équipe LABORO.","2.2  Rédiger le rapport mensuel réclamations destiné à Pascal Berruelle."]}],livrable:"Diagnostic + calcul coût + procédure livraison + indicateur hebdo + guide équipe + rapport mensuel",criteres:[{"c":"Gestion autonome de la complexité","i":"Je gère la réclamation de bout en bout sans aide, même dans une situation difficile"},{"c":"Maîtrise de la méthode","i":"ERESA est appliquée avec fluidité — sans lecture du support"},{"c":"Qualité argumentative","i":"Mon argumentaire est structuré, professionnel et adapté au contexte"},{"c":"Préservation de l'image LABORO","i":"Ma gestion préserve la réputation et la relation commerciale de LABORO"},{"c":"Propositions d'amélioration","i":"Je propose des actions pour éviter la récidive de ce type de réclamation"}],reflexivite_q:"Qu'est-ce qui te paraît le plus difficile dans la gestion d'une réclamation complexe ? Comment la méthode ERESA t'a-t-elle aidé à structurer ta réponse ?",reflexivite:3},
  {id:"M028",titre:"Piloter la satisfaction client de LABORO",comp:"C2.3",comp_ref:"C2.4",objectif:"Dans cette mission, tu vas concevoir et exploiter un dispositif de mesure de la satisfaction client adapté au contexte LABORO.",comp_libelle:"Bloc 2 — S’assurer de la satisfaction du client",palier:3,option:"commun",dossier:{l:"Données satisfaction — trimestre",rows:[["Répondants","247 clients"],["Taux de satisfaction","71% — objectif 80%"],["NPS","+ 8"],["Principal grief","Délais e-commerce 41%"],["Note showroom","4,3/5"],["Note e-commerce","3,4/5"],["Taux de réponse enquête","21%"]]},contexte:"Marco Pellini vous présente les résultats de satisfaction du trimestre. Pascal Berruelle attend un plan d'action pour atteindre 80% avant la fin de l'année.",contexte_pvoc:"Marco Pellini te confie le pilotage de la satisfaction des clients B2B de LABORO. Il te demande de concevoir le dispositif de mesure, d'analyser les résultats et de proposer un plan d'amélioration ciblé sur les clients CE et collectivités.",activites:[{t:"Analyser finement les résultats",q:["1.1  Interpréter le NPS de +8. Calculer le taux de promoteurs nécessaire pour atteindre un NPS de +20.","1.2  L'écart showroom (4,3) vs e-commerce (3,4) est significatif. Identifier 3 causes probables et pour chacune proposer une action corrective.","1.3  Le taux de réponse de 21% est insuffisant. Proposer 3 techniques pour le doubler au prochain trimestre."]},{t:"Construire le plan d'action",q:["2.1  Définir 4 actions prioritaires pour passer de 71% à 80% de satisfaction — chacune avec responsable, délai et indicateur de mesure.","2.2  Rédiger le rapport complet destiné à Pascal Berruelle."]}],livrable:"Interprétation NPS + 3 causes/actions e-commerce + techniques taux de réponse + 4 actions plan + rapport",criteres:[{"c":"Conception du dispositif","i":"Le dispositif proposé est cohérent avec les objectifs et les contraintes de LABORO"},{"c":"Maîtrise des indicateurs","i":"Je calcule et interprète tous les indicateurs avec précision"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont priorisées, justifiées et réalisables"},{"c":"Vision client","i":"Mon analyse place le client au centre et fait le lien avec la fidélisation"}],reflexivite_q:"Que révèlent les résultats d'une enquête de satisfaction sur les priorités d'amélioration de LABORO ? Quelles limites vois-tu à ce type d'outil ?",reflexivite:3},
  {id:"M029",titre:"Construire un programme de fidélisation",comp:"C3.2",comp_ref:"C3.2",objectif:"Dans cette mission, tu vas construire et évaluer un programme de fidélisation complet pour LABORO, en justifiant les choix effectués.",comp_libelle:"Bloc 3 — Contribuer à des actions de fidélisation de la clientèle et de développement de la relation client",palier:3,option:"commun",dossier:{l:"Données fidélisation LABORO",rows:[["Clients actifs","3 200"],["Clients ayant acheté 2x ou plus","38% — soit 1 216 clients"],["CA clients fidèles","68% du CA total"],["Coût d'acquisition nouveau client","~85 €"],["Coût de rétention client existant","~17 €"],["Taux d'attrition","22% — objectif < 15%"]]},contexte:"Pascal Berruelle veut structurer la politique de fidélisation de LABORO. Il vous confie la conception d'un programme complet pour réduire le taux d'attrition de 22% à 15%.",contexte_pvoc:"Pascal Berruelle te demande de construire le programme de fidélisation B2B de LABORO pour l'année N+1 — couvrant les 24 clients actifs avec des actions différenciées selon leur potentiel.",activites:[{t:"Concevoir le programme",q:["1.1  Calculer combien de clients LABORO perd chaque année avec un taux d'attrition de 22%. Calculer le CA perdu estimé.","1.2  Proposer 3 niveaux de fidélisation adaptés aux différents profils clients LABORO (B2C occasionnel, B2C régulier, B2B).","1.3  Pour chaque niveau, définir : avantages concrets, critères d'accès, coût estimé pour LABORO."]},{t:"Planifier et mesurer",q:["2.1  Établir le calendrier de déploiement du programme sur 12 mois.","2.2  Définir 5 indicateurs de pilotage avec formule, objectif et fréquence.","2.3  Rédiger la note stratégique à Pascal Berruelle pour obtenir son accord et le budget nécessaire."]}],livrable:"Calcul CA perdu + 3 niveaux de fidélisation + calendrier 12 mois + 5 indicateurs + note stratégique",criteres:[{"c":"Cohérence du programme","i":"Le programme de fidélisation forme un ensemble cohérent et progressif"},{"c":"Argumentation complète","i":"Chaque composante est justifiée par des données ou des arguments solides"},{"c":"Évaluation prévue","i":"Je définis des indicateurs précis pour mesurer l'efficacité du programme"},{"c":"Orientation client","i":"Le programme est centré sur la valeur apportée au client, pas uniquement sur les ventes"}],reflexivite_q:"Qu'est-ce qui distingue une action de fidélisation efficace d'une simple promotion ? Comment mesurer réellement la fidélité d'un client LABORO ?",reflexivite:3},
  {id:"M030",titre:"Concevoir et piloter une action de fidélisation",comp:"C3.3",comp_ref:"C3.3",objectif:"Dans cette mission, tu vas élaborer et piloter une stratégie digitale cohérente pour LABORO en intégrant les réseaux sociaux et les outils e-commerce.",comp_libelle:"Bloc 3 — Évaluer les actions de fidélisation de la clientèle et de développement de la relation client",palier:3,option:"commun",dossier:{l:"Soirée Rentrée Sportive — bilan",rows:[["Invités","50 clients"],["Présents","38 — taux présence 76%"],["CA généré le soir","4 200 € HT"],["CA généré les 30j suivants (clients présents)","11 800 € HT"],["Coût total de l'événement","1 200 €"],["NPS mesuré 15j après","+ 42 vs + 8 avant"],["Clients convertis de 1 achat à 2+ achats","7"]]},contexte:"Pascal Berruelle vous demande d'évaluer rigoureusement la soirée Rentrée Sportive et de décider si LABORO doit la reconduire, l'adapter ou la remplacer par une autre action.",contexte_pvoc:"Nina Chevalier te confie la coordination de l'opération de fidélisation B2B 'Semaine du Trail' : 15 clients CE et clubs invités à une journée test produit au showroom. Tu coordonnes à distance (relances téléphoniques, mails) et sur place le jour J.",activites:[{t:"Évaluer rigoureusement",q:["1.1  Calculer le ROI de la soirée sur 30 jours. Interpréter le résultat.","1.2  Au-delà du ROI, identifier 3 bénéfices non financiers de cet événement pour LABORO.","1.3  La soirée a-t-elle atteint ses objectifs de fidélisation ? Analyser à partir des données disponibles."]},{t:"Recommander et planifier",q:["2.1  Décider : reconduire, adapter ou remplacer ? Argumenter ta décision avec les données du bilan.","2.2  Si reconduction, proposer 3 améliorations pour augmenter le ROI.","2.3  Rédiger le rapport d'évaluation destiné à Pascal Berruelle avec ta recommandation."]}],livrable:"Calcul ROI + 3 bénéfices non financiers + analyse objectifs + décision argumentée + rapport",criteres:[{"c":"Stratégie cohérente","i":"La stratégie proposée est cohérente sur tous les canaux digitaux utilisés par LABORO"},{"c":"Maîtrise des indicateurs","i":"Tous les indicateurs sont calculés et interprétés correctement"},{"c":"Plan d'action opérationnel","i":"Le plan d'action est priorisé, chiffré et réalisable pour LABORO"},{"c":"Vision multicanale","i":"Je fais le lien entre digital et présence physique (showroom, événements)"}],reflexivite_q:"Quelles sont les limites des indicateurs digitaux que tu as calculés pour évaluer l'action de LABORO ? Que manque-t-il pour avoir une vision complète ?",reflexivite:3},
  {id:"M031",titre:"Optimiser le traitement de l'information client",comp:"C3.1",comp_ref:"C3.1",objectif:"Dans cette mission, tu vas analyser et segmenter la base clients LABORO pour construire des actions de contact personnalisées et mesurer leur efficacité.",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",palier:3,option:"commun",dossier:{l:"Tableau de bord contacts LABORO — semaine type",rows:[["Appels entrants","47"],["Mails reçus","83"],["Messages Instagram/Facebook","29"],["Avis Google","6 — dont 2 négatifs"],["Demandes via laboro-sport.fr","34"],["Délai moyen de réponse actuel","31h — objectif : < 24h"],["Taux de contacts non traités","12%"]]},contexte:"Marco Pellini vous présente les chiffres des contacts de la semaine et vous demande de concevoir un système de traitement plus efficace pour atteindre l'objectif de réponse en moins de 24h.",contexte_pvoc:"Pascal Berruelle te demande d'optimiser le traitement des contacts B2B entrants — mails, appels, réseaux sociaux, formulaires site — pour atteindre un délai de réponse < 24h sur tous les canaux.",activites:[{t:"Analyser et diagnostiquer",q:["1.1  Identifier les 2 canaux les plus critiques à améliorer en priorité. Justifier avec les données.","1.2  Le taux de 12% de contacts non traités représente combien de contacts perdus par semaine ? Quel est l'impact estimé en CA perdu ?","1.3  Concevoir la procédure de traitement des contacts entrants — priorités, délais par canal, responsables, escalade."]},{t:"Mettre en place et mesurer",q:["2.1  Rédiger les réponses types (templates) pour les 3 demandes les plus fréquentes — à personnaliser selon le client.","2.2  Définir le tableau de bord hebdomadaire de suivi des contacts à présenter à Pascal Berruelle."]}],livrable:"Diagnostic 2 canaux + calcul contacts perdus + procédure complète + 3 templates + tableau de bord",criteres:[{"c":"Analyse complète","i":"Mon analyse exploite l'ensemble des données disponibles sans omission"},{"c":"Segmentation argumentée","i":"Mes critères de segmentation sont justifiés et opérationnels"},{"c":"Actions personnalisées","i":"Les actions proposées sont différenciées selon les segments identifiés"},{"c":"Mesure de l'efficacité","i":"Je définis des indicateurs pour évaluer les actions envisagées"}],reflexivite_q:"Comment la segmentation de la base clients que tu as réalisée peut-elle orienter concrètement les actions commerciales de LABORO ?",reflexivite:3},
  {id:"M032",titre:"Développer la clientèle B2B de LABORO",comp:"C4A.3",comp_ref:"C4A.3",objectif:"Dans cette mission, tu vas concevoir et mettre en œuvre des actions de développement de la clientèle adaptées au contexte LABORO.",comp_libelle:"Bloc 4A — Développer la clientèle",palier:3,option:"AGEC",dossier:{l:"Analyse clientèle B2B — situation actuelle",rows:[["Clients B2B actifs","24"],["CA B2B total","1 120 000 € — 40% du CA LABORO"],["Panier moyen B2B","19 500 €"],["Taux de fidélisation B2B","74%"],["Secteurs représentés","CE 45% · Asso. sportives 30% · Collectivités 18% · Lycées 7%"],["Prospects B2B identifiés","38 — dont 12 qualifiés"],["Objectif CA B2B","+ 15% en 12 mois"]]},contexte:"Pascal Berruelle veut accélérer le développement B2B de LABORO. Il vous confie la conception d'un plan de développement pour atteindre +15% de CA B2B en 12 mois.",activites:[{t:"Analyser et fixer les objectifs",q:["1.1  Calculer le CA B2B à atteindre pour +15%. Combien de nouveaux clients ou de commandes supplémentaires faut-il ?","1.2  Identifier les 2 segments B2B à fort potentiel non encore exploités par LABORO. Justifier avec des données.","1.3  Proposer une offre commerciale B2B structurée — tarification, services associés, conditions — différente de l'offre B2C."]},{t:"Planifier et piloter",q:["2.1  Établir le plan d'action sur 12 mois avec les actions prioritaires, les responsables et les jalons.","2.2  Définir 5 indicateurs de pilotage du développement B2B.","2.3  Rédiger le plan stratégique complet destiné à Pascal Berruelle."]}],livrable:"Calcul objectif + 2 segments B2B + offre structurée + plan 12 mois + 5 indicateurs + plan stratégique",criteres:[{"c":"Conception de l'action","i":"L'action proposée est cohérente avec les objectifs et la cible de LABORO"},{"c":"Plan opérationnel","i":"Le plan d'action est détaillé, priorisé et réaliste"},{"c":"Argumentation","i":"Chaque choix est justifié par des données ou des arguments professionnels"},{"c":"Indicateurs de suivi","i":"Je définis des indicateurs précis pour évaluer l'efficacité de l'action"}],reflexivite_q:"En quoi les actions de développement clientèle que tu as proposées s'inscrivent-elles dans une logique de long terme pour LABORO ?",reflexivite:3},
  {id:"M033",titre:"Analyser et améliorer les performances commerciales",comp:"C1.1",comp_ref:"C1.1",comp_libelle:"Bloc 1 — Assurer la veille commerciale",objectif:"Dans cette mission, tu vas exploiter une veille commerciale pour formuler des recommandations argumentées sur le positionnement produit ou prix de LABORO.",palier:3,option:"commun",dossier:{l:"Tableau de bord commercial — semestre 1",rows:[["CA semestre","142 000 € HT — objectif 130 000 €"],["Taux de transformation","34% — objectif 38%"],["Panier moyen","162 € — objectif 175 €"],["CA running/sport","36% du CA total"],["Nouveaux clients","87"],["Clients perdus","71"],["NPS","+ 8"]]},contexte:"Romain Sauzet vous présente le tableau de bord du semestre. Le CA dépasse l'objectif mais le taux de transformation et le panier moyen sont en deçà. Pascal Berruelle attend une analyse et un plan correctif.",contexte_pvoc:"Romain Sauzet et Nina Chevalier te présentent le tableau de bord commercial B2B du semestre. Le CA dépasse l'objectif mais le taux de transformation des prospects et le panier moyen B2B sont en deçà. Pascal Berruelle attend une analyse et un plan correctif pour la relation client à distance.",activites:[{t:"Analyser en profondeur",q:["1.1  Le CA dépasse l'objectif mais deux indicateurs sont en retard. Expliquer cette apparente contradiction.","1.2  Calculer le solde clients (acquisitions - pertes). Interpréter ce résultat pour la pérennité de LABORO.","1.3  Identifier les 3 causes probables du taux de transformation insuffisant."]},{t:"Proposer et planifier",q:["2.1  Proposer 3 actions pour améliorer le taux de transformation de 34% à 38% d'ici la fin de l'année.","2.2  Proposer 2 actions pour augmenter le panier moyen de 162€ à 175€.","2.3  Rédiger le rapport d'analyse et de recommandations destiné à Pascal Berruelle."]}],livrable:"Analyse contradiction CA + solde clients + 3 causes taux transformation + 3+2 actions + rapport",criteres:[{"c":"Exploitation complète des données","i":"J'exploite toutes les informations pertinentes du dossier sans omission majeure"},{"c":"Analyse argumentée","i":"Mon analyse distingue faits, interprétations et recommandations"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont concrètes, réalisables et adaptées à LABORO"},{"c":"Rigueur professionnelle","i":"Le vocabulaire utilisé est celui d'un(e) professionnel(le) du commerce"}],reflexivite_q:"Quelles informations du dossier t'ont été les plus utiles pour construire ton analyse ? Qu'aurais-tu cherché en plus si tu avais eu plus de temps ?",reflexivite:3},
  {id:"M034",titre:"Gérer une crise client majeure",comp:"C2.2",comp_ref:"C2.3",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",objectif:"Dans cette mission, tu vas gérer des situations de réclamation complexes de façon autonome, en préservant la relation client et l'image de LABORO.",palier:3,option:"AGEC",dossier:{l:"Situation de crise",rows:[["Incident","3 lots de 8 maillots notre atelier de flocage livrés avec logo illisible"],["Clients concernés","AS Évry Athlétisme · CE PSA · Mairie Évry"],["CA en jeu","2 100 € HT"],["Événements prévus","Tournoi municipal samedi — dans 4 jours"],["Réaction clients","Jean-Paul Moretti furieux · Isabelle Faure déçue · David Chemin neutre"],["Faute","Validation BAT non effectuée par notre atelier de flocage"]]},contexte:"Marco Pellini vous informe ce matin d'un problème majeur : 3 commandes de maillots flocage sont défectueuses. Romain Sauzet est absent. Vous gérez seul(e) la crise.",activites:[{t:"Gérer l'urgence",q:["1.1  Dans les 2 premières heures, quelles sont les 5 actions prioritaires à mener dans l'ordre ?","1.2  Appeler Jean-Paul Moretti en premier (le plus furieux). Rédiger le script de l'appel téléphonique — accroche, empathie, solution proposée, engagement.","1.3  Rédiger le mail de notre atelier de flocage réclamant le remplacement d'urgence et une compensation commerciale."]},{t:"Résoudre et pérenniser",q:["2.1  Proposer une solution de substitution pour le tournoi de samedi si notre atelier de flocage ne peut pas refaire les maillots à temps.","2.2  Rédiger le rapport de crise post-incident destiné à Romain Sauzet et Pascal Berruelle avec un plan pour éviter la récidive."]}],livrable:"5 actions prioritaires + script Jean-Paul Moretti + mail notre atelier de flocage + solution de substitution + rapport de crise",criteres:[{"c":"Gestion autonome de la complexité","i":"Je gère la réclamation de bout en bout sans aide, même dans une situation difficile"},{"c":"Maîtrise de la méthode","i":"ERESA est appliquée avec fluidité — sans lecture du support"},{"c":"Qualité argumentative","i":"Mon argumentaire est structuré, professionnel et adapté au contexte"},{"c":"Préservation de l'image LABORO","i":"Ma gestion préserve la réputation et la relation commerciale de LABORO"},{"c":"Propositions d'amélioration","i":"Je propose des actions pour éviter la récidive de ce type de réclamation"}],reflexivite_q:"Qu'est-ce qui te paraît le plus difficile dans la gestion d'une réclamation complexe ? Comment la méthode ERESA t'a-t-elle aidé à structurer ta réponse ?",reflexivite:3},
  {id:"M035",titre:"Concevoir la stratégie omnicanale de LABORO",comp:"C1.2",comp_ref:"C1.2",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",objectif:"Dans cette mission, tu vas mener une vente omnicanale complexe en adaptant ton argumentation au profil client et en gérant les objections avec méthode.",palier:3,option:"AGEC",dossier:{l:"Performances canaux — année en cours",rows:[["Showroom Évry — CA","890 000 € — 32% du CA"],["E-commerce laboro-sport.fr — CA","980 000 € — 35% du CA"],["Commercial terrain — CA","720 000 € — 26% du CA"],["Téléphone entrant — CA","210 000 € — 7% du CA"],["Croissance e-commerce","+ 28% vs N-1"],["Taux d'abandon panier e-commerce","67%"],["CA clients omnicanaux (2+ canaux)","27% plus élevé que mono-canal"]]},contexte:"Pascal Berruelle constate que les clients qui utilisent plusieurs canaux génèrent 27% de CA supplémentaire. Il vous demande de concevoir une stratégie pour développer l'expérience omnicanale de LABORO.",activites:[{t:"Analyser et diagnostiquer",q:["1.1  Analyser la répartition du CA par canal. Quels sont les 2 leviers de croissance prioritaires ?","1.2  Le taux d'abandon panier de 67% sur l'e-commerce est préoccupant. Identifier 3 causes probables et proposer 3 actions correctives.","1.3  Définir ce qu'est une expérience client omnicanale idéale pour LABORO — parcours type d'un client B2C et B2B."]},{t:"Concevoir la stratégie",q:["2.1  Proposer 5 actions concrètes pour développer l'omnicanalité de LABORO avec délai et responsable pour chacune.","2.2  Rédiger le plan stratégique omnicanal destiné à Pascal Berruelle avec objectifs à 12 mois."]}],livrable:"Analyse 2 leviers + 3 causes/actions abandon panier + parcours B2C/B2B + 5 actions + plan stratégique",criteres:[{"c":"Adaptation au profil client","i":"Mon approche est clairement différenciée selon le profil (B2C/B2B, SONCAS identifié)"},{"c":"Maîtrise des techniques","i":"J'applique CAB, SONCAS et traitement des objections de façon fluide et cohérente"},{"c":"Gestion de la complexité","i":"Je gère correctement les situations imprévues ou les clients difficiles"},{"c":"Argumentation omnicanale","i":"J'intègre la dimension omnicanale (site, réseaux, showroom) dans la démarche de vente"}],reflexivite_q:"Si tu devais présenter ta technique de vente à un jury professionnel, quels arguments aurais-tu mis en avant ? Qu'aurais-tu pu faire différemment pour mieux cerner les besoins du client ?",reflexivite:3},
  {id:"M036",titre:"Piloter le suivi des commandes B2B",comp:"C2.1",comp_ref:"C2.1",objectif:"Dans cette mission, tu vas gérer des situations de commande complexes — rupture de stock, délais, commandes B2B — en proposant des solutions adaptées.",comp_libelle:"Bloc 2 — Assurer le suivi de la commande du produit et/ou du service",palier:3,option:"AGEC",dossier:{l:"Tableau des commandes B2B en cours",rows:[["CE PSA Stellantis","40 maillots brodés — livraison dans 12j — en production notre atelier de flocage"],["Mairie Évry","50 ballons + 20 filets — livrés vendredi — confirmation reçue"],["AS Évry Athlétisme","10 maillots + chaussures × 6 — retard 3j — transporteur bloqué"],["Lycée Pascal Orsay","15 ballons — commande passée hier — à préparer"],["Club Sportif Sénart","12 Chaussures running EasyRun — attente confirmation commande client"]]},contexte:"Romain Sauzet vous confie la gestion complète des commandes B2B de la semaine. Cinq dossiers sont ouverts simultanément — certains nécessitent des actions immédiates.",activites:[{t:"Prioriser et agir",q:["1.1  Classer les 5 commandes par ordre de priorité d'action. Justifier ton classement.","1.2  Pour AS Évry Athlétisme (retard 3 jours) : rédiger l'appel téléphonique à Jean-Paul Moretti pour l'informer et lui proposer une solution.","1.3  Pour Club Sportif Sénart : Marc Girault n'a pas confirmé. Rédiger le mail de relance avec une offre commerciale incitative."]},{t:"Optimiser le suivi",q:["2.1  Concevoir le tableau de bord de suivi des commandes B2B à mettre en place dans LABORO Connect — colonnes, alertes, fréquence de mise à jour.","2.2  Rédiger les procédures de gestion des retards transporteur pour standardiser les réponses de toute l'équipe LABORO."]}],livrable:"Classement priorités justifié + appel AS Évry + mail Club Sportif + tableau de bord LABORO Connect + procédure retards",criteres:[{"c":"Gestion des situations complexes","i":"Je traite correctement les situations difficiles (rupture, retard, litige)"},{"c":"Maîtrise des procédures","i":"Toutes les procédures sont appliquées sans erreur"},{"c":"Solutions adaptées","i":"Les solutions proposées sont adaptées, argumentées et acceptables par le client"},{"c":"Communication professionnelle","i":"Ma communication est fluide, professionnelle et préserve la relation client"}],reflexivite_q:"Quelle difficulté as-tu rencontrée dans le traitement de cette commande ? Comment l'aurais-tu gérée différemment en situation réelle ?",reflexivite:3},
  {id:"M037",titre:"Évaluer et optimiser la politique de fidélisation",comp:"C3.3",comp_ref:"C3.3",comp_libelle:"Bloc 3 — Évaluer les actions de fidélisation de la clientèle et de développement de la relation client",objectif:"Dans cette mission, tu vas élaborer et piloter une stratégie digitale cohérente pour LABORO en intégrant les réseaux sociaux et les outils e-commerce.",palier:3,option:"commun",dossier:{l:"Bilan programme fidélisation LABORO — 6 mois",rows:[["Clients inscrits au programme","284 sur 3 200 — taux 8,9%"],["CA clients programme","+ 34% vs clients non inscrits"],["Taux de rétention programme","87% vs 78% hors programme"],["Actions menées","Soirée Rentrée Sportive · 3 newsletters · 2 offres exclusives"],["Coût total programme","4 200 €"],["CA additionnel généré","18 700 € HT"],["Satisfaction clients programme","4,4/5"]]},contexte:"Pascal Berruelle vous demande d'évaluer les 6 premiers mois du programme de fidélisation et de préparer le plan du second semestre.",contexte_pvoc:"Pascal Berruelle te demande d'évaluer les 6 premiers mois du programme de fidélisation des clients B2B de LABORO (CE, clubs, collectivités) et de préparer le plan du second semestre, dans le contexte de la relation client à distance.",activites:[{t:"Évaluer rigoureusement",q:["1.1  Calculer le ROI global du programme sur 6 mois. Interpréter le résultat.","1.2  Le taux d'inscription de 8,9% est insuffisant. Identifier 3 freins à l'inscription et proposer 3 actions pour doubler ce taux.","1.3  Comparer les indicateurs clés entre clients programme et hors programme. Quelle est la valeur d'un client fidélisé pour LABORO ?"]},{t:"Planifier le second semestre",q:["2.1  Proposer 4 actions nouvelles pour le second semestre en justifiant chaque choix.","2.2  Rédiger le rapport semestriel complet destiné à Pascal Berruelle avec recommandations pour l'année suivante."]}],livrable:"Calcul ROI + 3 freins/actions inscription + analyse valeur client + 4 nouvelles actions + rapport semestriel",criteres:[{"c":"Stratégie cohérente","i":"La stratégie proposée est cohérente sur tous les canaux digitaux utilisés par LABORO"},{"c":"Maîtrise des indicateurs","i":"Tous les indicateurs sont calculés et interprétés correctement"},{"c":"Plan d'action opérationnel","i":"Le plan d'action est priorisé, chiffré et réalisable pour LABORO"},{"c":"Vision multicanale","i":"Je fais le lien entre digital et présence physique (showroom, événements)"}],reflexivite_q:"Quelles sont les limites des indicateurs digitaux que tu as calculés pour évaluer l'action de LABORO ? Que manque-t-il pour avoir une vision complète ?",reflexivite:3},
  {id:"M038",titre:"Rechercher et qualifier des informations de prospection",comp:"B4.1",comp_ref:"C4B.1",objectif:"Dans cette mission, tu vas construire une base de prospection qualifiée et définir une stratégie d'approche adaptée aux cibles B2B de LABORO.",comp_libelle:"Bloc 4B — Rechercher et analyser les informations à des fins d’exploitation",palier:3,option:"PVOC",dossier:{l:"Marché cible — CE grandes entreprises Essonne",rows:[["Entreprises > 500 salariés en Essonne","~45"],["Budget CE sport moyen","15 000 à 30 000 €/an"],["Taux de multi-fournisseurs","72% travaillent avec 2+ fournisseurs"],["Canal d'achat préféré B2B","E-mail 44% · Téléphone 31% · Visite terrain 25%"],["Délai moyen de décision","3 à 8 semaines selon budget"],["Décisionnaire principal","Responsable CE 68% · DRH 22% · DAF 10%"]]},contexte:"Pascal Berruelle veut conquérir les CE des grandes entreprises de l'Essonne (> 500 salariés). Il vous confie la veille concurrentielle et la constitution de la base de prospection pour cette cible.",activites:[{t:"Construire la base de prospection",q:["1.1  Identifier 5 sources fiables pour constituer la liste des CE d'entreprises > 500 salariés en Essonne.","1.2  Définir les critères de qualification prioritaires pour ce segment — BANT adapté aux CE.","1.3  Identifier 3 prospects CE non encore dans le fichier LABORO. Pour chacun : entreprise, contact, budget estimé, besoins potentiels."]},{t:"Analyser la concurrence et positionner",q:["2.1  Analyser les forces et faiblesses de LABORO face à Decathlon Pro sur ce marché CE grande entreprise.","2.2  Rédiger le brief de positionnement LABORO sur ce segment — 3 arguments différenciateurs + 1 offre d'entrée.","2.3  Rédiger le rapport de veille destiné à Pascal Berruelle."]}],livrable:"5 sources + critères BANT CE + 3 prospects identifiés + analyse concurrentielle + brief positionnement + rapport",criteres:[{"c":"Base de prospection qualifiée","i":"La base construite est complète, qualifiée et exploitable"},{"c":"Stratégie d'approche","i":"La stratégie d'approche est adaptée aux différents profils de prospects"},{"c":"Planification","i":"Le plan de prospection est réaliste et priorisé"},{"c":"Argumentation","i":"Les choix sont justifiés par des données et des arguments commerciaux solides"}],reflexivite_q:"Quels critères de qualification d'un prospect te semblent les plus importants pour LABORO ? Pourquoi certains prospects sont-ils plus prioritaires que d'autres ?",reflexivite:3},
  {id:"M039",titre:"Concevoir un plan de prospection stratégique",comp:"B4.2",comp_ref:"C4B.2",objectif:"Dans cette mission, tu vas construire un plan de prospection complet pour LABORO en intégrant les objectifs, les cibles et les outils.",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",palier:3,option:"PVOC",dossier:{l:"Ressources disponibles pour la prospection",rows:[["Commercial terrain","1 ETP (toi) — 3 jours terrain / 2 jours admin"],["Budget prospection","800 € / trimestre"],["CRM LABORO Connect","Disponible — 38 prospects qualifiés"],["Outils disponibles","Téléphone · Mail · LinkedIn · Présentoir mobile LABORO"],["Objectif direction","Signer 5 nouveaux contrats B2B > 5 000 € HT/an en 3 mois"]]},contexte:"Nina Chevalier vous donne les ressources disponibles et l'objectif pour le prochain trimestre. Elle vous demande de concevoir le plan de prospection complet.",activites:[{t:"Construire le plan stratégique",q:["1.1  À partir de l'objectif de 5 contrats, calculer le nombre de prospects à contacter (en remontant la chaîne de conversion à partir des taux observés).","1.2  Sélectionner et justifier les 3 techniques de prospection les plus adaptées à ce contexte et à ces ressources.","1.3  Établir le planning hebdomadaire type sur 12 semaines avec les actions et le temps alloué à chacune."]},{t:"Budgéter et anticiper",q:["2.1  Établir le budget détaillé de l'opération — ventiler les 800 € par poste de dépense.","2.2  Identifier 3 risques potentiels pour l'opération et pour chacun proposer une action préventive.","2.3  Rédiger le plan de prospection complet destiné à Nina Chevalier pour validation."]}],livrable:"Calcul nombre de prospects + 3 techniques justifiées + planning 12 semaines + budget détaillé + 3 risques + plan complet",criteres:[{"c":"Plan de prospection complet","i":"Le plan couvre toutes les étapes — ciblage, approche, outils, suivi, indicateurs"},{"c":"Cohérence stratégique","i":"Le plan est cohérent avec les objectifs commerciaux et les ressources de LABORO"},{"c":"Qualité des supports","i":"Les supports produits sont professionnels et directement utilisables"},{"c":"Indicateurs définis","i":"Les indicateurs de performance de la prospection sont précis et mesurables"}],reflexivite_q:"Qu'est-ce qui distingue un bon plan de prospection d'une simple liste de contacts à appeler ? Comment mesureras-tu le succès de ton plan ?",reflexivite:3},
  {id:"M040",titre:"Mettre en oeuvre et adapter la prospection",comp:"B4.3",comp_ref:"C4B.3",objectif:"Dans cette mission, tu vas conduire une négociation commerciale B2B de bout en bout, de la prise de contact à la proposition commerciale.",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",palier:3,option:"PVOC",dossier:{l:"Bilan mi-opération prospection — 6 semaines",rows:[["Prospects contactés","31 sur 38 prévus"],["RDV obtenus","11 — taux 35%"],["RDV effectués","8"],["Devis envoyés","5"],["Contrats signés","1 — CA 6 200 € HT"],["Contrats en négociation","3 — CA potentiel 22 000 € HT"],["Budget consommé","490 € sur 800 €"]]},contexte:"À mi-opération (semaine 6 sur 12), Nina Chevalier vous demande un bilan intermédiaire et des ajustements pour atteindre l'objectif de 5 contrats.",activites:[{t:"Analyser et ajuster",q:["1.1  Analyser les taux de conversion à chaque étape. Où se situent les pertes les plus importantes ?","1.2  Avec 3 contrats en négociation et 1 signé, est-il réaliste d'atteindre 5 contrats en 6 semaines restantes ? Calculer et argumenter.","1.3  Proposer 3 ajustements tactiques pour maximiser les chances d'atteindre l'objectif."]},{t:"Gérer les négociations en cours",q:["2.1  L'un des 3 prospects en négociation demande une remise de 20% pour signer immédiatement. Quelle est ta réponse et ta stratégie de négociation ?","2.2  Rédiger le rapport de mi-opération destiné à Nina Chevalier."]}],livrable:"Analyse taux de conversion + calcul faisabilité + 3 ajustements + stratégie négociation + rapport mi-opération",criteres:[{"c":"Conduite de la négociation","i":"Je mène la négociation de bout en bout avec fluidité et méthode"},{"c":"Adaptation à l'interlocuteur","i":"Mon approche s'adapte au profil et aux enjeux de l'interlocuteur B2B"},{"c":"Proposition commerciale","i":"Ma proposition est construite, argumentée et adaptée aux besoins identifiés"},{"c":"Conclusion","i":"Je concluis la négociation de façon professionnelle (accord, étape suivante, suivi)"}],reflexivite_q:"Qu'as-tu appris sur ta propre façon de gérer une négociation B2B à travers cette mission ? Qu'aurais-tu fait différemment ?",reflexivite:3},
  {id:"M041",titre:"Valoriser l'offre LABORO en situation complexe",comp:"B4.5",comp_ref:"C4B.5",objectif:"Dans cette mission, tu vas élaborer et présenter une offre commerciale complexe pour LABORO, en intégrant les besoins spécifiques du client.",comp_libelle:"Bloc 4B — Valoriser les produits et/ou les services",palier:3,option:"PVOC",dossier:{l:"Contexte RDV — ArianeGroup Massy",rows:[["Entreprise","ArianeGroup — 2 800 salariés Massy"],["Contact","Sébastien Foulon — responsable CE"],["Budget sport CE","28 000 €/an"],["Fournisseur actuel","Decathlon Pro — relation 4 ans"],["Motif du RDV","ArianeGroup consulte 3 fournisseurs par appel d'offres informel"],["Délai de décision","3 semaines"],["Critères annoncés","Prix 40% · SAV 30% · Conseil 20% · Délais 10%"]]},contexte:"Tu as décroché un RDV stratégique avec ArianeGroup Massy — 28 000 €/an de budget CE sport. C'est le prospect le plus important de l'opération. Nina Chevalier compte sur toi.",activites:[{t:"Préparer la proposition",q:["1.1  Analyser les critères de décision d'ArianeGroup. Sur quels critères LABORO peut-il gagner contre Decathlon Pro ?","1.2  Concevoir la proposition commerciale complète pour ArianeGroup — 3 offres à des niveaux différents pour laisser le choix.","1.3  Préparer 5 objections probables de Sébastien Foulon et une réponse argumentée pour chacune."]},{t:"Conclure et fidéliser",q:["2.1  Sébastien Foulon annonce que Decathlon Pro est 12% moins cher sur le textile. Rédiger ta réponse pour défendre la valeur LABORO sans brader.","2.2  Le RDV se conclut positivement. Rédiger le mail de synthèse envoyé dans les 2 heures après le RDV."]}],livrable:"Analyse critères + 3 offres + 5 objections/réponses + réponse objection prix + mail post-RDV",criteres:[{"c":"Offre complète et personnalisée","i":"L'offre est entièrement adaptée aux besoins spécifiques du client B2B"},{"c":"Argumentation experte","i":"L'argumentation mobilise des techniques avancées (ROI, références clients, garanties)"},{"c":"Présentation convaincante","i":"La présentation est structurée pour maximiser l'impact sur le décideur"},{"c":"Gestion des objections anticipée","i":"J'anticipe les objections probables et prépare des réponses adaptées"}],reflexivite_q:"En quoi la personnalisation d'une offre B2B est-elle un avantage concurrentiel pour LABORO ? Qu'est-ce qui fait qu'une offre convainc vraiment un décideur ?",reflexivite:3},
  {id:"M042",titre:"Assurer le suivi et la fidélisation des comptes B2B",comp:"B4.4",comp_ref:"C4B.4",objectif:"Dans cette mission, tu vas évaluer une action de prospection de LABORO, en calculant les indicateurs clés et en formulant des recommandations.",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",palier:3,option:"PVOC",dossier:{l:"Portefeuille comptes B2B — état des relations",rows:[["CE PSA Stellantis","22 400 €/an — client fidèle 3 ans — renouvellement contrat dans 2 mois"],["Mairie Évry","14 800 €/an — très satisfait — pas de contact depuis 45 jours"],["AS Évry Athlétisme","9 200 €/an — incident maillots récent — fragilisé"],["Club Sportif Sénart","1er contrat 4 800 € — à consolider"],["ArianeGroup","Nouveau client 28 000 € potentiel — à onboarder"]]},contexte:"Nina Chevalier vous confie la gestion relationnelle de 5 comptes B2B clés. Chacun nécessite une approche différente selon sa situation.",activites:[{t:"Définir la stratégie par compte",q:["1.1  Pour chacun des 5 comptes, définir l'objectif relationnel à 3 mois et l'action prioritaire.","1.2  Rédiger le plan de contact pour CE PSA Stellantis dont le contrat se renouvelle dans 2 mois — actions à mener semaine par semaine.","1.3  AS Évry est fragilisé après l'incident maillots. Rédiger la stratégie de reconquête relationnelle en 3 étapes."]},{t:"Agir et mesurer",q:["2.1  Rédiger le mail de reprise de contact pour la Mairie d'Évry (pas de contact depuis 45 jours) en créant une opportunité commerciale naturelle.","2.2  Définir les 4 indicateurs de pilotage de ton portefeuille B2B — formule, objectif, fréquence."]}],livrable:"Stratégie 5 comptes + plan CE PSA + stratégie reconquête AS Évry + mail Mairie + 4 indicateurs",criteres:[{"c":"Maîtrise des indicateurs","i":"Tous les indicateurs sont calculés et interprétés correctement"},{"c":"Analyse complète","i":"Mon analyse identifie causes, conséquences et leviers d'amélioration"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont priorisées, justifiées et chiffrées quand possible"},{"c":"Tableau de bord","i":"Le tableau de bord proposé est complet, lisible et exploitable"}],reflexivite_q:"Quels indicateurs te semblent les plus pertinents pour piloter la prospection de LABORO ? Pourquoi le taux de transformation est-il l'indicateur clé ?",reflexivite:3},
  {id:"M043",titre:"Analyser et optimiser les résultats de la prospection",comp:"B4.4",comp_ref:"C4B.4",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",objectif:"Dans cette mission, tu vas évaluer une action de prospection de LABORO, en calculant les indicateurs clés et en formulant des recommandations.",palier:3,option:"PVOC",dossier:{l:"Bilan final opération prospection — 12 semaines",rows:[["Prospects contactés","47"],["RDV obtenus","16 — taux 34%"],["Devis envoyés","11"],["Contrats signés","4 — CA 31 200 € HT"],["Objectif initial","5 contrats"],["Budget consommé","780 € sur 800 €"],["CA moyen par contrat","7 800 € HT"],["Coût d'acquisition moyen","195 € / nouveau client"]]},contexte:"L'opération de prospection est terminée. Nina Chevalier vous demande le bilan complet et les recommandations pour la prochaine opération.",activites:[{t:"Évaluer rigoureusement",q:["1.1  Calculer le ROI de l'opération. LABORO a investi 780 € — quel est le retour sur investissement sur la première année de CA ?","1.2  L'objectif de 5 contrats n'est pas atteint (4 signés). Identifier 3 causes et proposer 3 actions correctives pour la prochaine opération.","1.3  Analyser la chaîne de conversion — où se situent les meilleures performances et les points d'amélioration ?"]},{t:"Capitaliser et recommander",q:["2.1  Rédiger les enseignements de cette opération sous forme de guide pour un futur commercial LABORO.","2.2  Rédiger le rapport final complet destiné à Pascal Berruelle et Nina Chevalier avec recommandations stratégiques."]}],livrable:"Calcul ROI + 3 causes/actions + analyse chaîne conversion + guide commercial + rapport final",criteres:[{"c":"Maîtrise des indicateurs","i":"Tous les indicateurs sont calculés et interprétés correctement"},{"c":"Analyse complète","i":"Mon analyse identifie causes, conséquences et leviers d'amélioration"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont priorisées, justifiées et chiffrées quand possible"},{"c":"Tableau de bord","i":"Le tableau de bord proposé est complet, lisible et exploitable"}],reflexivite_q:"Quels indicateurs te semblent les plus pertinents pour piloter la prospection de LABORO ? Pourquoi le taux de transformation est-il l'indicateur clé ?",reflexivite:3},
  {id:"M044",titre:"Construire la stratégie commerciale B2B de LABORO",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas construire un plan de prospection complet pour LABORO en intégrant les objectifs, les cibles et les outils.",palier:3,option:"PVOC",dossier:{l:"Situation commerciale B2B — bilan annuel",rows:[["CA B2B actuel","1 120 000 € — 40% du CA LABORO"],["Objectif CA B2B N+1","1 288 000 € — + 15%"],["Clients B2B actifs","24"],["Taux de fidélisation B2B","74%"],["Nouveaux clients B2B","6 cette année"],["CA par commercial terrain","560 000 € (0,5 ETP)"],["Marché potentiel Essonne","estimé 8 à 12 M€ / an"]]},contexte:"Pascal Berruelle vous demande de construire le plan stratégique commercial B2B pour l'année suivante. C'est votre mission de Terminale — elle sera présentée à l'équipe de direction.",activites:[{t:"Analyser et fixer les orientations",q:["1.1  Calculer le CA B2B à atteindre et définir les 3 segments prioritaires à développer en justifiant chaque choix.","1.2  Analyser les forces et faiblesses de LABORO sur le marché B2B Essonne. Identifier 2 opportunités et 2 menaces.","1.3  Proposer 3 offres B2B différenciées adaptées à chaque segment prioritaire."]},{t:"Construire le plan et piloter",q:["2.1  Établir le plan d'action sur 12 mois avec objectifs trimestriels, actions, responsables et budget.","2.2  Définir 6 indicateurs de pilotage stratégique B2B.","2.3  Rédiger le plan stratégique complet destiné à la direction LABORO — 30 à 40 lignes — pour présentation."]}],livrable:"3 segments + analyse SWOT + 3 offres + plan 12 mois + 6 indicateurs + plan stratégique direction",criteres:[{"c":"Plan de prospection complet","i":"Le plan couvre toutes les étapes — ciblage, approche, outils, suivi, indicateurs"},{"c":"Cohérence stratégique","i":"Le plan est cohérent avec les objectifs commerciaux et les ressources de LABORO"},{"c":"Qualité des supports","i":"Les supports produits sont professionnels et directement utilisables"},{"c":"Indicateurs définis","i":"Les indicateurs de performance de la prospection sont précis et mesurables"}],reflexivite_q:"Qu'est-ce qui distingue un bon plan de prospection d'une simple liste de contacts à appeler ? Comment mesureras-tu le succès de ton plan ?",reflexivite:3},
  {id:"M080",titre:"Concevoir et animer une animation commerciale",comp:"C4A.3",comp_ref:"C4A.3",comp_libelle:"Bloc 4A — Développer la clientèle",objectif:"Dans cette mission, tu vas concevoir et mettre en œuvre des actions de développement de la clientèle adaptées au contexte LABORO.",palier:3,option:"AGEC",dossier:{l:"Bilan opération Printemps du Sport — avril 2026",rows:[["CA généré","6 200 € sur objectif 8 000 €"],["Visiteurs","94 — dont 41 acheteurs"],["Taux de transformation","44% — objectif 50%"],["Satisfaction événement","4,1/5"],["Coût opération","580 €"],["ROI","(6 200 − 580) ÷ 580 × 100 = 969%"]]},contexte:"Romain Sauzet te félicite mais veut faire mieux à l'automne. Il te confie la conception complète de l'opération Rentrée Sportive de septembre — de l'idée au bilan.",activites:[{t:"Concevoir l'opération",q:["1.1  Calculer le CA additionnel à viser pour dépasser l'objectif de 8 000 € avec un budget de 600 €. Définir un objectif SMART complet.","1.2  Concevoir le programme de l'animation — thème, dates, actions, cibles, supports de communication. Justifier chaque choix par rapport aux enseignements du Printemps du Sport.","1.3  Ventiler les 600 € de budget entre les postes en justifiant chaque allocation."]},{t:"Piloter et analyser",q:["2.1  Définir 5 indicateurs de pilotage à suivre pendant et après l'opération — formule, objectif, fréquence.","2.2  L'opération se termine. Rédiger le bilan complet à Pascal Berruelle — résultats vs objectifs, causes des écarts, 3 recommandations pour la prochaine édition. Analyser ta propre pratique : qu'aurais-tu fait différemment ?"]}],livrable:"Objectif SMART + programme complet + budget ventilé + 5 indicateurs + bilan avec auto-analyse",criteres:[{"c":"Conception de l'action","i":"L'action proposée est cohérente avec les objectifs et la cible de LABORO"},{"c":"Plan opérationnel","i":"Le plan d'action est détaillé, priorisé et réaliste"},{"c":"Argumentation","i":"Chaque choix est justifié par des données ou des arguments professionnels"},{"c":"Indicateurs de suivi","i":"Je définis des indicateurs précis pour évaluer l'efficacité de l'action"}],reflexivite_q:"En quoi les actions de développement clientèle que tu as proposées s'inscrivent-elles dans une logique de long terme pour LABORO ?",reflexivite:3},
  {id:"M081",titre:"Piloter la satisfaction et proposer un plan d'amélioration",comp:"C2.3",comp_ref:"C2.4",comp_libelle:"Bloc 2 — S’assurer de la satisfaction du client",objectif:"Dans cette mission, tu vas concevoir et exploiter un dispositif de mesure de la satisfaction client adapté au contexte LABORO.",palier:3,option:"commun",dossier:{l:"Bilan satisfaction LABORO — T1 2026",rows:[["NPS global","+18 — objectif +25"],["Taux satisfaction accueil","84%"],["Taux satisfaction conseil","71%"],["Taux satisfaction délais","58% — point critique"],["Taux satisfaction prix","63%"],["Clients perdus ce trimestre","7 — dont 4 pour délais"]]},contexte:"Marco Pellini te présente le bilan T1 et te dit : 'On a perdu 4 clients à cause des délais. C'est inacceptable. Je veux un plan d'action complet d'ici lundi.'",contexte_pvoc:"Marco Pellini te présente le bilan satisfaction B2B T1 2026. 4 clients CE ont été perdus à cause des délais de livraison. Nina Chevalier te demande un plan d'action complet d'ici lundi — dans le contexte spécifique de la relation client B2B à distance.",activites:[{t:"Analyser et diagnostiquer",q:["1.1  Calculer le manque à gagner estimé des 7 clients perdus (panier moyen B2C : 187 €, fréquence annuelle estimée : 3 achats). À quel CA perdu cela correspond-il sur un an ?","1.2  Le problème de délais : identifier les 3 causes les plus probables dans l'organisation LABORO et classer par ordre de priorité d'action.","1.3  Rédiger les 2 questions à ajouter à la prochaine enquête satisfaction pour mieux comprendre ce problème de délais."]},{t:"Construire le plan et réfléchir",q:["2.1  Proposer un plan d'amélioration sur 3 mois — 4 actions concrètes avec responsable, délai, budget estimé, indicateur de succès.","2.2  Réflexivité : si tu avais détecté ce problème de délais 3 mois plus tôt, qu'aurais-tu pu faire ? Qu'est-ce que ça t'apprend sur l'importance de la veille interne ?"]}],livrable:"Calcul CA perdu + 3 causes + 2 questions enquête + plan 4 actions + réflexivité",criteres:[{"c":"Conception du dispositif","i":"Le dispositif proposé est cohérent avec les objectifs et les contraintes de LABORO"},{"c":"Maîtrise des indicateurs","i":"Je calcule et interprète tous les indicateurs avec précision"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont priorisées, justifiées et réalisables"},{"c":"Vision client","i":"Mon analyse place le client au centre et fait le lien avec la fidélisation"}],reflexivite_q:"Que révèlent les résultats d'une enquête de satisfaction sur les priorités d'amélioration de LABORO ? Quelles limites vois-tu à ce type d'outil ?",reflexivite:3},
  {id:"M082",titre:"Gérer une crise client et en tirer les enseignements",comp:"C2.2",comp_ref:"C2.3",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",objectif:"Dans cette mission, tu vas gérer des situations de réclamation complexes de façon autonome, en préservant la relation client et l'image de LABORO.",palier:3,option:"commun",dossier:{l:"Incident — livraison Mairie d'Évry-Courcouronnes",rows:[["Commande","50 ballons Pro Match T5 + 20 filets — 4 850 € HT"],["Problème","15 ballons livrés défectueux — coutures décollées"],["Moment","Veille du tournoi municipal — demain 9h"],["Réaction client","David Chemin appelle — mécontent — menace de résiliation"],["Fournisseur","le fournisseur de ballons — SAV joignable jusqu'à 18h"],["Stock LABORO","12 ballons Pro Match T5 disponibles — 3 manquants"]]},contexte:"Tu décroches le téléphone. C'est David Chemin, furieux. Romain Sauzet est absent. Tu dois gérer seul(e) cette crise — et vite.",contexte_pvoc:"Le CE PSA Stellantis t'appelle : 15 des 30 vestes softshell livrées ont un logo mal centré. L'événement d'entreprise est dans 48h. Nina Chevalier est en déplacement. Tu dois gérer seul(e) cette crise à distance.",activites:[{t:"Gérer la crise en temps réel",q:["1.1  David Chemin t'appelle, furieux : 15 des 50 ballons Pro Match T5 livrés sont défectueux (coutures décollées) et le tournoi municipal est demain 9h. Quelles sont tes 3 premières actions dans les 15 minutes ? Justifie chaque choix.","1.2  Le stock LABORO ne contient que 12 ballons Pro Match T5 disponibles (3 manquants pour les 15 à remplacer). Propose 2 solutions alternatives en évaluant les avantages et inconvénients de chacune, sachant que le SAV Pro Match est joignable jusqu'à 18h."]},{t:"Capitaliser et prévenir",q:["2.1  Après la crise, rédige en 5 points le compte rendu à transmettre à Romain Sauzet : faits, causes, solution apportée, satisfaction de David Chemin, action corrective.","2.2  Quelle procédure de contrôle à la livraison aurais-tu pu mettre en place pour éviter cette situation ? Propose une amélioration concrète du process de réception des commandes fournisseurs chez LABORO."]}],criteres:[{"c":"Gestion autonome de la complexité","i":"Je gère la réclamation de bout en bout sans aide, même dans une situation difficile"},{"c":"Maîtrise de la méthode","i":"ERESA est appliquée avec fluidité — sans lecture du support"},{"c":"Qualité argumentative","i":"Mon argumentaire est structuré, professionnel et adapté au contexte"},{"c":"Préservation de l'image LABORO","i":"Ma gestion préserve la réputation et la relation commerciale de LABORO"},{"c":"Propositions d'amélioration","i":"Je propose des actions pour éviter la récidive de ce type de réclamation"}],reflexivite_q:"Qu'est-ce qui te paraît le plus difficile dans la gestion d'une réclamation complexe ? Comment la méthode ERESA t'a-t-elle aidé à structurer ta réponse ?",reflexivite:3},
  {id:"M083",titre:"Construire et présenter un bilan de compétences commerciales",comp:"C1.2",comp_ref:"C1.2",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",objectif:"Dans cette mission, tu vas mener une vente omnicanale complexe en adaptant ton argumentation au profil client et en gérant les objections avec méthode.",palier:3,option:"commun",dossier:{l:"Bilan de période de stage — retour terrain",rows:[["Durée du stage","6 semaines"],["Entreprise d'accueil","Entreprise sportive (similaire à LABORO)"],["Missions effectuées","Accueil clients · Vente · Encaissement · Gestion réclamations"],["Points forts identifiés","Accueil et écoute client · Présentation des produits"],["Points à améliorer","Argumentation prix · Conclusion de vente · Gestion objections"],["CA ventes réalisées","estimé 8 400 € sur la période"]]},contexte:"De retour de stage, Romain Sauzet te demande de préparer un bilan professionnel complet à présenter à l'équipe LABORO. C'est aussi l'occasion d'identifier tes axes de progression.",contexte_pvoc:"De retour de PFMP dans une entreprise de vente B2B à distance, Nina Chevalier te demande de préparer ton bilan professionnel à présenter à l'équipe LABORO — en te focalisant sur les compétences de prospection et de relation client à distance.",activites:[{t:"Analyser et structurer le bilan",q:["1.1  Sur les 5 dernières ventes enregistrées dans LABORO Connect, calcule ton taux de transformation et ta valeur panier moyenne. Que constates-tu ?","1.2  Identifie ta compétence la plus forte et ta compétence à améliorer en vente. Appuie-toi sur des exemples concrets de missions réalisées."]},{t:"Présenter et projeter",q:["2.1  Prépare ta présentation de bilan (5 min max) à Romain Sauzet : résultats, points forts, axes d'amélioration, objectif pour le prochain mois.","2.2  Suite à ce bilan, fixe-toi 2 objectifs SMART pour le mois prochain. Pour chaque objectif : indicateur, cible chiffrée, délai, action concrète."]},{t:"Analyser et concevoir",q:["3.1  En t'appuyant sur ton bilan, quel type de formation ou d'entraînement te permettrait de progresser le plus rapidement ? Justifie ton choix."]}],criteres:[{"c":"Adaptation au profil client","i":"Mon approche est clairement différenciée selon le profil (B2C/B2B, SONCAS identifié)"},{"c":"Maîtrise des techniques","i":"J'applique CAB, SONCAS et traitement des objections de façon fluide et cohérente"},{"c":"Gestion de la complexité","i":"Je gère correctement les situations imprévues ou les clients difficiles"},{"c":"Argumentation omnicanale","i":"J'intègre la dimension omnicanale (site, réseaux, showroom) dans la démarche de vente"}],reflexivite_q:"Si tu devais présenter ta technique de vente à un jury professionnel, quels arguments aurais-tu mis en avant ? Qu'aurais-tu pu faire différemment pour mieux cerner les besoins du client ?",reflexivite:3},
  {id:"M084",titre:"Piloter une opération de prospection de A à Z",comp:"B4.3",comp_ref:"C4B.3",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",objectif:"Dans cette mission, tu vas conduire une négociation commerciale B2B de bout en bout, de la prise de contact à la proposition commerciale.",palier:3,option:"PVOC",dossier:{l:"Bilan opération clubs sportifs — 4 semaines",rows:[["Prospects contactés","41"],["RDV obtenus","14 — taux 34%"],["Devis envoyés","9"],["Contrats signés","3 — CA 22 100 € HT"],["Objectif initial","5 contrats"],["Coût opération","420 €"],["ROI","(22 100 − 420) ÷ 420 × 100 = 5 162%"]]},contexte:"Nina Chevalier analyse le bilan avec toi. L'objectif de 5 contrats n'est pas atteint — 3 seulement. Elle te confie la conception et le pilotage de la prochaine opération avec un objectif plus ambitieux.",activites:[{t:"Analyser et concevoir",q:["1.1  A partir des données de prospection du dossier, calcule le taux de transformation appels/RDV et RDV/ventes. Que révèlent ces indicateurs sur la performance de l'équipe ?","1.2  Identifie les 3 points faibles de l'opération de prospection actuelle. Pour chacun, propose une action corrective concrète et chiffrée.","1.3  Prépare les 5 objections les plus probables et une réponse argumentée + chiffrée pour chacune."]},{t:"Piloter et réfléchir",q:["2.1  Définis le tableau de bord de suivi de l'opération : 4 indicateurs, formules, fréquence de mesure, seuils d'alerte.","2.2  Après 3 semaines, les résultats sont en dessous des objectifs. Quelle décision prends-tu ? Justifie en analysant les causes probables."]}],criteres:[{"c":"Conduite de la négociation","i":"Je mène la négociation de bout en bout avec fluidité et méthode"},{"c":"Adaptation à l'interlocuteur","i":"Mon approche s'adapte au profil et aux enjeux de l'interlocuteur B2B"},{"c":"Proposition commerciale","i":"Ma proposition est construite, argumentée et adaptée aux besoins identifiés"},{"c":"Conclusion","i":"Je concluis la négociation de façon professionnelle (accord, étape suivante, suivi)"}],reflexivite_q:"Qu'as-tu appris sur ta propre façon de gérer une négociation B2B à travers cette mission ? Qu'aurais-tu fait différemment ?",reflexivite:3},
  {id:"M085",titre:"Défendre l'offre LABORO face à un appel d'offres concurrentiel",comp:"B4.5",comp_ref:"C4B.5",comp_libelle:"Bloc 4B — Valoriser les produits et/ou les services",objectif:"Dans cette mission, tu vas élaborer et présenter une offre commerciale complexe pour LABORO, en intégrant les besoins spécifiques du client.",palier:3,option:"PVOC",dossier:{l:"Appel d'offres — ArianeGroup Massy — 28 000 €/an",rows:[["Critères annoncés","Prix 40% · SAV 30% · Conseil 20% · Délais 10%"],["Offre Decathlon Pro","Prix HT estimé : 24 200 € · Remise 8%"],["Offre SportRun Pro","Prix HT estimé : 25 800 € · Remise 5%"],["Offre LABORO à construire","Budget cible : 26 500 € HT — marge min 38%"],["Délai de décision","3 semaines"],["Enjeu","Premier grand compte CE pour LABORO Essonne"]]},contexte:"C'est le RDV le plus important de l'année. Sébastien Foulon attend ta proposition définitive vendredi. Pascal Berruelle compte sur toi.",activites:[{t:"Construire et défendre la proposition",q:["1.1  Analyser les 4 critères de décision. Sur lesquels LABORO peut-il objectivement gagner contre Decathlon Pro ? Construire le tableau comparatif argumenté.","1.2  Concevoir la proposition commerciale complète — 3 niveaux d'offre permettant à Sébastien Foulon de choisir selon son budget réel.","1.3  Préparer les 5 objections les plus probables et une réponse argumentée + chiffrée pour chacune."]},{t:"Conclure et capitaliser",q:["2.1  Sébastien Foulon demande -15% supplémentaires. Rédiger ta réponse complète — négociation, contrepartie proposée, limite à ne pas franchir.","2.2  Réflexivité : que t'a appris ce dossier sur l'art de vendre de la valeur plutôt que du prix ? Comment vas-tu intégrer ces enseignements dans ta pratique quotidienne ?"]}],livrable:"Tableau comparatif + 3 niveaux d'offre + 5 objections/réponses + réponse négociation + réflexivité",criteres:[{"c":"Offre complète et personnalisée","i":"L'offre est entièrement adaptée aux besoins spécifiques du client B2B"},{"c":"Argumentation experte","i":"L'argumentation mobilise des techniques avancées (ROI, références clients, garanties)"},{"c":"Présentation convaincante","i":"La présentation est structurée pour maximiser l'impact sur le décideur"},{"c":"Gestion des objections anticipée","i":"J'anticipe les objections probables et prépare des réponses adaptées"}],reflexivite_q:"En quoi la personnalisation d'une offre B2B est-elle un avantage concurrentiel pour LABORO ? Qu'est-ce qui fait qu'une offre convainc vraiment un décideur ?",reflexivite:3},
  {id:"M086",titre:"Analyser ses résultats de prospection et se fixer un cap",comp:"B4.1",comp_ref:"C4B.1",comp_libelle:"Bloc 4B — Rechercher et analyser les informations à des fins d’exploitation",objectif:"Dans cette mission, tu vas construire une base de prospection qualifiée et définir une stratégie d'approche adaptée aux cibles B2B de LABORO.",palier:3,option:"PVOC",dossier:{l:"Tableau de bord personnel — 8 semaines de prospection",rows:[["Appels passés","147"],["Prospects qualifiés","38 — taux 26%"],["RDV obtenus","16 — taux 42% sur contacts"],["Devis envoyés","9"],["Contrats signés","2 — CA 14 300 € HT"],["Objectif attendu","4 contrats"],["Taux de transformation","22% devis-contrat"]]},contexte:"Nina Chevalier te remet ton tableau de bord personnel des 8 dernières semaines. Elle te dit : 'Les chiffres parlent — mais toi, qu'est-ce que tu en penses ?'",activites:[{t:"Analyser et comprendre",q:["1.1  Analyser ta chaîne de conversion étape par étape. Où perds-tu le plus de prospects ? Formuler au moins 2 hypothèses explicatives basées sur ton vécu terrain.","1.2  Calculer l'écart entre tes résultats et l'objectif en nombre de contrats et en CA. Qu'est-ce que ça représente concrètement pour LABORO ?","1.3  Identifier les 3 situations de prospection où tu te sens le moins à l'aise. Pour chacune, proposer un exercice d'entraînement concret."]},{t:"Se projeter et réfléchir",q:["2.1  Fixer tes propres objectifs pour les 8 prochaines semaines — réalistes et ambitieux. Les justifier par l'analyse de tes points forts et points faibles.","2.2  Réflexivité : qu'est-ce que 8 semaines de prospection t'ont appris sur toi-même en tant que futur(e) commercial(e) ? Qu'est-ce qui te surprend dans tes propres résultats ?"]}],livrable:"Analyse chaîne conversion + calcul écart + 3 points faibles + entraînements + objectifs personnels + réflexivité",criteres:[{"c":"Base de prospection qualifiée","i":"La base construite est complète, qualifiée et exploitable"},{"c":"Stratégie d'approche","i":"La stratégie d'approche est adaptée aux différents profils de prospects"},{"c":"Planification","i":"Le plan de prospection est réaliste et priorisé"},{"c":"Argumentation","i":"Les choix sont justifiés par des données et des arguments commerciaux solides"}],reflexivite_q:"Quels critères de qualification d'un prospect te semblent les plus importants pour LABORO ? Pourquoi certains prospects sont-ils plus prioritaires que d'autres ?",reflexivite:3},
  {id:"M087",titre:"Gérer une réclamation client complexe et en tirer les leçons",comp:"C2.2",comp_ref:"C2.3",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",objectif:"Dans cette mission, tu vas gérer des situations de réclamation complexes de façon autonome, en préservant la relation client et l'image de LABORO.",palier:3,option:"commun",dossier:{l:"Réclamation — CE PSA Stellantis",rows:[["Client","Isabelle Faure — CE PSA — CA 22 400 €/an"],["Problème","30 vestes softshell livrées avec mauvais logo — événement dans 48h"],["Réaction","Isabelle Faure demande remboursement total + dédommagements"],["Fournisseur","notre atelier de flocage — joignable jusqu'à 17h"],["Montant en jeu","1 770 € HT + risque de perte du compte (22 400 €/an)"],["Stock LABORO","Aucune veste en stock — délai réassort 3 semaines"]]},contexte:"Tu es seul(e) au bureau quand Isabelle Faure appelle. Nina Chevalier est en déplacement. Tu as 2 heures pour trouver une solution et la rappeler.",contexte_pvoc:"Le CE PSA Stellantis (22 400 €/an de CA) t'appelle : 30 vestes softshell livrées avec le mauvais logo. L'événement est dans 48h. Nina Chevalier est absente. Tu dois gérer seul(e) cette crise en combinant appels, mails et coordination fournisseur.",activites:[{t:"Gérer l'urgence",q:["1.1  Rédiger le script de rappel à Isabelle Faure dans les 2 heures — solution proposée, délai de traitement, engagement personnel.","1.2  Quelles démarches effectues-tu auprès de notre atelier de flocage dans les 30 minutes ? Quel est ton objectif minimal pour ce soir ?","1.3  Si notre atelier de flocage ne peut pas livrer à temps, quelles solutions alternatives explores-tu ? Lister toutes les options possibles."]},{t:"Capitaliser et transmettre",q:["2.1  Rédiger le rapport d'incident pour Nina Chevalier et Pascal Berruelle — faits, actions, résultat, coût estimé, procédure recommandée pour éviter la récidive.","2.2  Réflexivité : comment as-tu géré le stress de cette situation ? Qu'est-ce que ça t'apprend sur ta capacité à prendre des décisions seul(e) sous pression ?"]}],livrable:"Script rappel Isabelle Faure + démarches notre atelier de flocage + solutions alternatives + rapport + réflexivité",criteres:[{"c":"Gestion autonome de la complexité","i":"Je gère la réclamation de bout en bout sans aide, même dans une situation difficile"},{"c":"Maîtrise de la méthode","i":"ERESA est appliquée avec fluidité — sans lecture du support"},{"c":"Qualité argumentative","i":"Mon argumentaire est structuré, professionnel et adapté au contexte"},{"c":"Préservation de l'image LABORO","i":"Ma gestion préserve la réputation et la relation commerciale de LABORO"},{"c":"Propositions d'amélioration","i":"Je propose des actions pour éviter la récidive de ce type de réclamation"}],reflexivite_q:"Qu'est-ce qui te paraît le plus difficile dans la gestion d'une réclamation complexe ? Comment la méthode ERESA t'a-t-elle aidé à structurer ta réponse ?",reflexivite:3},
  {id:"M090",titre:"Concevoir la stratégie commerciale de LABORO et la défendre",comp:"C1.2",comp_ref:"C1.2",objectif:"Dans cette mission, tu vas optimiser la performance commerciale de LABORO en analysant les indicateurs de vente et en proposant des actions d'amélioration.",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",palier:4,option:"AGEC",dossier:{l:"Données stratégiques LABORO — bilan annuel",rows:[["CA annuel","1 120 000 € — +9% vs N-1"],["Marge moyenne","43,5%"],["Part B2B","40% du CA"],["NPS global","+22"],["Taux de fidélisation","74%"],["Objectif Pascal Berruelle","CA 1 300 000 € dans 2 ans"],["Contexte","SportRun Évry a ouvert un 2e magasin à Massy"]]},contexte:"Pascal Berruelle t'annonce : 'Je veux qu'une équipe de stagiaires construise la stratégie commerciale de LABORO pour les 2 prochaines années. Je te confie la coordination.' C'est la mission de Terminale la plus complexe.",activites:[{t:"Construire la stratégie",q:["1.1  Réaliser une analyse SWOT complète de LABORO à partir de toutes les données disponibles dans la plateforme. Identifier les 3 axes stratégiques prioritaires.","1.2  Décliner l'objectif de 1 300 000 € de CA en objectifs annuels, par rayon et par canal. Justifier la répartition.","1.3  Proposer 3 initiatives stratégiques majeures pour les 24 mois — chacune avec sa logique, ses ressources nécessaires, ses risques et ses indicateurs de succès."]},{t:"Défendre et réfléchir",q:["2.1  Anticiper les 5 objections que Pascal Berruelle pourrait formuler face à cette stratégie et préparer une réponse argumentée pour chacune.","2.2  Réflexivité approfondie : en quoi cette mission de construction stratégique est-elle différente de toutes les missions que tu as réalisées jusqu'ici ? Qu'est-ce que ça révèle sur ta façon de penser le commerce ?"]},{t:"Prendre du recul (réflexivité experte)",q:["3.1  Avec du recul, quels sont les 2 risques majeurs de cette strategie commerciale ? Que feriez-vous differemment si vous etiez PDG depuis 3 ans ?"]}],livrable:"SWOT complet + objectifs déclinés + 3 initiatives + 5 objections/réponses + réflexivité approfondie",criteres:[{"c":"Analyse des indicateurs de vente","i":"J'identifie les indicateurs pertinents et les interprète correctement"},{"c":"Recommandations stratégiques","i":"Mes propositions d'amélioration sont justifiées et opérationnelles"},{"c":"Maîtrise experte","i":"Mon niveau de maîtrise est celui attendu pour les épreuves CCF (E31)"},{"c":"Recul professionnel","i":"Je fais le lien entre cette compétence et d'autres situations professionnelles"}],reflexivite_q:"En quoi la maîtrise de la vente omnicanale est-elle un avantage concurrentiel pour LABORO ? Comment cette compétence te sera utile dans d'autres contextes professionnels ?",reflexivite:4},
  {id:"M091",titre:"Créer et animer un dispositif de veille partagée",comp:"C1.1",comp_ref:"C1.1",objectif:"Dans cette mission, tu vas construire et piloter une stratégie de veille commerciale complète, en intégrant plusieurs sources et en produisant une analyse stratégique.",comp_libelle:"Bloc 1 — Assurer la veille commerciale",palier:4,option:"AGEC",dossier:{l:"Situation veille LABORO — diagnostic",rows:[["Notes de veille produites","3 ce trimestre — objectif 1/semaine"],["Partage avec l'équipe","Inexistant — chacun surveille de son côté"],["Nouvelles concurrences","SportRun Évry a ouvert à Massy — nouveaux acteurs e-commerce"],["Informations manquées","Promo Decathlon -20% — repérée 1 semaine après le lancement"],["Demande Pascal Berruelle","Un système de veille collectif opérationnel d'ici 30 jours"]]},contexte:"Pascal Berruelle t'a choisi(e) pour concevoir ET animer le système de veille de toute l'équipe LABORO. Ce n'est pas juste un document — c'est un vrai projet de changement organisationnel.",activites:[{t:"Concevoir le dispositif",q:["1.1  Concevoir l'architecture complète du système de veille LABORO — sources, fréquences, responsables, format des notes, circuit de diffusion.","1.2  Créer les outils du dispositif : modèle de note de veille, tableau de bord des signaux, protocole de partage en réunion hebdomadaire.","1.3  Anticiper les 3 freins principaux à l'adoption par l'équipe et proposer une stratégie pour chacun."]},{t:"Animer et pérenniser",q:["2.1  Rédiger le plan d'animation sur 3 mois — comment tu vas embarquer l'équipe, animer les premières semaines, mesurer l'appropriation.","2.2  Réflexivité : en quoi passer du rôle d'observateur à celui de concepteur et d'animateur d'un système change-t-il ta façon de concevoir ton rôle professionnel ?"]},{t:"Auto-évaluer le dispositif",q:["3.1  Auto-evaluez ce dispositif de veille : qu'est-ce qui fonctionnera vraiment ? Qu'est-ce qui risque de ne pas tenir dans la duree ? Proposez une amelioration."]}],livrable:"Architecture système + 3 outils + 3 freins/stratégies + plan animation 3 mois + réflexivité sur posture professionnelle",criteres:[{"c":"Vision stratégique","i":"Mon analyse intègre plusieurs dimensions (concurrence, tendances, clientèle)"},{"c":"Argumentation experte","i":"Chaque recommandation est justifiée par des données et des arguments solides"},{"c":"Opérationnalité","i":"Le dispositif de veille proposé est applicable et réaliste pour LABORO"},{"c":"Recul critique","i":"Je prends du recul sur les limites de la veille réalisée"}],reflexivite_q:"Comment la veille commerciale que tu viens de réaliser pourrait-elle influencer une décision concrète de Pascal Berruelle ? Que ferais-tu différemment avec plus de moyens ?",reflexivite:4},
  {id:"M092",titre:"Piloter l'expérience client LABORO de bout en bout",comp:"C4A.2",comp_ref:"C4A.2",objectif:"Dans cette mission, tu vas piloter l'attractivité de l'espace commercial LABORO en évaluant les actions menées et en proposant des optimisations.",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",palier:4,option:"AGEC",dossier:{l:"Diagnostic expérience client — showroom Évry",rows:[["Score parcours client global","6,8/10 — objectif 8,5/10"],["Point de friction n°1","Signalétique insuffisante — 42% de satisfaction"],["Point de friction n°2","Temps d'attente caisse — 60% de satisfaction"],["Point de friction n°3","Manque de prix affichés — verbatim récurrent"],["CA perdu estimé","3 clients perdus/semaine × 187 € = 561 €/semaine"],["Budget alloué","800 € pour l'ensemble des améliorations"]]},contexte:"Pascal Berruelle te confie la refonte complète de l'expérience client du showroom. 'Je veux que dans 3 mois, chaque client qui pousse notre porte reparte avec l'envie de revenir.' Budget : 800 €.",activites:[{t:"Concevoir la refonte",q:["1.1  Prioriser les 3 points de friction par impact sur le CA et la satisfaction. Pour chaque point : action concrète, coût estimé, délai de mise en oeuvre.","1.2  Concevoir le nouveau parcours client LABORO de A à Z — de l'arrivée sur le parking à la prise de congé. Décrire chaque étape, les points de contact et l'émotion visée.","1.3  Ventiler les 800 € entre les actions en justifiant chaque allocation. Identifier des solutions à coût zéro."]},{t:"Déployer et mesurer",q:["2.1  Rédiger le plan de déploiement — qui fait quoi, dans quel ordre, comment on mesure.","2.2  Réflexivité : que t'a appris la conception de ce parcours client sur la vision systémique du commerce ? En quoi ça change ta façon d'observer un point de vente ?"]},{t:"Tirer un apprentissage personnel",q:["3.1  En prenant du recul sur cette operation, quel apprentissage personnel en tirez-vous ? Quel indicateur aurait du etre suivi des le debut ?"]}],livrable:"Priorisation 3 points + nouveau parcours client + budget ventilé + plan déploiement + réflexivité systémique",criteres:[{"c":"Expertise merchandising","i":"Mon analyse mobilise des concepts avancés (PLV, théâtralisation, parcours client)"},{"c":"Vision stratégique","i":"Mes recommandations s'inscrivent dans la stratégie globale de LABORO"},{"c":"Mesure de la performance","i":"Je propose un suivi chiffré des actions d'amélioration"},{"c":"Recul critique","i":"Je prends du recul sur les limites de mon diagnostic"}],reflexivite_q:"Comment l'amélioration de l'espace commercial de LABORO peut-elle avoir un impact sur la performance commerciale globale ?",reflexivite:4},
  {id:"M093",titre:"Concevoir la stratégie B2B de LABORO et former l'équipe",comp:"B4.2",comp_ref:"C4B.2",objectif:"Dans cette mission, tu vas optimiser une stratégie de prospection existante de LABORO en analysant les résultats et en proposant des ajustements.",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",palier:4,option:"PVOC",dossier:{l:"Ambition B2B LABORO — cap 2 ans",rows:[["CA B2B actuel","448 000 € — 40% du CA"],["Objectif CA B2B N+2","650 000 € — +45%"],["Clients B2B actifs","24"],["Taux de fidélisation B2B","74%"],["Budget développement B2B","2 500 €/an"],["Ressource commerciale","1 commercial terrain 3j/semaine"],["Concurrent","Decathlon Pro cible les mêmes CE et collectivités"]]},contexte:"Pascal Berruelle te confie la mission la plus stratégique de LABORO : concevoir le plan de développement B2B sur 2 ans ET former les 2 nouveaux commerciaux qui viennent d'être recrutés.",activites:[{t:"Concevoir la stratégie",q:["1.1  Segmenter le marché B2B Essonne en 4 cibles et définir la priorité de chacune. Calculer le potentiel CA réaliste sur 2 ans pour chaque segment.","1.2  Concevoir le plan de prospection annuel — volumes, techniques, budget mensuel, objectifs trimestriels.","1.3  Définir la proposition de valeur LABORO différenciée par segment — 3 arguments ciblés par cible."]},{t:"Former et réfléchir",q:["2.1  Concevoir le plan de formation de 2 heures pour les 2 nouveaux commerciaux — objectifs pédagogiques, contenus, exercices pratiques, évaluation.","2.2  Réflexivité : qu'est-ce que le fait de former quelqu'un te révèle sur ce que tu maîtrises vraiment et ce que tu maîtrises moins ? En quoi enseigner est-il la meilleure façon d'apprendre ?"]},{t:"Évaluer les risques de la stratégie",q:["3.1  Quel est le risque principal d'echec de cette strategie B2B ? Comment l'anticipez-vous concretement ?"]}],livrable:"4 segments + plan prospection annuel + propositions de valeur + plan formation 2h + réflexivité sur transmission",criteres:[{"c":"Vision stratégique","i":"L'optimisation proposée s'inscrit dans la stratégie commerciale globale de LABORO"},{"c":"Analyse des résultats","i":"Mon analyse des résultats est complète et s'appuie sur des données précises"},{"c":"Recommandations expertes","i":"Mes recommandations sont argumentées, chiffrées et opérationnelles"},{"c":"Recul professionnel","i":"Je fais le lien entre prospection et fidélisation dans la stratégie LABORO"}],reflexivite_q:"En quoi la qualité de la préparation conditionne-t-elle le succès d'une campagne de prospection pour LABORO ?",reflexivite:4},
  {id:"M094",titre:"Analyser et optimiser le portefeuille clients B2B",comp:"B4.4",comp_ref:"C4B.4",objectif:"Dans cette mission, tu vas piloter la performance commerciale de LABORO en construisant un tableau de bord et en proposant des actions correctives.",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",palier:4,option:"PVOC",dossier:{l:"Analyse portefeuille B2B LABORO — 24 clients actifs",rows:[["CA cumulé 24 clients","448 000 €/an"],["Top 3 clients","CE PSA 22 400 € · Mairie Évry 14 800 € · ArianeGroup 12 600 €"],["Clients < 3 000 €/an","11 clients — CA total 18 700 €"],["Taux de fidélisation","74% — soit 6 clients perdus l'an dernier"],["CA moyen par client","18 667 €"],["Fréquence d'achat moyenne","3,2 commandes/an"]]},contexte:"Nina Chevalier te présente l'analyse du portefeuille et te demande de construire la stratégie de gestion de la relation client B2B pour les 12 prochains mois.",activites:[{t:"Analyser et segmenter",q:["1.1  Appliquer la loi de Pareto (80/20) au portefeuille. Combien de clients représentent 80% du CA ? Qu'est-ce que ça implique en termes de priorité de gestion ?","1.2  Segmenter les 24 clients en 3 catégories : comptes stratégiques (à chouchouter), comptes à développer, comptes à risque. Définir les critères de chaque catégorie.","1.3  Pour chacune des 3 catégories, définir la stratégie de relation client — fréquence de contact, type de contact, objectif annuel."]},{t:"Piloter et réfléchir",q:["2.1  Concevoir le plan de compte pour ArianeGroup (12 600 €/an) — comment doubler ce CA en 12 mois ? Étapes, actions, indicateurs.","2.2  Réflexivité : en quoi la vision portefeuille est-elle différente de la vision transaction client par client ? Qu'est-ce que cette approche change dans ta façon de travailler au quotidien ?"]},{t:"Identifier sa progression",q:["3.1  Quelle competence avez-vous developpee ou renforcee en realisant cette mission ? Quel aurait ete votre angle mort sans cette analyse ?"]}],livrable:"Analyse Pareto + 3 segments + 3 stratégies relationnelles + plan compte ArianeGroup + réflexivité vision portefeuille",criteres:[{"c":"Vision de pilotage","i":"Mon tableau de bord permet un pilotage efficace de l'activité commerciale de LABORO"},{"c":"Analyse experte","i":"Mon analyse va au-delà des données — elle identifie des tendances et des risques"},{"c":"Recommandations stratégiques","i":"Mes recommandations ont une portée stratégique pour LABORO"},{"c":"Recul professionnel","i":"Je fais le lien entre pilotage commercial et stratégie globale de LABORO"}],reflexivite_q:"Comment utiliser l'analyse des résultats de prospection pour améliorer la stratégie commerciale globale de LABORO ?",reflexivite:4},
  {id:"M095",titre:"Innover dans l'approche commerciale et proposer un nouveau service",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas optimiser une stratégie de prospection existante de LABORO en analysant les résultats et en proposant des ajustements.",palier:4,option:"PVOC",dossier:{l:"Opportunité identifiée — service de dotation sportive",rows:[["Constat","8 CE clients nous ont demandé un service de gestion annuelle des dotations sportives"],["Concept","Contrat annuel forfaitaire : LABORO gère l'ensemble des commandes sportives du CE sur l'année"],["CA potentiel estimé","5 000 à 15 000 €/CE/an"],["Effort commercial","1 RDV de cadrage + suivi trimestriel — pas de prospection répétée"],["Risque","Stock à gérer · Impayés · Dépendance à 1 seul interlocuteur"],["Question","Faut-il lancer ce service ? À quelles conditions ?"]]},contexte:"Pascal Berruelle t'a entendu parler de cette idée à la machine à café. Il te dit : 'Mets ça en forme. Tu as 2 semaines. Si c'est convaincant, on teste avec 3 CE dès la rentrée.'",activites:[{t:"Concevoir et évaluer",q:["1.1  Modéliser le service de dotation sportive — fonctionnement, offre, prix, conditions, différenciation vs la vente classique.","1.2  Réaliser une analyse bénéfices/risques complète. Calculer le CA potentiel si 5 CE signent, et le ROI pour LABORO.","1.3  Définir les 3 conditions impératives pour lancer ce service sans mettre LABORO en danger."]},{t:"Défendre et réfléchir",q:["2.1  Rédiger la note de proposition à Pascal Berruelle — synthétique, argumentée, avec recommandation claire : lancer ou ne pas lancer, et pourquoi.","2.2  Réflexivité : qu'est-ce que le fait d'avoir identifié cette opportunité toi-même, sans qu'on te le demande, dit sur ta posture professionnelle ? En quoi l'initiative et la force de proposition te définissent-ils comme futur(e) professionnel(le) ?"]},{t:"Définir son style professionnel",q:["3.1  En vous appuyant sur cette mission, comment definiriez-vous votre propre style d'innovation commerciale ? Quelles sont vos forces et vos limites ?"]}],livrable:"Modélisation service + analyse bénéfices/risques + calcul CA/ROI + 3 conditions + note Pascal + réflexivité sur initiative",criteres:[{"c":"Vision stratégique","i":"L'optimisation proposée s'inscrit dans la stratégie commerciale globale de LABORO"},{"c":"Analyse des résultats","i":"Mon analyse des résultats est complète et s'appuie sur des données précises"},{"c":"Recommandations expertes","i":"Mes recommandations sont argumentées, chiffrées et opérationnelles"},{"c":"Recul professionnel","i":"Je fais le lien entre prospection et fidélisation dans la stratégie LABORO"}],reflexivite_q:"En quoi la qualité de la préparation conditionne-t-elle le succès d'une campagne de prospection pour LABORO ?",reflexivite:4},
  {id:"M064",titre:"Observer et décrire l'espace de vente LABORO",comp:"C4A.2",comp_ref:"C4A.2",objectif:"Dans cette mission, tu vas observer et analyser l'attractivité de l'espace de vente LABORO en identifiant les composantes du merchandising.",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",palier:1,option:"AGEC",contexte:"C'est ta première semaine au showroom. Romain Sauzet te demande d'observer l'espace de vente et de rédiger une description structurée avant de commencer à toucher quoi que ce soit. 'Avant de changer les choses, il faut les comprendre', dit-il.",activites:[{t:"Observer l'espace de vente",q:["1.1  Décrire en 5 à 8 phrases l'organisation actuelle du showroom LABORO : zones, rayons, mobilier, signalétique. Être précis et factuel — comme si tu décrivais à quelqu'un qui ne l'a jamais vu.","1.2  Identifier les 3 zones chaudes (les plus fréquentées) et les 3 zones froides (les moins visitées) du showroom. Expliquer comment tu les repères sans données chiffrées."]},{t:"Analyser et proposer",q:["2.1  Tu remarques que les Chaussures running EasyRun (le produit le plus vendu selon Romain) sont placés en bas à droite, peu visibles. Expliquer pourquoi c'est un problème selon les règles du merchandising.","2.2  Proposer 2 changements simples dans l'organisation du rayon chaussures pour améliorer la visibilité des produits phares. Justifier chaque changement avec une règle de merchandising."]}],livrable:"Description structurée showroom + 3 zones chaudes/froides + problème placement LABORO + 2 changements justifiés",criteres:[{"c":"Identification des composantes","i":"Je cite et décris correctement les composantes de l'attractivité d'un espace de vente"},{"c":"Observation structurée","i":"Mon observation suit un plan logique (agencement, signalétique, produits, ambiance...)"},{"c":"Lien avec LABORO","i":"Je relie mes observations au contexte sportif et outdoor de LABORO"}],reflexivite:0},
  {id:"M065",titre:"Identifier les produits phares et leur argumentation",comp:"C1.2",comp_ref:"C1.2",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",objectif:"Dans cette mission, tu vas identifier les étapes d'un entretien de vente et repérer les techniques de découverte et d'argumentation utilisées chez LABORO.",palier:1,option:"AGEC",contexte:"Romain Sauzet te remet le catalogue LABORO et te dit : 'Avant de conseiller un client, tu dois connaître nos produits sur le bout des doigts. Je veux que tu prépares une fiche argumentaire sur nos 5 produits les plus vendus.'",activites:[{t:"Découvrir et analyser les produits",q:["1.1  À partir du catalogue LABORO, identifier les 5 produits avec le meilleur ratio marge/vente. Pour chacun : nom, prix de vente, marge en %, 1 caractéristique technique clé.","1.2  Choisir le produit que tu trouves le plus facile à argumenter. Rédiger sa fiche CAB complète : Caractéristique → Avantage → Bénéfice pour le client."]},{t:"Pratiquer l'argumentation",q:["2.1  Un client entre et dit : 'Je cherche une chaussure de sport pour débuter, je ne veux pas dépenser trop.' Quelle question poses-tu en premier ? Quel produit proposes-tu ? Rédiger les 4 premières phrases de ton conseil.","2.2  Le client demande : 'Complète cet argument : Chez LABORO vous bénéficiez d'un ___ personnalise, d'une ___ experte et d'un suivi ___ en Essonne. ?' Rédiger ta réponse en 3 arguments courts et percutants."]}],livrable:"5 produits analysés + fiche CAB complète + 4 premières phrases conseil + 3 arguments LABORO vs Decathlon",criteres:[{"c":"Connaissance des étapes de vente","i":"J'identifie correctement les phases de l'entretien de vente (accueil, découverte, argumentation, conclusion)"},{"c":"Repérage des techniques","i":"Je repère les questions ouvertes, les arguments CAB et les signaux d'achat dans la situation décrite"},{"c":"Posture professionnelle","i":"Je décris les attitudes attendues d'un(e) conseiller(ère) de vente chez LABORO"}],reflexivite:0},
  {id:"M066",titre:"Préparer le rayon pour l'ouverture",comp:"C4A.2",comp_ref:"C4A.2",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",objectif:"Dans cette mission, tu vas observer et analyser l'attractivité de l'espace de vente LABORO en identifiant les composantes du merchandising.",palier:1,option:"AGEC",contexte:"Romain Sauzet t'explique que chaque matin, avant l'ouverture du showroom à 10h, l'équipe effectue une série de vérifications pour s'assurer que le rayon est prêt à accueillir les clients. Il te demande de réaliser cette routine seul(e) demain matin.",activites:[{t:"Préparer la checklist d'ouverture",q:["1.1  Lister les 8 actions à effectuer chaque matin avant ouverture dans un rayon sport : propreté, réassort, étiquettes, PLV, facing, éclairage, signalétique, sécurité antivol. Pour chaque action, expliquer pourquoi elle est importante pour le client.","1.2  Tu constates en arrivant ce matin que 3 chaussures sport sont disposées au sol, hors de leur boîte, sans étiquette de prix. Décrire ta démarche pour régulariser la situation avant l'ouverture."]},{t:"Gérer une situation imprévue",q:["2.1  À 9h50, tu reçois une livraison de 12 cartons de ballons Pro Match T5. L'ouverture est dans 10 minutes et tu es seul(e). Comment gères-tu la situation ?","2.2  Rédiger la checklist d'ouverture définitive que tu remettrais à un(e) nouveau(elle) collègue — claire, rapide à exécuter, dans le bon ordre."]}],livrable:"8 actions checklist justifiées + régularisation chaussures + gestion livraison + checklist définitive rédigée",criteres:[{"c":"Identification des composantes","i":"Je cite et décris correctement les composantes de l'attractivité d'un espace de vente"},{"c":"Observation structurée","i":"Mon observation suit un plan logique (agencement, signalétique, produits, ambiance...)"},{"c":"Lien avec LABORO","i":"Je relie mes observations au contexte sportif et outdoor de LABORO"}],reflexivite:0},
  {id:"M067",titre:"Comprendre et expliquer les documents de vente",comp:"C1.3",comp_ref:"C1.3",comp_libelle:"Bloc 1 — Assurer l’exécution de la vente",objectif:"Dans cette mission, tu vas identifier les opérations à réaliser après une vente chez LABORO — bon de commande, suivi, remise de documentation.",palier:1,option:"AGEC",contexte:"Romain Sauzet te montre plusieurs documents liés aux ventes de la semaine : tickets de caisse, factures, bons de livraison, devis. Il te demande de les analyser et de comprendre le rôle de chacun.",activites:[{t:"Identifier les documents",q:["1.1  Pour chacun des 4 documents suivants, expliquer en 2 phrases à quoi il sert, qui le reçoit et quand il est émis : ticket de caisse, facture, bon de livraison, devis.","1.2  Quelle est la différence entre une vente B2C (particulier) et une vente B2B (entreprise) en termes de documents ? Citer au moins 2 différences concrètes."]},{t:"Calculer et vérifier",q:["2.1  Vérifier la facture suivante : 2 tapis yoga LABORO à 59 € TTC + 1 kettlebell 12kg à 45 € TTC. Calculer le total TTC, le total HT (TVA 20%) et la TVA collectée. La facture indique 147 € HT — y a-t-il une erreur ?","2.2  Un client B2B (Mairie d'Évry) demande une facture avec mention 'TVA non applicable — article 293B'. Que signifie cette mention ? À qui s'applique-t-elle ?"]}],livrable:"4 documents expliqués + 2 différences B2C/B2B + vérification facture + explication mention TVA",criteres:[{"c":"Identification des opérations post-vente","i":"Je décris les opérations à réaliser après une vente chez LABORO (bon de commande, suivi, remise de doc)"},{"c":"Connaissance des documents","i":"Je cite et décris les documents commerciaux utilisés lors de la finalisation d'une vente"},{"c":"Lien avec la relation client","i":"J'explique en quoi ces opérations contribuent à la satisfaction du client"}],reflexivite:0},
  {id:"M068",titre:"Découvrir la fidélisation client chez LABORO",comp:"C3.2",comp_ref:"C3.2",comp_libelle:"Bloc 3 — Contribuer à des actions de fidélisation de la clientèle et de développement de la relation client",objectif:"Dans cette mission, tu vas identifier les actions de fidélisation utilisées par LABORO et comprendre leur logique commerciale.",palier:1,option:"AGEC",contexte:"Romain Sauzet t'explique que LABORO ne vit pas que de nouveaux clients — la fidélisation est au coeur de la stratégie. Il te demande d'analyser les outils de fidélisation existants et d'observer comment ils sont utilisés au quotidien.",activites:[{t:"Observer et comprendre",q:["1.1  Romain te cite 3 outils de fidélisation utilisés par LABORO : carte LABORO PRO, newsletter mensuelle, soirée clients annuelle. Pour chacun, décrire en 3 phrases : comment ça fonctionne, qui en bénéficie, quel est l'objectif.","1.2  M. Vidal est client depuis 3 ans, CA cumulé 2 100 €, mais n'a jamais activé sa carte LABORO PRO. Que représente ce client pour LABORO en termes de valeur ? Pourquoi est-il important de le fidéliser encore plus ?"]},{t:"Agir concrètement",q:["Quel est le meilleur moment pour proposer la carte fidelite ? A) Avant le choix produit — B) Au paiement — C) Apres la transaction.","2.2  Romain Sauzet te demande de relire la liste des 48 clients invités à la dernière soirée. Sur quels critères penses-tu qu'ils ont été sélectionnés ? Proposer 3 critères de sélection logiques et justifier chaque choix."]}],livrable:"3 outils décrits + valeur M. Vidal expliquée + 3 phrases proposition carte PRO + 3 critères sélection soirée",criteres:[{"c":"Identification des actions de fidélisation","i":"Je cite et décris au moins 3 actions de fidélisation utilisées par LABORO"},{"c":"Compréhension des enjeux","i":"J'explique pourquoi fidéliser un client est plus rentable qu'en conquérir un nouveau"},{"c":"Lien avec le contexte LABORO","i":"Je relie les actions identifiées à la clientèle sport & outdoor de LABORO"}],reflexivite:0},
  {id:"M069",titre:"Gérer les informations clients dans LABORO Connect",comp:"C3.1",comp_ref:"C3.1",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",objectif:"Dans cette mission, tu vas identifier les informations clients disponibles chez LABORO et comprendre leur utilité dans la relation commerciale.",palier:1,option:"AGEC",contexte:"Marco Pellini te forme à LABORO Connect, le logiciel de gestion commerciale de LABORO. Il te dit : 'Tout ce qui n'est pas tracé n'existe pas. Si une interaction avec un client n'est pas dans LABORO Connect, elle n'a pas eu lieu pour l'entreprise.'",activites:[{t:"Comprendre l'outil et ses enjeux",q:["1.1  Pourquoi une entreprise comme LABORO a-t-elle besoin d'un logiciel comme LABORO Connect ? Donner 4 raisons concrètes liées au quotidien commercial.","1.2  Marco te montre la fiche client de M. Vidal. Identifier les 6 types d'informations qu'on y trouve et expliquer l'utilité de chacune pour l'équipe LABORO."]},{t:"Agir et tracer",q:["2.1  Mme Konaté vient d'acheter un ballon Pro Match pour son fils. C'est sa première visite chez LABORO. Lister toutes les informations que tu dois saisir dans LABORO Connect après cette vente.","2.2  Tu reçois un appel de M. Fontaine qui te demande où en est sa commande. Après l'avoir renseigné, quelles informations dois-tu mettre à jour dans LABORO Connect pour que la prochaine personne qui décroche puisse répondre sans rappeler le client ?"]}],livrable:"4 raisons LABORO Connect + 6 types informations fiche client + saisie après vente Konaté + mise à jour appel Fontaine",criteres:[{"c":"Identification des informations clients","i":"Je cite les informations clés à collecter sur un client LABORO (nom, type, historique, préférences)"},{"c":"Compréhension de l'utilité","i":"J'explique à quoi servent ces informations dans la relation commerciale"},{"c":"Lecture du fichier clients","i":"Je lis correctement les données du fichier clients LABORO fourni"}],reflexivite:0},
  {id:"M070",titre:"Analyser les résultats commerciaux et préparer un rapport",comp:"C1.1",comp_ref:"C1.1",objectif:"Dans cette mission, tu vas analyser la veille commerciale de LABORO en comparant les offres concurrentes et en identifiant les opportunités de marché.",comp_libelle:"Bloc 1 — Assurer la veille commerciale",palier:2,option:"AGEC",dossier:{l:"Tableau de bord LABORO — comparatif T1 2025 vs T1 2026",rows:[["CA total T1 2026","278 000 € — objectif 250 000 €"],["CA total T1 2025","236 000 €"],["Evolution CA","+ 42 000 € — + 17,8%"],["CA running/sport","98 000 € — vs 83 000 € T1 2025"],["CA textile","61 000 € — vs 47 000 € T1 2025"],["CA outdoor","24 000 € — vs 26 000 € T1 2025"],["Taux de marge moyen","43,2% — vs 41,7% T1 2025"]]},contexte:"Pascal Berruelle prépare la réunion de bilan trimestriel avec les associés. Il te demande de préparer le rapport commercial complet — analyse des évolutions, identification des tendances, recommandations.",activites:[{t:"Analyser les évolutions",q:["1.1  Calculer l'évolution en % de chaque rayon entre T1 2025 et T1 2026. Lequel progresse le plus ? Lequel régresse ?","1.2  Le taux de marge global a progressé de 1,5 point. Identifier 2 causes probables de cette amélioration à partir des données disponibles.","1.3  L'outdoor baisse malgré la croissance globale. Proposer 3 hypothèses explicatives et indiquer comment les vérifier."]},{t:"Synthétiser et recommander",q:["2.1  Pour préparer la synthèse commerciale du T1 destinée aux associés, sélectionne et hiérarchise les éléments réellement indispensables à présenter. Justifie pourquoi tu écartes les éléments non pertinents.","2.2  Définir 3 orientations stratégiques pour le T2 2026 basées sur cette analyse."]}],livrable:"Calcul évolutions + analyse marge + 3 hypothèses outdoor + synthèse associés + 3 orientations T2",criteres:[{"c":"Analyse comparative","i":"Je compare les offres concurrentes de façon structurée (tableau, critères explicites)"},{"c":"Identification des opportunités","i":"Je repère au moins une opportunité ou menace concrète pour LABORO"},{"c":"Justification des conclusions","i":"Mes conclusions s'appuient sur des données précises tirées du dossier"}],reflexivite:0},
  {id:"M071",titre:"Gérer la performance du rayon et optimiser l'implantation",comp:"C4A.2",comp_ref:"C4A.2",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",objectif:"Dans cette mission, tu vas proposer des actions d'amélioration de l'attractivité de l'espace commercial LABORO en justifiant tes choix.",palier:2,option:"AGEC",dossier:{l:"Indicateurs rayon outdoor — mars 2026",rows:[["CA rayon outdoor","24 000 € — -8% vs T1 2025"],["Produit le plus vendu","Tente LABORO Quick — 28 unités"],["Rotation stock tentes","2,1 — objectif : > 3"],["Taux de rupture","14% — objectif : < 2%"],["Produit sans vente","Lampe frontale LABORO — 0 vente ce mois"],["Facing actuel","Tentes au sol zone froide · Lampes au niveau yeux zone chaude"]]},contexte:"Romain Sauzet constate que le rayon outdoor perd du terrain. Il te confie l'analyse et la réorganisation complète de ce rayon avant le week-end.",activites:[{t:"Diagnostiquer et prioriser",q:["1.1  Analyser les indicateurs : identifier les 2 problèmes les plus graves et leurs conséquences financières estimées pour LABORO.","1.2  Le facing actuel place les lampes (0 vente) en zone chaude et les tentes (best-seller) au sol en zone froide. Expliquer pourquoi c'est une erreur et quel impact ça a sur le CA.","1.3  Proposer la nouvelle implantation pour les 4 références outdoor — zone, niveau, nombre de facings. Justifier chaque choix avec une règle de merchandising."]},{t:"Mettre en oeuvre et mesurer",q:["2.1  Rédiger la fiche d'implantation complète remise à l'équipe pour exécuter la réorganisation — claire, visuelle, avec les dimensions et les règles à respecter.","2.2  Définir 3 indicateurs pour mesurer l'impact de la réorganisation à J+30."]}],livrable:"2 problèmes + impact financier + explication erreur implantation + nouvelle implantation justifiée + fiche + 3 indicateurs",criteres:[{"c":"Diagnostic structuré","i":"Mon diagnostic distingue clairement les points forts et les axes d'amélioration"},{"c":"Propositions concrètes","i":"Mes propositions d'amélioration sont précises, réalisables et justifiées"},{"c":"Cohérence avec l'identité LABORO","i":"Les améliorations proposées respectent le positionnement sport & outdoor de LABORO"}],reflexivite:0},
  {id:"M072",titre:"Construire et défendre un plan d'action commercial",comp:"C1.2",comp_ref:"C1.2",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",objectif:"Dans cette mission, tu vas conduire un entretien de vente structuré en appliquant les méthodes CAB et SONCAS dans un contexte LABORO.",palier:2,option:"AGEC",dossier:{l:"Objectifs commerciaux LABORO — T2 2026",rows:[["CA T2 à atteindre","310 000 € — soit +11,5% vs T2 2025"],["CA T2 2025","278 000 €"],["Effectif commercial","4 personnes dont 1 apprenti"],["Budget actions commerciales","2 200 €"],["Priorité Pascal Berruelle","Développer les ventes B2B et fidéliser les clients sportifs"]]},contexte:"Romain Sauzet te confie la construction du plan d'action commercial du T2 2026. Il doit être présenté à Pascal Berruelle vendredi prochain.",activites:[{t:"Construire le plan",q:["1.1  Décomposer l'objectif de 310 000 € par rayon et par canal (B2C showroom / B2C e-commerce / B2B). Justifier la répartition.","1.2  Proposer 4 actions commerciales pour le T2 — 2 pour développer le B2B, 2 pour fidéliser les clients sportifs. Pour chaque action : description, responsable, budget, indicateur de succès.","1.3  Ventiler les 2 200 € de budget entre les 4 actions. Justifier chaque allocation."]},{t:"Défendre et anticiper",q:["2.1  Pascal Berruelle demande : 'Qu'est-ce qui pourrait faire échouer ce plan ?' Identifier 3 risques et proposer une solution de secours pour chacun.","2.2  Rédiger le plan d'action complet sous forme de tableau synthétique — prêt à être présenté en réunion."]}],livrable:"Décomposition CA + 4 actions détaillées + budget ventilé + 3 risques/solutions + tableau plan d'action",criteres:[{"c":"Découverte des besoins","i":"J'utilise des questions ouvertes adaptées au profil client pour identifier ses besoins"},{"c":"Argumentation structurée (CAB)","i":"Mon argumentation distingue caractéristique, avantage et bénéfice client"},{"c":"Traitement des objections","i":"Je traite au moins une objection avec méthode (écoute, reformulation, réponse, validation)"},{"c":"Conclusion de la vente","i":"Je propose une formule de conclusion adaptée à la situation"}],reflexivite:0},
  {id:"M073",titre:"Analyser et améliorer le parcours client LABORO",comp:"C2.3",comp_ref:"C2.4",objectif:"Dans cette mission, tu vas analyser les résultats d'une enquête de satisfaction et identifier les axes d'amélioration pour LABORO.",comp_libelle:"Bloc 2 — S’assurer de la satisfaction du client",palier:2,option:"AGEC",dossier:{l:"Résultats enquête parcours client — showroom Évry",rows:[["Clients interrogés","52"],["Satisfaits de la signalétique","28 — 54%"],["Satisfaits du temps d'attente en caisse","31 — 60%"],["Satisfaits du conseil vendeur","44 — 85%"],["Trouvent facilement les produits","22 — 42%"],["NPS showroom","+14"],["Verbatim négatifs","'On ne sait pas où aller' · 'Trop d'attente en caisse' · 'Manque de prix affichés'"]]},contexte:"Marco Pellini te présente cette enquête et te demande de construire un plan d'amélioration du parcours client du showroom à présenter à Romain Sauzet.",activites:[{t:"Analyser et prioriser",q:["1.1  Calculer le taux de satisfaction pour chaque critère. Classer les 5 critères du moins satisfaisant au plus satisfaisant.","1.2  Identifier les 2 irritants majeurs du parcours client (ce qui énerve le plus les clients). Relier chaque irritant à un verbatim concret.","1.3  Le NPS de +14 : interpréter ce score. Combien de clients sont 'promoteurs' (recommandent LABORO) si on estime que le NPS = % promoteurs - % détracteurs et que 10% sont détracteurs ?"]},{t:"Proposer et planifier",q:["2.1  Proposer 3 améliorations concrètes du parcours client showroom — réalisables en moins d'un mois, sans gros investissement. Pour chaque amélioration : action, responsable, délai, coût estimé.","2.2  Rédiger la note de recommandation destinée à Romain Sauzet."]}],livrable:"5 taux calculés + classement + 2 irritants + interprétation NPS + 3 améliorations + note Romain Sauzet",criteres:[{"c":"Analyse structurée","i":"Mon analyse distingue points forts, points faibles et axes d'amélioration"},{"c":"Calcul des indicateurs","i":"Je calcule correctement les indicateurs demandés (taux de satisfaction, NPS...)"},{"c":"Recommandations concrètes","i":"Je propose des actions d'amélioration adaptées au contexte LABORO"}],reflexivite:0},
  {id:"M074",titre:"Piloter une opération de fidélisation de A à Z",comp:"C3.2",comp_ref:"C3.2",comp_libelle:"Bloc 3 — Contribuer à des actions de fidélisation de la clientèle et de développement de la relation client",objectif:"Dans cette mission, tu vas concevoir une action de fidélisation adaptée à un segment de clientèle LABORO.",palier:2,option:"AGEC",dossier:{l:"Opération 'Semaine du Trail' — LABORO — mai 2026",rows:[["Période","Du 12 au 17 mai 2026"],["Objectif","Fidéliser les clients sportifs + générer 8 000 € de CA supplémentaire"],["Budget","350 €"],["Clients sport LABORO","67 — dont 41 avec historique achat sport en 2025"],["Actions prévues","Newsletter + Journée test chaussures samedi + Offre exclusive -10%"],["Partenariat possible","Club Sportif Forêt de Sénart — Marc Girault"]]},contexte:"Romain Sauzet te confie la coordination de la Semaine du Trail. C'est toi qui pilotes — il supervise.",activites:[{t:"Organiser l'opération",q:["1.1  Établir le planning détaillé de l'opération jour par jour du 5 au 17 mai — préparation + exécution + bilan.","1.2  Rédiger la newsletter destinée aux 41 clients sportifs — objet accrocheur, corps du message (120 mots max), call-to-action clair.","1.3  Ventiler les 350 € de budget entre les différentes actions. Justifier chaque poste."]},{t:"Mesurer et capitaliser",q:["2.1  Définir 4 indicateurs pour évaluer le succès de l'opération à J+7.","2.2  L'opération se termine. CA généré : 6 200 € — objectif 8 000 €. Rédiger le bilan complet à Romain Sauzet : analyse de l'écart, causes identifiées, recommandations pour la prochaine édition."]}],livrable:"Planning 5-17 mai + newsletter rédigée + budget ventilé + 4 indicateurs + bilan avec analyse écart",criteres:[{"c":"Conception de l'action","i":"L'action de fidélisation proposée est cohérente avec le profil de la clientèle LABORO"},{"c":"Justification des choix","i":"Mes choix sont argumentés en lien avec les objectifs commerciaux de LABORO"},{"c":"Faisabilité","i":"L'action est réaliste dans le contexte d'une PME sport comme LABORO"}],reflexivite:0},
  {id:"M050",titre:"Comparer l'offre LABORO à la concurrence",comp:"C1.1",comp_ref:"C1.1",comp_libelle:"Bloc 1 — Assurer la veille commerciale",objectif:"Dans cette mission, tu vas analyser la veille commerciale de LABORO en comparant les offres concurrentes et en identifiant les opportunités de marché.",palier:2,option:"commun",dossier:{l:"Relevé concurrentiel — semaine du 14 avril 2026",rows:[["Concurrent","SportRun Évry"],["Produit observé","Chaussures route Velocity — affichée 79 € (vs 89 € LABORO)"],["Promotion en cours","- 10% sur les chaussures sport jusqu'au 19 avril"],["Nouveau produit repéré","Chaussures trail expert carbone — non référencé chez LABORO"],["Avis Google SportRun","4,1 / 5 — 87 avis — délai réponse critiqué"]]},contexte:"Romain Sauzet t'envoie un message ce matin : 'J'ai vu que SportRun fait une promo agressive cette semaine. Peux-tu analyser ça et me dire ce qu'on doit faire ?' Tu as la matinée pour préparer une note.",contexte_pvoc:"Nina Chevalier te demande de préparer une analyse concurrentielle B2B avant la réunion de secteur. SportRun Pro vient d'ouvrir un service de prospection CE en Essonne. Tu dois analyser leur approche et proposer la riposte commerciale LABORO.",activites:[{t:"Observer et analyser",q:["1.1  Lister les 3 informations les plus importantes de ce relevé pour LABORO. Pour chacune, expliquer pourquoi elle compte.","1.2  Sur le critère prix : LABORO est 14 € plus cher sur les Downshifter 12. Quels arguments LABORO peut-il opposer pour justifier cet écart ?","1.3  Le Chaussures trail expert carbone n'est pas chez LABORO. Comment évalues-tu si LABORO devrait le référencer ? Quelles informations te manquent ?"]},{t:"Rédiger et recommander",q:["2.1  Rédiger la note de veille concurrentielle destinée à Romain Sauzet : fait observé, impact pour LABORO, 2 recommandations concrètes.","2.2  Proposer un plan de veille hebdomadaire simple pour ne jamais être pris par surprise par un concurrent."]}],livrable:"3 informations analysées + arguments prix + note de veille rédigée + plan de veille hebdomadaire",criteres:[{"c":"Analyse comparative","i":"Je compare les offres concurrentes de façon structurée (tableau, critères explicites)"},{"c":"Identification des opportunités","i":"Je repère au moins une opportunité ou menace concrète pour LABORO"},{"c":"Justification des conclusions","i":"Mes conclusions s'appuient sur des données précises tirées du dossier"}],reflexivite:0},
  {id:"M051",titre:"Gérer une situation de vente compliquée",comp:"C1.3",comp_ref:"C1.3",objectif:"Dans cette mission, tu vas exécuter les opérations de finalisation d'une vente en respectant les procédures LABORO.",comp_libelle:"Bloc 1 — Assurer l’exécution de la vente",palier:2,option:"commun",dossier:{l:"Commande M. Fontaine — situation complexe",rows:[["Client","M. Fontaine — particulier — client depuis 2 ans"],["Commande","Chaussures trail Grip X taille 44 — 175 € TTC"],["Problème","Stock épuisé — réassort dans 10 jours"],["Délai souhaité","M. Fontaine part en sport dans 5 jours"],["Alternative en stock","Chaussures trail Grip X (modèle précédent) taille 44 — 159 € — modèle précédent"],["Commande déjà encaissée","Oui — CB débité ce matin"]]},contexte:"M. Fontaine a commandé en ligne hier soir. Ce matin Romain Sauzet découvre la rupture de stock. Il te demande de gérer la situation avec M. Fontaine qui doit partir en sport dans 5 jours.",contexte_pvoc:"M. Moreau (AS Palaiseau Football) t'avait confirmé par téléphone une commande de 85 maillots flocage. Mais ce matin il t'envoie un mail pour annuler — il a trouvé moins cher. Tu dois gérer cette situation à distance pour sauver la vente.",activites:[{t:"Gérer la situation client",q:["1.1  Avant d'appeler M. Fontaine, quelles solutions concrètes prépares-tu ? Lister toutes les options possibles avec leurs avantages et inconvénients.","1.2  Rédiger le script complet de l'appel téléphonique à M. Fontaine — annonce du problème, solutions proposées, attitude à adopter."]},{t:"Finaliser et tracer",q:["2.1  M. Fontaine accepte la substitution par le X Ultra 3 GTX à 159 €. Décrire les opérations administratives à réaliser : remboursement partiel, nouvelle facture, délai de livraison.","2.2  Que dois-tu saisir dans LABORO Connect pour garder une trace de cet incident et éviter qu'il se reproduise ?"]}],livrable:"Solutions préparées + script téléphonique + opérations administratives + traçabilité LABORO Connect",criteres:[{"c":"Exécution correcte","i":"J'exécute les opérations post-vente en respectant les procédures LABORO"},{"c":"Exactitude des documents","i":"Les documents produits sont complets, exacts et conformes aux données fournies"},{"c":"Respect des délais","i":"Je respecte les délais et les engagements pris envers le client"}],reflexivite:0},
  {id:"M052",titre:"Gérer une réclamation par écrit et proposer une solution",comp:"C2.2",comp_ref:"C2.3",objectif:"Dans cette mission, tu vas traiter une réclamation client en appliquant la méthode ERESA et en proposant une solution satisfaisante.",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",palier:2,option:"commun",dossier:{l:"Message reçu — compte client laboro-sport.fr",rows:[["Expéditeur","thomas.vidal@gmail.com — client fidèle depuis 3 ans"],["Objet","Commande non conforme"],["Date réception","Ce matin 8h47"],["Message","Bonjour, j'ai reçu hier ma commande de chaussures Chaussures running Velocity taille 43. Le coloris reçu est gris alors que j'avais commandé le bleu marine. Je suis très déçu car c'était un cadeau pour ma femme. Je souhaite être remboursé ou échangé rapidement. Thomas Vidal"],["Historique client","CA cumulé 2 100 € — 6 commandes — aucune réclamation antérieure"]]},contexte:"Marco Pellini te transmet ce message reçu ce matin. Il te dit : 'Thomas Vidal est un bon client — traite ça avec soin et propose-lui quelque chose de bien.' Tu as 1 heure pour répondre.",contexte_pvoc:"Thomas Vidal t'envoie un mail ce matin : il a reçu des chaussures Chaussures running Velocity en gris au lieu du bleu marine commandé sur laboro-sport.fr. C'était un cadeau pour sa femme. Marco Pellini te dit : 'Réponds-lui rapidement par mail puis appelle-le.'",activites:[{t:"Analyser et préparer",q:["1.1  Identifier le type de réclamation et sa gravité. Quels sont les enjeux pour LABORO dans ce cas précis ?","1.2  Avant de répondre, quelles vérifications fais-tu dans LABORO Connect et dans le système de commandes ?","1.3  Lister les 3 solutions que tu peux proposer à M. Vidal, avec les avantages de chacune pour lui et pour LABORO."]},{t:"Répondre et clore",q:["2.1  Rédiger le mail de réponse complet à M. Vidal — ton professionnel, excuse, solution proposée, délai, geste commercial.","2.2  Après résolution, quelles actions mènes-tu pour éviter ce type d'erreur à l'avenir ?"]}],livrable:"Analyse réclamation + vérifications + 3 solutions + mail de réponse complet + actions préventives",criteres:[{"c":"Application de la méthode ERESA","i":"Je traite la réclamation en respectant les 5 étapes dans l'ordre"},{"c":"Qualité de la réponse","i":"Ma réponse est professionnelle, claire et personnalisée"},{"c":"Préservation de la relation client","i":"La solution proposée tient compte des intérêts du client et de LABORO"}],reflexivite:0},
  {id:"M053",titre:"Analyser la satisfaction client et proposer des actions",comp:"C2.3",comp_ref:"C2.4",comp_libelle:"Bloc 2 — S’assurer de la satisfaction du client",objectif:"Dans cette mission, tu vas analyser les résultats d'une enquête de satisfaction et identifier les axes d'amélioration pour LABORO.",palier:2,option:"commun",dossier:{l:"Résultats enquête satisfaction — clients B2C showroom — mars 2026",rows:[["Répondants","64 clients"],["Note moyenne accueil","8,4 / 10"],["Note moyenne conseil produit","7,1 / 10"],["Note moyenne prix","6,3 / 10"],["Note moyenne site web","5,8 / 10"],["NPS global","+18"],["Verbatim récurrents","Accueil sympa · Conseils limités sur le sport · Site peu pratique · Pas assez de stock"]]},contexte:"Marco Pellini te présente les résultats de l'enquête satisfaction de mars. Il te demande d'analyser les points faibles et de préparer 3 actions concrètes à présenter à Romain Sauzet vendredi matin.",contexte_pvoc:"Marco Pellini te remet les résultats de l'enquête satisfaction menée auprès des 41 clients B2B actifs de LABORO. Il te demande d'analyser les résultats et de proposer 3 actions concrètes d'amélioration ciblées sur la relation client à distance.",activites:[{t:"Analyser les résultats",q:["1.1  Calculer le taux de satisfaction globale (notes >= 7/10 sur chaque critère). Identifier le point le plus satisfaisant et le point le plus critique.","1.2  Le NPS de +18 : est-ce un bon score ? Qu'est-ce qu'il signifie concrètement pour LABORO ?","1.3  Les verbatim mentionnent le site web. Sans données chiffrées sur ce point, comment évalues-tu la gravité de ce problème ?"]},{t:"Proposer et rédiger",q:["2.1  Proposer 3 actions concrètes et réalisables à court terme pour améliorer les 2 critères les plus faibles. Pour chaque action : description, responsable, délai, indicateur de réussite.","2.2  Rédiger la synthèse destinée à Romain Sauzet — 15 à 20 lignes — résultats clés + 3 actions prioritaires."]}],livrable:"Calcul satisfaction + interprétation NPS + analyse verbatim + 3 actions + synthèse Romain Sauzet",criteres:[{"c":"Analyse structurée","i":"Mon analyse distingue points forts, points faibles et axes d'amélioration"},{"c":"Calcul des indicateurs","i":"Je calcule correctement les indicateurs demandés (taux de satisfaction, NPS...)"},{"c":"Recommandations concrètes","i":"Je propose des actions d'amélioration adaptées au contexte LABORO"}],reflexivite:0},
  {id:"M054",titre:"Organiser le traitement des contacts entrants multicanaux",comp:"C3.1",comp_ref:"C3.1",objectif:"Dans cette mission, tu vas exploiter le fichier clients LABORO pour préparer des actions commerciales ciblées.",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",palier:2,option:"commun",dossier:{l:"Contacts reçus sur une journée type LABORO",rows:[["9h00","Mail — demande de devis CE Essilor — 80 salariés"],["9h30","Appel — client qui demande le statut de sa commande"],["10h15","Commentaire Instagram — question sur les tailles de maillots"],["11h00","Avis Google 2 étoiles — client insatisfait de la livraison"],["14h00","Formulaire laboro-sport.fr — demande catalogue B2B"],["15h30","Message Facebook — client cherche un revendeur LABORO en Essonne"],["16h45","Mail — partenaire LABORO qui envoie une nouvelle PLV"]]},contexte:"Marco Pellini te confie la gestion des contacts de la journée. Il te dit : 'Classe, priorise et traite — ou prépare les réponses — pour tous ces contacts avant 18h.'",contexte_pvoc:"Pascal Berruelle constate que les contacts B2B entrants (mails, appels, réseaux) ne sont pas traités de façon homogène par l'équipe. Il te confie la mise en place d'un système de traitement et de priorisation des contacts pour toute l'équipe commerciale.",activites:[{t:"Classer et prioriser",q:["1.1  Classer les 7 contacts en 3 niveaux de priorité (urgent / important / à traiter en fin de journée). Justifier le classement de chacun.","1.2  Pour les 2 contacts les plus urgents, rédiger la réponse complète immédiate."]},{t:"Traiter et organiser",q:["2.1  Pour l'avis Google 2 étoiles : rédiger la réponse publique de LABORO — professionnelle et constructive en moins de 80 mots.","2.2  Proposer un système simple de priorisation des contacts entrants que toute l'équipe LABORO pourrait utiliser — 3 règles maximum, claires et mémorisables."]}],livrable:"Classement 3 niveaux justifié + 2 réponses immédiates + réponse avis Google + système de priorisation équipe",criteres:[{"c":"Exploitation des données","i":"J'utilise les données clients pour préparer une action commerciale ciblée"},{"c":"Segmentation","i":"Je regroupe les clients selon des critères pertinents et justifiés"},{"c":"Plan d'action","i":"Mon plan d'action est cohérent avec les données exploitées"}],reflexivite:0},
  {id:"M055",titre:"Découvrir les outils de fidélisation de LABORO",comp:"C3.3",comp_ref:"C3.3",objectif:"Dans cette mission, tu vas identifier les outils digitaux utilisés par LABORO pour développer sa relation client et mesurer leur impact.",comp_libelle:"Bloc 3 — Évaluer les actions de fidélisation de la clientèle et de développement de la relation client",palier:1,option:"commun",contexte:"Romain Sauzet t'explique que LABORO a mis en place plusieurs outils pour fidéliser ses clients et les faire revenir. Il te demande de les découvrir et de comprendre à quoi chacun sert.",contexte_pvoc:"Nina Chevalier t'explique que LABORO utilise plusieurs outils pour fidéliser ses clients B2B : relances téléphoniques personnalisées, newsletter CE, invitations soirée clients, programme de parrainage. Elle te demande de les analyser et de comprendre leur logique.",activites:[{t:"Identifier les outils de fidélisation",q:["1.1  Romain Sauzet te cite 4 outils de fidélisation que LABORO utilise : carte LABORO PRO, newsletter mensuelle, soirée clients annuelle, programme de parrainage. Pour chacun, expliquer en 2 phrases à quoi il sert et qui il cible.","1.2  Parmi ces 4 outils, lequel te semble le plus adapté à un client B2C passionné de sport ? Et pour un CE d'entreprise ? Justifier ton choix."]},{t:"Comprendre la logique de fidélisation",q:["2.1  Quelle est la différence entre un client satisfait et un client fidèle ? Donner un exemple avec un client LABORO.","2.2  M. Vidal est client depuis 3 ans — CA cumulé 2 100 €. Il n'a jamais utilisé sa carte LABORO PRO. Comment lui en parler naturellement lors de sa prochaine visite ? Rédiger les 3 phrases à dire."]}],livrable:"4 outils décrits et comparés + choix justifié par profil + différence satisfait/fidèle + script carte PRO",criteres:[{"c":"Identification des outils digitaux","i":"Je cite les outils digitaux utilisés par LABORO (Instagram, site, email marketing...)"},{"c":"Lecture des indicateurs","i":"Je lis et décris correctement les indicateurs de performance digitale fournis"},{"c":"Compréhension des enjeux","i":"J'explique l'intérêt du digital pour développer la relation client de LABORO"}],reflexivite:0},
  {id:"M056",titre:"Préparer et animer une action de fidélisation",comp:"C3.3",comp_ref:"C3.3",objectif:"Dans cette mission, tu vas concevoir du contenu digital adapté à l'identité de LABORO et analyser les indicateurs de performance.",comp_libelle:"Bloc 3 — Évaluer les actions de fidélisation de la clientèle et de développement de la relation client",palier:2,option:"commun",dossier:{l:"Soirée clients LABORO — bilan de la dernière édition",rows:[["Date","15 novembre 2025 — showroom Évry"],["Clients invités","48"],["Présents","31 — taux de présence 65%"],["CA généré ce soir-là","4 200 €"],["Satisfaction post-événement","4,3 / 5 — enquête SMS J+2"],["Principaux retours","Bonne ambiance · Démonstrations utiles · Trop court · Voulaient plus de produits nouveaux"]]},contexte:"Romain Sauzet prépare la prochaine soirée clients LABORO prévue en novembre 2026. Il te demande de l'aider à améliorer le format par rapport à la dernière édition.",contexte_pvoc:"Nina Chevalier prépare la prochaine opération de fidélisation clients B2B — une journée test produit au showroom pour 20 CE partenaires. Elle te demande d'améliorer le format par rapport à la dernière édition et de coordonner l'opération.",activites:[{t:"Analyser et améliorer",q:["1.1  Analyser le bilan de la dernière soirée : 3 points positifs à conserver, 2 points à améliorer. Appuyer chaque point sur des données du bilan.","1.2  Proposer 3 améliorations concrètes pour la prochaine édition en tenant compte des retours clients.","1.3  Définir l'objectif principal de la soirée 2026 — il doit être SMART (Spécifique, Mesurable, Atteignable, Réaliste, Temporel)."]},{t:"Organiser et communiquer",q:["2.1  Rédiger l'invitation mail à envoyer aux 55 meilleurs clients LABORO — objet accrocheur, programme de la soirée, call-to-action RSVP.","2.2  Définir 3 indicateurs pour évaluer le succès de la soirée 2026 — formule + objectif cible."]}],livrable:"3 points à conserver + 2 à améliorer + 3 améliorations + objectif SMART + invitation mail + 3 indicateurs",criteres:[{"c":"Création de contenu adapté","i":"Le contenu produit est cohérent avec l'identité visuelle et éditoriale de LABORO"},{"c":"Calcul des indicateurs","i":"Je calcule et interprète correctement les indicateurs demandés (taux d'engagement...)"},{"c":"Recommandations digitales","i":"Mes recommandations sont adaptées aux ressources et à l'audience de LABORO"}],reflexivite:0},
  {id:"M057",titre:"Découvrir et prendre en main le rayon chaussures",comp:"C4A.2",comp_ref:"C4A.2",comp_libelle:"Bloc 4A — Rendre l’unité commerciale attractive et fonctionnelle",objectif:"Dans cette mission, tu vas observer et analyser l'attractivité de l'espace de vente LABORO en identifiant les composantes du merchandising.",palier:1,option:"AGEC",contexte:"C'est ton premier jour au rayon chaussures du showroom LABORO. Romain Sauzet t'explique les bases avant de te laisser en autonomie : comment est organisé le rayon, quels sont les produits phares, et quelles sont les règles de base du merchandising.",activites:[{t:"Découvrir l'organisation du rayon",q:["1.1  Observer le plan du rayon chaussures LABORO : chaussures sport à gauche, running route à droite, accessoires au centre. Expliquer en 3 phrases pourquoi cette organisation facilite le parcours client.","1.2  Lister les 4 produits phares du rayon chaussures (ceux qui se vendent le plus) à partir du catalogue LABORO. Pour chaque produit, noter : nom, prix de vente, 1 argument commercial clé.","1.3  Qu'est-ce que le 'facing' en merchandising ? Donner un exemple concret sur une référence du rayon chaussures LABORO."]},{t:"Observer et préparer",q:["2.1  Tu remarques que les Chaussures running EasyRun (best-seller) sont placés en hauteur, peu visibles. Que fait Romain Sauzet si tu lui signales ce problème ?  Que faut-il faire et pourquoi ?","2.2  Un client entre et te dit : 'Je cherche des chaussures pour commencer le sport, je ne sais pas quoi choisir.' Quelle est ta première phrase et ta première question ?"]}],livrable:"Organisation rayon expliquée + 4 produits phares + définition facing + correction placement + accueil client",criteres:[{"c":"Identification des composantes","i":"Je cite et décris correctement les composantes de l'attractivité d'un espace de vente"},{"c":"Observation structurée","i":"Mon observation suit un plan logique (agencement, signalétique, produits, ambiance...)"},{"c":"Lien avec LABORO","i":"Je relie mes observations au contexte sportif et outdoor de LABORO"}],reflexivite:0},
  {id:"ACC-P2",titre:"Gérer l'accueil en situation de flux et de tension",comp:"ACC",comp_ref:"ACC",objectif:"Dans cette mission, tu vas mettre en œuvre un accueil client structuré en appliquant les standards professionnels de LABORO.",comp_libelle:"Seconde — Découverte des métiers de l’accueil (famille relation client)",palier:2,option:"2nde",dossier:{l:"Journée Portes Ouvertes LABORO — samedi 12 avril",rows:[["Visiteurs attendus","120 à 150"],["Équipe accueil","2 personnes dont toi"],["Programme","10h : ouverture · 11h : démonstration running · 14h : atelier flocage · 16h : tombola"],["Problèmes connus","Parking limité · Pas de vestiaires · Wi-Fi instable"],["Objectif","Accueillir, orienter, créer un bon souvenir de LABORO"]]},contexte:"Pascal Berruelle t'a confié l'accueil de la Journée Portes Ouvertes avec un(e) collègue. Ce sera une journée chargée avec des profils de visiteurs très variés.",activites:[{t:"Préparer l'accueil",q:["1.1  Préparer le kit d'accueil de la journée : que dois-tu avoir à ta disposition dès 9h30 pour accueillir les visiteurs dans les meilleures conditions ? Lister au moins 6 éléments.","1.2  À 11h, la démonstration running attire 40 personnes simultanément. Tu es seul(e) à l'accueil. Décrire comment tu gères l'afflux et dans quel ordre tu prends en charge les visiteurs."]},{t:"Gérer les situations difficiles",q:["2.1  Un visiteur se plaint bruyamment du parking : 'C'est scandaleux, j'ai dû me garer à 300m !' Deux autres visiteurs l'entendent. Rédiger ta réponse complète.","2.2  Un visiteur insiste pour essayer des chaussures mais toutes les pointures de sa taille sont sorties. Comment proposes-tu une alternative sans le décevoir ?","2.3  En fin de journée, évaluer : 3 choses qui ont bien fonctionné dans ton accueil aujourd'hui et 2 choses à améliorer la prochaine fois."]}],livrable:"Kit accueil 6 éléments + gestion afflux + réponse visiteur parking + alternative chaussures + auto-évaluation",criteres:[{"c":"Accueil structuré","i":"Mon accueil respecte les étapes et les standards professionnels de LABORO"},{"c":"Adaptation à l'interlocuteur","i":"J'adapte mon accueil au profil et aux attentes de la personne accueillie"},{"c":"Gestion des situations imprévues","i":"Je gère les situations imprévues avec calme et professionnalisme"}],reflexivite:0},
  {id:"ACC-P3",titre:"Concevoir et coordonner le dispositif d'accueil d'un événement",comp:"ACC",comp_ref:"ACC",objectif:"Dans cette mission, tu vas concevoir et coordonner un dispositif d'accueil complet pour un événement LABORO.",comp_libelle:"Seconde — Découverte des métiers de l’accueil (famille relation client)",palier:3,option:"2nde",dossier:{l:"Événement LABORO — Sport en Essonne — partenariat",rows:[["Événement","Sport en Essonne — 800 coureurs — dimanche 18 mai"],["Rôle LABORO","Partenaire officiel — stand d'accueil + espace équipement"],["Équipe disponible","4 personnes dont toi qui coordonnes"],["Public","Coureurs (tous niveaux), accompagnants, bénévoles, presse locale"],["Objectifs","Image de marque + 40 contacts qualifiés + 15 ventes immédiates"]]},contexte:"Pascal Berruelle te confie la coordination de la présence LABORO au Sport en Essonne. C'est la première fois que LABORO est partenaire d'un événement de cette taille. Il compte sur toi.",activites:[{t:"Concevoir le dispositif",q:["1.1  Définir le rôle de chacun des 4 membres de l'équipe pour la journée — fiche de poste succincte pour chaque personne.","Remets dans l'ordre ces moments cles de la journee evenement : A) Rangement final — B) Accueil des premiers visiteurs — C) Mise en place du stand — D) Bilan d'equipe — E) Pause dejeuner","1.3  Identifier 5 situations difficiles probables lors de cet événement et préparer la réponse à chacune."]},{t:"Coordonner et évaluer",q:["2.1  Rédiger le brief de 10 minutes que tu feras à l'équipe à 7h30 le matin de l'événement — ton, posture, consignes clés, objectifs.","2.2  Concevoir la fiche de collecte des 40 contacts qualifiés à renseigner sur tablette tout au long de la journée.","2.3  Rédiger le compte-rendu de l'événement destiné à Pascal Berruelle — bilan quantitatif + qualitatif + recommandations pour la prochaine édition."]}],livrable:"4 fiches de poste + planning journée + 5 situations/réponses + brief équipe + fiche contacts + compte-rendu",criteres:[{"c":"Conception du dispositif","i":"Le dispositif d'accueil proposé est complet, cohérent et adapté à l'événement"},{"c":"Coordination de l'équipe","i":"Le rôle de chaque membre de l'équipe est clairement défini"},{"c":"Anticipation des risques","i":"J'anticipe les situations difficiles et prépare des réponses adaptées"},{"c":"Évaluation du dispositif","i":"Je définis des indicateurs pour évaluer la qualité de l'accueil"}],reflexivite:0},
  {id:"M058",titre:"Conseiller un client et réaliser une vente simple",comp:"C1.2",comp_ref:"C1.2",comp_libelle:"Bloc 1 — Réaliser la vente dans un cadre omnicanal",objectif:"Dans cette mission, tu vas conduire un entretien de vente structuré en appliquant les méthodes CAB et SONCAS dans un contexte LABORO.",palier:2,option:"2nde",dossier:{l:"Situation showroom — mercredi après-midi",rows:[["Client","Mme Konaté — 42 ans — première visite chez LABORO"],["Demande initiale","Un cadeau pour son fils de 16 ans qui aime le foot"],["Budget annoncé","Environ 50 à 60 €"],["Infos recueillies","Son fils joue en club le week-end · Entraînements 2 fois/semaine · Pointure 41"],["Produits adaptés","Ballon Pro Match T5 49 € · Maillot basket réversible 38 € · Bandes élastiques 39 €"]]},contexte:"Romain Sauzet t'a observé(e) accueillir des clients depuis 3 semaines. Aujourd'hui il te laisse gérer seul(e) cette vente avec Mme Konaté, en t'observant de loin.",activites:[{t:"Découvrir les besoins et conseiller",q:["1.1  À partir des informations recueillies, quel produit LABORO recommandes-tu à Mme Konaté ? Justifier ton choix avec la méthode CAB (Caractéristique, Avantage, Bénéfice).","1.2  Mme Konaté hésite entre le ballon (49 €) et les bandes élastiques (39 €). Elle dit : 'Je ne sais pas ce qui lui fera plus plaisir.' Que lui dis-tu pour l'aider à choisir ?"]},{t:"Finaliser la vente",q:["2.1  Mme Konaté choisit le ballon Pro Match à 49 €. Proposer un produit complémentaire adapté (moins de 15 €) et rédiger la phrase de proposition.","2.2  Rédiger la phrase de prise de congé après l'encaissement — remercier, informer sur la garantie, inviter à revenir."]}],livrable:"Recommandation CAB + aide à la décision + proposition complémentaire + prise de congé rédigée",criteres:[{"c":"Découverte des besoins","i":"J'utilise des questions ouvertes adaptées au profil client pour identifier ses besoins"},{"c":"Argumentation structurée (CAB)","i":"Mon argumentation distingue caractéristique, avantage et bénéfice client"},{"c":"Traitement des objections","i":"Je traite au moins une objection avec méthode (écoute, reformulation, réponse, validation)"},{"c":"Conclusion de la vente","i":"Je propose une formule de conclusion adaptée à la situation"}],reflexivite:0},
  {id:"M059",titre:"Traiter un message client et rédiger une réponse professionnelle",comp:"C3.1",comp_ref:"C3.1",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",objectif:"Dans cette mission, tu vas exploiter le fichier clients LABORO pour préparer des actions commerciales ciblées.",palier:2,option:"2nde",dossier:{l:"Message reçu sur laboro-sport.fr",rows:[["Expéditeur","Mme Petit — Centre de loisirs Vert-Bois"],["Objet","Demande d'information"],["Message","Bonjour, nous organisons un séjour nature pour 18 enfants de 8 à 12 ans fin juin. Nous cherchons des tentes pouvant accueillir 3 personnes, résistantes et faciles à monter. Quel est votre délai de livraison et avez-vous des tarifs de groupe ? Cordialement, Aurélie Petit"],["Délai de réponse souhaité","Sous 24h selon nos engagements clients"]]},contexte:"Marco Pellini te confie ce message reçu hier soir. Il te dit : 'Réponds-lui de façon professionnelle — c'est peut-être un bon client B2B à développer.'",activites:[{t:"Préparer la réponse",q:["1.1  Avant de répondre, quelles informations dois-tu vérifier dans le catalogue LABORO et dans LABORO Connect ?","1.2  La Tente LABORO Quick 3 places à 169 € correspond bien à sa demande. Calculer le montant HT et TTC pour 6 tentes (une par groupe de 3), et la remise applicable si LABORO accorde 8% pour une commande groupe."]},{t:"Rédiger et proposer",q:["2.1  Rédiger le mail de réponse complet à Mme Petit — objet professionnel, réponse à ses questions, proposition de devis, signature LABORO.","2.2  Marco Pellini lit ta réponse et te dit : 'Bien — et si on lui proposait aussi quelques accessoires pour les enfants ?' Ajouter 2 produits complémentaires pertinents à la proposition."]}],livrable:"Infos vérifiées + calcul HT/TTC + remise + mail de réponse complet + 2 produits complémentaires proposés",criteres:[{"c":"Exploitation des données","i":"J'utilise les données clients pour préparer une action commerciale ciblée"},{"c":"Segmentation","i":"Je regroupe les clients selon des critères pertinents et justifiés"},{"c":"Plan d'action","i":"Mon plan d'action est cohérent avec les données exploitées"}],reflexivite:0},
  {id:"M060",titre:"Analyser les performances commerciales de LABORO",comp:"C1.1",comp_ref:"C1.1",comp_libelle:"Bloc 1 — Assurer la veille commerciale",objectif:"Dans cette mission, tu vas repérer les sources d'information commerciale utilisées chez LABORO et identifier les informations clés sur les produits, les prix et la concurrence.",palier:1,option:"commun",dossier:{l:"Tableau de bord LABORO — 1er trimestre 2026",rows:[["CA total","278 000 € — objectif 250 000 € — réalisé à 111%"],["CA running/sport","98 000 € — +18% vs T1 2025"],["CA textile personnalisé","61 000 € — +31% vs T1 2025"],["CA outdoor","24 000 € — -8% vs T1 2025"],["Panier moyen B2C","187 €"],["Panier moyen B2B","3 200 €"],["Nouveaux clients","14 — dont 9 B2B"]]},contexte:"Pascal Berruelle te présente le tableau de bord du 1er trimestre. Il te demande de l'analyser et d'identifier les points clés avant la réunion d'équipe de vendredi.",contexte_pvoc:"Pascal Berruelle te remet le tableau de bord commercial B2B du T1 2026 — CA par segment, nouveaux clients, taux de fidélisation, performances prospection. Il te demande de l'analyser et de préparer les 5 points clés pour la réunion d'équipe de vendredi.",activites:[{t:"Lire et comprendre les données",q:["1.1  Le CA total dépasse l'objectif. Calculer l'écart en euros et en pourcentage. Est-ce une bonne nouvelle ? Pourquoi ?","1.2  Identifier le rayon le plus performant et le moins performant. Pour chacun, donner une explication possible.","1.3  Calculer la part du CA running/sport dans le CA total. Ce rayon est-il stratégique pour LABORO ?"]},{t:"Interpréter et communiquer",q:["2.1  Le CA outdoor baisse de 8%. Proposer 2 causes possibles et 1 action pour y remédier.","Parmi ces resultats, lesquels sont positifs ? Coche : A) CA en hausse 8% — B) 3 reclamations — C) Satisfaction 94% — D) Stock epuise."]}],livrable:"Calcul écart CA + rayon fort/faible expliqué + part running calculée + 2 causes outdoor + 5 points clés réunion",criteres:[{"c":"Identification des sources","i":"Je cite au moins 2 sources d'information commerciale pertinentes pour LABORO"},{"c":"Compréhension des informations","i":"Je décris correctement les informations utiles issues des sources identifiées"},{"c":"Lien avec la situation LABORO","i":"Je relie les informations trouvées à la situation commerciale décrite"}],reflexivite:0},
  {id:"M061",titre:"Traiter une réclamation client sensible",comp:"C2.2",comp_ref:"C2.3",comp_libelle:"Bloc 2 — Traiter les retours et les réclamations du client",objectif:"Dans cette mission, tu vas identifier les étapes de traitement d'une réclamation client et repérer les attitudes professionnelles adaptées.",palier:1,option:"commun",dossier:{l:"Situation — réclamation reçue au showroom",rows:[["Client","M. Marchand — 58 ans — client depuis 5 ans — CA cumulé 3 800 €"],["Réclamation","chaussures LABORO achetées il y a 3 mois — semelle décollée après 4 sorties"],["Réaction","M. Marchand est mécontent et dit que la qualité LABORO a baissé"],["Garantie","Garantie légale 2 ans en cours — défaut non lié à un usage anormal"],["Solution LABORO","Échange ou remboursement selon politique standard"]]},contexte:"M. Marchand se présente au showroom ce matin, les chaussures dans un sac. Il est visiblement irrité. Romain Sauzet te dit discrètement : 'Prends-le en charge — c'est un très bon client.'",contexte_pvoc:"M. Marchand t'appelle : ses chaussures LABORO achetées il y a 3 mois via laboro-sport.fr ont la semelle décollée après 4 sorties. Il est mécontent. Romain Sauzet te dit : 'Gère ça par téléphone — propose-lui quelque chose de bien.'",activites:[{t:"Accueillir et comprendre",q:["1.1  Décrire les 4 premières phrases que tu dis à M. Marchand dès son arrivée pour désamorcer la tension.","1.2  M. Marchand dit : 'C'est la deuxième fois que j'ai un problème ici.' Tu n'as pas d'information sur un problème précédent. Comment réagis-tu ?"]},{t:"Proposer et conclure",q:["2.1  Expliquer à M. Marchand les 2 solutions auxquelles il a droit (échange ou remboursement) en termes simples et professionnels.","2.2  M. Marchand choisit l'échange mais la référence exacte n'est plus disponible en taille 44. Que lui proposes-tu concrètement ?"]}],livrable:"4 phrases d'accueil + réponse à l'historique inconnu + explication 2 solutions + proposition alternative",criteres:[{"c":"Connaissance des étapes ERESA","i":"J'identifie et nomme correctement les 5 étapes du traitement d'une réclamation"},{"c":"Attitude professionnelle","i":"Je décris les attitudes adaptées face à un client mécontent (écoute, empathie, calme)"},{"c":"Identification de la solution","i":"Je propose une solution réaliste et adaptée à la situation décrite"}],reflexivite:0},
  {id:"M062",titre:"Mesurer et interpréter la satisfaction d'un segment client",comp:"C2.3",comp_ref:"C2.4",comp_libelle:"Bloc 2 — S’assurer de la satisfaction du client",objectif:"Dans cette mission, tu vas identifier les outils et indicateurs de mesure de la satisfaction client utilisés chez LABORO.",palier:1,option:"commun",dossier:{l:"Résultats sondage — clients B2B LABORO — février 2026",rows:[["Clients B2B interrogés","18"],["Satisfaits du délai de livraison","12"],["Satisfaits du conseil commercial","15"],["Satisfaits de la qualité produits","17"],["Souhaitent un interlocuteur dédié","11"],["NPS B2B","+22"]]},contexte:"Nina Chevalier a mené ce sondage rapide auprès des clients B2B. Elle te demande de calculer les taux de satisfaction et de dire ce que LABORO devrait améliorer en priorité.",contexte_pvoc:"Nina Chevalier a mené un sondage rapide auprès des 18 clients B2B actifs de LABORO. Elle te remet les résultats et te demande de calculer les taux de satisfaction, d'interpréter le NPS et d'identifier la priorité d'amélioration.",activites:[{t:"Calculer et lire les résultats",q:["1.1  Calculer le taux de satisfaction pour chacun des 4 critères. Présenter les résultats du plus satisfaisant au moins satisfaisant.","1.2  Le NPS B2B est de +22. Qu'est-ce que ça signifie ? Comment se calcule le NPS ? Est-ce un bon score pour une entreprise B2B ?"]},{t:"Analyser et recommander",q:["2.1  Quel critère LABORO doit-il améliorer en priorité ? Justifier et proposer 2 actions concrètes.","2.2  11 clients sur 18 souhaitent un interlocuteur dédié. Nina Chevalier te demande si LABORO devrait créer un poste de 'chargé de comptes B2B'. Donner ton avis argumenté."]}],livrable:"4 taux calculés + définition/calcul NPS + priorité argumentée + 2 actions + avis sur poste dédié",criteres:[{"c":"Identification des outils","i":"Je cite les outils de mesure de satisfaction utilisés chez LABORO (questionnaire, avis, NPS)"},{"c":"Lecture des résultats","i":"Je lis et décris correctement les résultats d'une enquête simple"},{"c":"Formulation d'une observation","i":"Je relève au moins un point fort et un point faible dans les résultats"}],reflexivite:0},
  {id:"M063",titre:"Construire et piloter un tableau de bord de suivi client",comp:"C3.1",comp_ref:"C3.1",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",objectif:"Dans cette mission, tu vas exploiter le fichier clients LABORO pour préparer des actions commerciales ciblées.",palier:2,option:"commun",dossier:{l:"Situation LABORO — gestion des contacts multicanaux",rows:[["Canaux actifs","Téléphone · Mail · Instagram · Facebook · Site web · Présentiel"],["Volume contacts/semaine","estimé 150 à 200"],["Délai de réponse actuel","Téléphone : immédiat · Mail : 31h · Réseaux : 48h"],["Objectif Pascal Berruelle","Tous les canaux traités en moins de 24h"],["Problème identifié","Pas de suivi centralisé — chacun traite de son côté"]]},contexte:"Pascal Berruelle te confie la construction d'un tableau de bord de suivi des contacts pour toute l'équipe. Il veut que tout le monde utilise le même outil et les mêmes règles.",contexte_pvoc:"Pascal Berruelle te confie la conception d'un tableau de bord de suivi des contacts B2B entrants pour toute l'équipe commerciale. Objectif : uniformiser le traitement, réduire le délai de réponse à moins de 24h sur tous les canaux.",activites:[{t:"Concevoir le tableau de bord",q:["1.1  Définir les 6 indicateurs à suivre dans le tableau de bord — nom de l'indicateur, formule de calcul, objectif cible, fréquence de mise à jour.","1.2  Proposer la structure du tableau de bord (colonnes, lignes, couleurs) pour qu'il soit lisible en moins de 30 secondes par Pascal Berruelle.","1.3  Rédiger les 3 règles de traitement des contacts que toute l'équipe devra respecter — simples, claires, vérifiables."]},{t:"Mettre en oeuvre",q:["2.1  Rédiger le mail de présentation du tableau de bord à l'équipe LABORO — expliquer pourquoi, comment, et ce qu'on attend de chacun.","2.2  Au bout d'un mois, le délai moyen mail passe de 31h à 22h. Est-ce suffisant ? Comment poursuivre l'amélioration ?"]}],livrable:"6 indicateurs définis + structure tableau + 3 règles + mail présentation équipe + analyse progrès",criteres:[{"c":"Exploitation des données","i":"J'utilise les données clients pour préparer une action commerciale ciblée"},{"c":"Segmentation","i":"Je regroupe les clients selon des critères pertinents et justifiés"},{"c":"Plan d'action","i":"Mon plan d'action est cohérent avec les données exploitées"}],reflexivite:0},
  {id:"B41-P1",titre:"Constituer un fichier de prospects B2B pour LABORO",comp:"B4.1",comp_ref:"C4B.1",comp_libelle:"Bloc 4B — Rechercher et analyser les informations à des fins d’exploitation",objectif:"Dans cette mission, tu vas identifier les sources d'information utiles à la prospection commerciale et comprendre les enjeux de la prospection B2B pour LABORO.",palier:1,option:"PVOC",contexte:"Nina Chevalier vous demande de trouver de nouveaux prospects B2B en Essonne pour développer le portefeuille clients de LABORO. Vous disposez d'une matinée pour identifier et qualifier des cibles.",activites:[{t:"Identifier les sources et collecter les données",q:["1.1  Lister 4 sources d'information que vous pouvez utiliser pour trouver des prospects B2B sportifs en Essonne. Pour chaque source, préciser le type de prospect qu'elle permet de trouver.","1.2  A partir de ces sources, identifier 3 prospects potentiels non encore dans le fichier LABORO. Pour chacun : nom, secteur, contact estimé, besoins pressentis."]},{t:"Qualifier et hiérarchiser les prospects",q:["2.1  Appliquer la méthode BANT pour évaluer le potentiel de chacun des 3 prospects identifiés.","2.2  Classer les 3 prospects par ordre de priorité. Justifier votre classement et indiquer lequel contacter en premier.","2.3  Lister les 8 champs à renseigner dans LABORO Connect pour chaque prospect avant toute prise de contact."]}],livrable:"4 sources listées + 3 prospects identifiés + qualification BANT + classement justifié + fiche LABORO Connect",criteres:[{"c":"Identification des sources","i":"Je cite les sources d'information utiles pour préparer une prospection B2B"},{"c":"Compréhension des enjeux","i":"J'explique pourquoi la prospection est essentielle pour le développement de LABORO"},{"c":"Lecture du fichier prospects","i":"Je lis et décris correctement les données du fichier prospects fourni"}],reflexivite:0},
  {id:"B41-P2",titre:"Analyser et enrichir la base de prospects LABORO",comp:"B4.1",comp_ref:"C4B.1",objectif:"Dans cette mission, tu vas collecter et organiser les informations nécessaires à une action de prospection ciblée pour LABORO.",comp_libelle:"Bloc 4B — Rechercher et analyser les informations à des fins d’exploitation",palier:2,option:"PVOC",dossier:{l:"Extrait base prospects LABORO Connect — LABORO",rows:[["CE PSA Stellantis","Client actif — CA 22 400 € — contact Isabelle Faure"],["Comité 91 Handball","Prospect tiède — contact Pierre Lambert — budget estimé 7 000 €/an"],["MJC de Massy","Aucune info — identifiée via forum sport Essonne — à qualifier"],["ArianeGroup Massy","Prospect froid — 2 800 salariés — aucun contact LABORO"],["Club Gym Évry","Aucune info — vue sur LinkedIn — à qualifier"]]},contexte:"Nina Chevalier vous remet la liste des 5 prospects en cours et vous demande de l'analyser, de la compléter et de la prioriser pour la prochaine campagne de prospection.",activites:[{t:"Analyser la qualité du fichier",q:["1.1  Identifier les 3 prospects dont les informations sont insuffisantes pour lancer une prospection. Lister ce qui manque pour chacun.","1.2  Pour ArianeGroup Massy, identifier toutes les informations que vous pouvez trouver via des sources professionnelles (secteur, taille, contact CE probable, budget estimé). Détailler votre démarche."]},{t:"Structurer et prioriser",q:["2.1  Réorganiser les 5 prospects en 3 niveaux de priorité (A = urgent, B = important, C = à surveiller). Justifier chaque classement.","2.2  Proposer un plan d'action sur 2 semaines pour enrichir les fiches incomplètes — actions, sources, responsable, délai.","2.3  Calculer le potentiel CA estimé du portefeuille si tous les prospects se convertissent en clients. Interpréter ce chiffre."]}],livrable:"Analyse manques + démarche ArianeGroup + priorisation A/B/C justifiée + plan 2 semaines + calcul CA potentiel",criteres:[{"c":"Collecte structurée","i":"Les informations collectées sont pertinentes, fiables et bien organisées"},{"c":"Qualification des prospects","i":"Je qualifie les prospects selon des critères adaptés à LABORO (secteur, taille, potentiel)"},{"c":"Priorisation","i":"Je priorise les prospects de façon justifiée"}],reflexivite:0},
  {id:"B41-P3",titre:"Concevoir le systeme de veille et de qualification prospects",comp:"B4.1",comp_ref:"C4B.1",comp_libelle:"Bloc 4B — Rechercher et analyser les informations à des fins d’exploitation",objectif:"Dans cette mission, tu vas construire une base de prospection qualifiée et définir une stratégie d'approche adaptée aux cibles B2B de LABORO.",palier:3,option:"PVOC",dossier:{l:"Situation prospection LABORO — bilan annuel",rows:[["Prospects entrants par mois","3 à 5 — dont 80% non qualifiés"],["Temps de qualification par prospect","45 min en moyenne"],["Taux de doublons dans LABORO Connect","18%"],["Prospects perdus faute de suivi","22 — CA potentiel perdu : 180 000 €"],["Sources les plus productives","Forum sport Essonne 38% · LinkedIn 29% · Bouche à oreille 21%"]]},contexte:"Pascal Berruelle constate que LABORO perd trop de prospects faute d'un systeme de veille et de qualification structuré. Il vous confie la conception d'un dispositif permanent.",activites:[{t:"Concevoir le dispositif",q:["1.1  Identifier les 3 causes principales de la perte de 22 prospects et calculer leur impact financier.","1.2  Concevoir la procedure de qualification des nouveaux prospects — etapes, criteres BANT pondérés, délai maximum de traitement, responsable.","1.3  Proposer 5 sources de veille automatisée à mettre en place pour alimenter le fichier en continu — outil, fréquence, type de prospect capté."]},{t:"Mettre en oeuvre et former",q:["2.1  Concevoir la fiche de qualification type à integrer dans LABORO Connect — structure, champs obligatoires, score de priorité automatique.","2.2  Rédiger le guide de qualification prospects à destination de toute l'équipe commerciale LABORO.","2.3  Rédiger le rapport stratégique à Pascal Berruelle présentant le dispositif et les gains estimés."]}],livrable:"3 causes + impact financier + procedure qualification + 5 sources veille + fiche LABORO Connect + guide équipe + rapport",criteres:[{"c":"Base de prospection qualifiée","i":"La base construite est complète, qualifiée et exploitable"},{"c":"Stratégie d'approche","i":"La stratégie d'approche est adaptée aux différents profils de prospects"},{"c":"Planification","i":"Le plan de prospection est réaliste et priorisé"},{"c":"Argumentation","i":"Les choix sont justifiés par des données et des arguments commerciaux solides"}],reflexivite_q:"Quels critères de qualification d'un prospect te semblent les plus importants pour LABORO ? Pourquoi certains prospects sont-ils plus prioritaires que d'autres ?",reflexivite:3},
  {id:"B42-P1",titre:"Préparer un premier plan de prospection téléphonique",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas identifier les étapes d'une opération de prospection et comprendre les outils utilisés par les commerciaux de LABORO.",palier:1,option:"PVOC",dossier:{l:"Fiche prospect — AS Palaiseau Football",rows:[["Contact","M. Moreau — responsable administratif"],["Structure","Association — 280 licenciés — 22 équipes"],["Besoins estimés","Maillots flocage, ballons, équipements"],["Budget estimé","4 000 à 8 000 €/an"],["Statut","Prospect froid — identifié forum sport mars 2026"],["Dernier contact","Aucun"]]},contexte:"Nina Chevalier vous confie votre premier appel de prospection. La cible est M. Moreau, responsable de l'AS Palaiseau Football. Il ne vous connait pas.",activites:[{t:"Préparer l'appel",q:["1.1  Lister les 5 informations à connaitre sur l'AS Palaiseau avant de décrocher votre téléphone.","1.2  Rédiger le plan d'appel complet : accroche de 2 phrases, presentation LABORO en 20 secondes, 3 questions de découverte BANT, proposition de RDV, formule de congé."]},{t:"Anticiper les objections et conclure",q:["2.1  M. Moreau dit : \"Envoyez-moi une documentation, je regarderai.\" Rédiger votre réponse complète pour ne pas perdre le contact.","2.2  Il accepte un rendez-vous téléphonique mardi à 10h. Rédiger le mail de confirmation envoyé dans l'heure.","2.3  Que saisir dans LABORO Connect dans les 10 minutes suivant l'appel ?"]}],livrable:"5 infos à préparer + plan d'appel complet + réponse à l'objection + mail de confirmation + mise à jour LABORO Connect",criteres:[{"c":"Identification des étapes","i":"Je décris correctement les étapes d'une opération de prospection"},{"c":"Connaissance des outils","i":"Je cite les outils utilisés par les commerciaux LABORO pour prospecter"},{"c":"Compréhension de l'argumentaire","i":"Je décris les éléments clés d'un argumentaire de prospection"}],reflexivite:0},
  {id:"B42-P2",titre:"Concevoir une campagne de prospection multicanale",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas concevoir les supports d'une opération de prospection — argumentaire, plan de découverte, outils de suivi.",palier:2,option:"PVOC",dossier:{l:"Ressources disponibles",rows:[["Budget campagne","350 €"],["Durée","4 semaines"],["Cible","Clubs sportifs Essonne — 50 à 300 licenciés"],["Base de données","68 clubs identifiés — 41 qualifiés BANT"],["Objectif","Obtenir 8 RDV et signer 2 contrats"],["Outils disponibles","Téléphone · Mail · LinkedIn · Plaquette LABORO"]]},contexte:"Nina Chevalier vous demande de concevoir une campagne de prospection ciblant les clubs sportifs de l'Essonne qui ne sont pas encore clients de LABORO.",activites:[{t:"Définir la stratégie et le message",q:["1.1  Choisir les 2 techniques de prospection les plus adaptées à cette cible et justifier chaque choix avec un argument chiffré.","1.2  Formuler les 3 arguments différenciateurs de LABORO face à Decathlon Pro pour ce profil de club sportif.","1.3  Rédiger l'e-mailing de prospection complet : objet (6 mots max), accroche, corps du message (150 mots max), call-to-action, signature."]},{t:"Planifier et budgéter",q:["2.1  Établir le planning semaine par semaine sur 4 semaines — actions, volumes, temps estimé.","2.2  Ventiler le budget de 350 € par poste de dépense en justifiant chaque ligne.","2.3  Définir 4 indicateurs de suivi avec leur formule et leur objectif cible."]}],livrable:"2 techniques justifiées + 3 arguments + e-mailing complet + planning 4 semaines + budget ventilé + 4 indicateurs",criteres:[{"c":"Construction de l'argumentaire","i":"Mon argumentaire est structuré, adapté à la cible et met en valeur l'offre LABORO"},{"c":"Plan de découverte","i":"Mes questions de découverte sont ouvertes, pertinentes et logiquement ordonnées"},{"c":"Outils de suivi","i":"Les outils de suivi proposés sont adaptés et exploitables"}],reflexivite:0},
  {id:"B42-P3",titre:"Concevoir le plan de prospection stratégique annuel",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas construire un plan de prospection complet pour LABORO en intégrant les objectifs, les cibles et les outils.",palier:3,option:"PVOC",dossier:{l:"Objectifs commerciaux B2B — LABORO N+1",rows:[["CA B2B à générer via prospection","+ 168 000 € HT (soit +15% du CA B2B)"],["Budget prospection annuel","1 800 €"],["Cibles prioritaires","CE grandes entreprises + collectivités + fédérations"],["Taux de transformation historique","12% prospects-clients"],["Délai moyen de décision","4 semaines CE · 8 semaines collectivités"],["Ressource commerciale","1 commercial terrain 3 jours / semaine"]]},contexte:"Pascal Berruelle vous demande de concevoir le plan de prospection annuel pour atteindre l'objectif de +168 000 € de CA B2B via de nouveaux clients.",activites:[{t:"Dimensionner et planifier",q:["1.1  Calculer le nombre de prospects à contacter pour atteindre l'objectif en remontant la chaîne de conversion.","1.2  Répartir les efforts de prospection par cible (CE, collectivités, fédérations) en justifiant la pondération.","1.3  Établir le calendrier trimestriel avec les campagnes, les volumes et les objectifs par période."]},{t:"Budgéter et anticiper les risques",q:["2.1  Ventiler les 1 800 € de budget sur 4 trimestres et par type d'action.","2.2  Identifier 3 risques majeurs pour ce plan et proposer un plan de contingence pour chacun.","2.3  Rédiger le plan de prospection annuel complet destiné à Pascal Berruelle et Nina Chevalier pour validation."]}],livrable:"Calcul nombre de prospects + répartition par cible + calendrier trimestriel + budget ventilé + 3 risques + plan annuel",criteres:[{"c":"Plan de prospection complet","i":"Le plan couvre toutes les étapes — ciblage, approche, outils, suivi, indicateurs"},{"c":"Cohérence stratégique","i":"Le plan est cohérent avec les objectifs commerciaux et les ressources de LABORO"},{"c":"Qualité des supports","i":"Les supports produits sont professionnels et directement utilisables"},{"c":"Indicateurs définis","i":"Les indicateurs de performance de la prospection sont précis et mesurables"}],reflexivite_q:"Qu'est-ce qui distingue un bon plan de prospection d'une simple liste de contacts à appeler ? Comment mesureras-tu le succès de ton plan ?",reflexivite:3},
  {id:"B43-P1",titre:"Réaliser un premier entretien de prospection",comp:"B4.3",comp_ref:"C4B.3",objectif:"Dans cette mission, tu vas identifier les techniques de prise de contact et de qualification d'un prospect dans le contexte B2B de LABORO.",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",palier:1,option:"PVOC",dossier:{l:"Contexte RDV téléphonique — Comité 91 Handball",rows:[["Contact","Pierre Lambert — responsable achats"],["Structure","42 clubs affiliés — 1 200 licenciés en Essonne"],["Commandes estimées","Ballons, filets, dossards, équipements terrain"],["Budget annuel estimé","5 000 à 10 000 €/an"],["Historique","Prospect froid — 1er contact obtenu par phoning la semaine dernière"],["Durée prévue du RDV","20 minutes"]]},contexte:"Pierre Lambert vous a accordé un rendez-vous téléphonique de 20 minutes suite à votre appel de prospection. C'est votre premier vrai entretien de découverte commercial.",activites:[{t:"Conduire l'entretien de découverte",q:["Complete cette accroche : Bonjour M. ___, merci de m'accorder ce ___. Je propose d'aborder ___ en ___ minutes","1.2  Rédiger les 4 questions BANT à poser dans l'ordre logique pour qualifier précisément le potentiel du Comité 91 Handball."]},{t:"Reformuler et proposer",q:["2.1  Pierre Lambert révèle : budget de 6 000 €/an, décision en mars pour la saison suivante, besoin de 30 ballons + flocage équipes. Reformuler ces informations en 3 phrases pour valider votre compréhension.","2.2  Proposer 2 références du catalogue LABORO adaptées à ces besoins. Justifier chaque choix avec un argument ciblé sur ce qu'il vient de dire.","2.3  Conclure l'entretien par une proposition de prochaine étape concrète (devis, visite, autre) et rédiger la formule de congé professionnelle."]}],livrable:"Accroche rédigée + 4 questions BANT + reformulation + 2 produits justifiés + conclusion avec prochaine étape",criteres:[{"c":"Connaissance des techniques de contact","i":"Je décris les techniques de prise de contact adaptées à la prospection B2B"},{"c":"Qualification du prospect","i":"J'identifie les informations à recueillir pour qualifier un prospect LABORO"},{"c":"Posture professionnelle","i":"Je décris les attitudes attendues lors d'un contact commercial B2B"}],reflexivite:0},
  {id:"B43-P2",titre:"Mener une tournée de prospection terrain",comp:"B4.3",comp_ref:"C4B.3",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",objectif:"Dans cette mission, tu vas mettre en œuvre une action de prospection téléphonique ou physique en appliquant les techniques LABORO.",palier:2,option:"PVOC",dossier:{l:"Planning tournée — secteur Massy / Saclay / Palaiseau",rows:[["9h00","MJC de Massy — Service sport — Camille Dufour — prospect froid"],["11h00","AS Palaiseau Football — M. Moreau — RDV qualifié — budget 6 000 €"],["14h00","CE Thales Massy — Isabelle Faure — client existant — visite de suivi"],["16h00","Comité dép. 91 Handball — Pierre Lambert — 1er RDV en face-à-face"],["Budget déplacement","65 € — véhicule LABORO"],["Objectif","1 devis signé ou confirmé + 2 relances de prospection"]]},contexte:"Nina Chevalier vous envoie mener votre premiere tournée de prospection terrain. Quatre visites dans la journée — profils et objectifs très différents.",activites:[{t:"Préparer et mener les visites",q:["1.1  Pour chacune des 4 visites, rédiger une accroche d'ouverture personnalisée (2 phrases max) adaptée au profil du contact.","1.2  Pour AS Palaiseau Football : M. Moreau est intéressé par 85 maillots flocage pour toutes ses équipes. Établir rapidement le devis et calculer le montant HT remisé (remise clubs > 50 unités) et TTC."]},{t:"Analyser et capitaliser",q:["2.1  CE Thales est déjà cliente. Mme Faure mentionne un projet de challenge sportif en juin. Décrire la stratégie de vente au rebond à mener dans les 15 minutes de la visite.","2.2  En fin de journée, rédiger le compte-rendu de tournée complet pour Nina Chevalier — résultats, prochaines étapes, points d'amélioration.","2.3  Calculer le taux de transformation de la tournée (RDV productifs / total RDV). Analyser et commenter."]}],livrable:"4 accroches personnalisées + devis AS Palaiseau calculé + stratégie vente au rebond Thales + compte-rendu + calcul taux",criteres:[{"c":"Prise de contact structurée","i":"Ma prise de contact respecte les étapes (présentation, accroche, objet de l'appel)"},{"c":"Qualification réussie","i":"J'obtiens les informations clés pour qualifier le prospect"},{"c":"Gestion des objections","i":"Je traite les objections courantes (pas le temps, pas intéressé) avec méthode"}],reflexivite:0},
  {id:"B43-P3",titre:"Piloter la mise en oeuvre d\"une opération de prospection",comp:"B4.3",comp_ref:"C4B.3",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",objectif:"Dans cette mission, tu vas conduire une négociation commerciale B2B de bout en bout, de la prise de contact à la proposition commerciale.",palier:3,option:"PVOC",dossier:{l:"Bilan mi-opération — 5 semaines sur 10",rows:[["Prospects contactés","28 sur 40 prévus — soit 70%"],["RDV obtenus","10 — taux 36%"],["RDV effectués","7"],["Devis envoyés","4"],["Contrats signés","1 — CA 5 800 € HT"],["Contrats en négociation","2 — CA potentiel 14 200 € HT"],["Budget consommé","340 € sur 600 €"]]},contexte:"A mi-parcours de l'opération de prospection, Nina Chevalier vous demande un état des lieux complet et des propositions d'ajustement pour atteindre l'objectif de 4 contrats.",activites:[{t:"Analyser et ajuster",q:["1.1  Analyser la chaîne de conversion étape par étape. Où se situent les pertes les plus importantes ? Proposer une cause probable pour chacune.","1.2  Avec 2 contrats en négociation et 1 signé, calculer si l'objectif de 4 contrats en 5 semaines restantes est réaliste. Argumenter avec les données disponibles.","1.3  Proposer 3 ajustements tactiques concrets pour maximiser les chances d'atteindre l'objectif sur la deuxième moitié de l'opération."]},{t:"Gérer les négociations et rédiger",q:["2.1  L'un des 2 prospects en négociation demande 15% de remise supplémentaire pour signer avant vendredi. Décrire votre stratégie de réponse complète — que proposez-vous, comment défendez-vous la marge LABORO ?","2.2  Rédiger le rapport de mi-opération destiné à Nina Chevalier avec bilan chiffré, analyse et recommandations."]}],livrable:"Analyse chaîne conversion + calcul faisabilité + 3 ajustements + stratégie négociation + rapport mi-opération",criteres:[{"c":"Conduite de la négociation","i":"Je mène la négociation de bout en bout avec fluidité et méthode"},{"c":"Adaptation à l'interlocuteur","i":"Mon approche s'adapte au profil et aux enjeux de l'interlocuteur B2B"},{"c":"Proposition commerciale","i":"Ma proposition est construite, argumentée et adaptée aux besoins identifiés"},{"c":"Conclusion","i":"Je concluis la négociation de façon professionnelle (accord, étape suivante, suivi)"}],reflexivite_q:"Qu'as-tu appris sur ta propre façon de gérer une négociation B2B à travers cette mission ? Qu'aurais-tu fait différemment ?",reflexivite:3},
  {id:"B44-P1",titre:"Assurer le suivi d\"un devis et relancer un prospect",comp:"B4.4",comp_ref:"C4B.4",objectif:"Dans cette mission, tu vas identifier les indicateurs de suivi d'une action de prospection et comprendre leur utilité pour les commerciaux de LABORO.",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",palier:1,option:"PVOC",dossier:{l:"Suivi devis — Club Sportif Forêt de Sénart",rows:[["Prospect","Marc Girault — président — Club Sportif Forêt de Sénart"],["Devis","12 Chaussures running EasyRun — 1 476 € HT (remise 8%)"],["Date d'envoi du devis","Il y a 7 jours"],["Réponse","Aucune — pas de retour mail ni téléphone"],["Evenement club","Sortie sport le 20 avril — dans 12 jours"],["Statut LABORO Connect","Devis envoyé — relance prévue J+7"]]},contexte:"Marc Girault n'a pas donné suite à votre devis de 12 chaussures sport envoyé il y a 7 jours. Nina Chevalier vous demande de le relancer.",activites:[{t:"Préparer et mener la relance",q:["1.1  Avant de relancer Marc Girault, quelles informations devez-vous vérifier dans LABORO Connect ? Lister les 4 éléments à contrôler.","1.2  Rédiger le mail de relance J+7 à Marc Girault — objet, corps (80 mots max), call-to-action. Apporter un élément nouveau par rapport au devis initial."]},{t:"Anticiper et mettre a jour",q:["2.1  Marc Girault rappelle et dit qu'il hésite encore — le délai de livraison de 48h est important pour lui avant la sortie du 20 avril. Rédiger votre réponse téléphonique complète.","2.2  La conversation se conclut positivement — il va signer la semaine prochaine. Que saisissez-vous dans LABORO Connect dans les 10 minutes suivantes pour ne rien oublier ?"]}],livrable:"4 éléments à vérifier + mail de relance + réponse téléphonique + mise à jour LABORO Connect",criteres:[{"c":"Identification des indicateurs","i":"Je cite les indicateurs de suivi d'une prospection (taux de contact, taux de transformation...)"},{"c":"Lecture des résultats","i":"Je lis et décris correctement les résultats d'une action de prospection"},{"c":"Identification des écarts","i":"Je repère les écarts entre objectifs et résultats"}],reflexivite:0},
  {id:"B44-P2",titre:"Gérer le suivi d\"une opération de prospection complète",comp:"B4.4",comp_ref:"C4B.4",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",objectif:"Dans cette mission, tu vas analyser les résultats d'une action de prospection à partir des indicateurs fournis et identifier les écarts.",palier:2,option:"PVOC",dossier:{l:"Bilan prospection 4 semaines — clubs sportifs Essonne",rows:[["Prospects contactés","41"],["RDV obtenus","14 — taux 34%"],["Devis envoyés","9"],["Devis signés","3 — CA 22 100 € HT"],["Devis en attente","6 — CA potentiel 41 400 € HT"],["Devis sans réponse > 10 jours","4"],["Objectif initial","5 contrats"]]},contexte:"L'opération de 4 semaines est terminée mais 6 devis sont encore en attente. Nina Chevalier vous demande de gérer le suivi de ces devis pour transformer un maximum d'entre eux.",activites:[{t:"Analyser et prioriser",q:["1.1  Calculer le taux de transformation devis-contrat actuel. Quel serait-il si tous les devis en attente se convertissaient ?","1.2  Pour les 4 devis sans réponse depuis plus de 10 jours, proposer une stratégie de relance différenciée selon le profil du prospect — e-mail, téléphone ou visite ?"]},{t:"Relancer et capitaliser",q:["2.1  Rédiger le mail de relance pour le CE ArianeGroup (devis de 18 000 € HT envoyé il y a 12 jours sans réponse). Objet percutant + corps de 100 mots max.","2.2  Rédiger le rapport de suivi post-opération pour Nina Chevalier : résultats consolidés, analyse des causes de non-réponse, recommandations pour la prochaine opération."]}],livrable:"Calcul taux de transformation + stratégie relance différenciée + mail CE ArianeGroup + rapport de suivi",criteres:[{"c":"Calcul des indicateurs","i":"Je calcule correctement les indicateurs demandés"},{"c":"Analyse des écarts","i":"Mon analyse des écarts est structurée et s'appuie sur les données"},{"c":"Formulation de recommandations","i":"Je propose au moins 2 recommandations concrètes pour améliorer les résultats"}],reflexivite:0},
  {id:"B44-P3",titre:"Concevoir le systeme de suivi et d\"alerte commercial",comp:"B4.4",comp_ref:"C4B.4",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",objectif:"Dans cette mission, tu vas évaluer une action de prospection de LABORO, en calculant les indicateurs clés et en formulant des recommandations.",palier:3,option:"PVOC",dossier:{l:"Diagnostic suivi commercial LABORO — situation actuelle",rows:[["Devis envoyés sans relance dans les 7 jours","38% — soit 14 sur 37"],["Contrats perdus faute de relance","9 — CA perdu estimé 76 000 €"],["Délai moyen entre devis et signature","18 jours — objectif : 12 jours"],["LABORO Connect mis à jour dans les 24h","52% des commerciaux — objectif 100%"],["Alertes automatiques dans le CRM","Inexistantes à ce jour"]]},contexte:"Pascal Berruelle constate que LABORO perd trop d'affaires faute de suivi structuré. Il vous confie la conception d'un systeme d'alerte et de suivi commercial intégré à LABORO Connect.",activites:[{t:"Concevoir le dispositif",q:["1.1  Conçois le tableau de suivi des prospects LABORO B2B : colonnes, données à renseigner, codes couleur selon l'avancement. Justifie tes choix.","1.2  M. Moreau dit que votre solution est trop chere. Propose une reponse argumentee qui maintient la valeur percue sans brader le prix.","1.3  Définis 3 règles d'or du suivi client B2B chez LABORO. Pour chacune : la règle, la raison, et la conséquence si elle n'est pas respectée."]},{t:"Former et pérenniser",q:["2.1  Comment t'assures-tu que le dispositif de suivi sera utilisé par toute l'équipe dans 6 mois ? Propose 3 mécanismes concrets.","2.2  Rédige la fiche mémo (1 page max) que tu donnerais à un nouveau commercial pour lui expliquer le système de suivi en place."]}],criteres:[{"c":"Maîtrise des indicateurs","i":"Tous les indicateurs sont calculés et interprétés correctement"},{"c":"Analyse complète","i":"Mon analyse identifie causes, conséquences et leviers d'amélioration"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont priorisées, justifiées et chiffrées quand possible"},{"c":"Tableau de bord","i":"Le tableau de bord proposé est complet, lisible et exploitable"}],reflexivite_q:"Quels indicateurs te semblent les plus pertinents pour piloter la prospection de LABORO ? Pourquoi le taux de transformation est-il l'indicateur clé ?",reflexivite:3},
  {id:"B45-P1",titre:"Défendre l\"offre LABORO face a un concurrent",comp:"B4.5",comp_ref:"C4B.5",objectif:"Dans cette mission, tu vas identifier les éléments d'une offre commerciale B2B et comprendre les enjeux de la valorisation de l'offre LABORO.",comp_libelle:"Bloc 4B — Valoriser les produits et/ou les services",palier:1,option:"PVOC",dossier:{l:"Situation RDV — M. Moreau AS Palaiseau Football",rows:[["Besoin","20 maillots flocage pour la saison"],["Offre LABORO","28 €/u × 20 = 560 € HT — remise 8% = 515,20 € HT"],["Offre Decathlon Pro présentée","24 €/u × 20 = 480 € HT — sans remise"],["Écart","35,20 € HT en faveur de Decathlon Pro"],["Avantage LABORO","Délai flocage 3 sem. vs 5 sem. Decathlon · Commercial dédié"],["Saison démarrage","Dans 4 semaines"]]},contexte:"M. Moreau vous montre un devis de Decathlon Pro pour les mêmes maillots, moins chers de 35 €. Il hésite. Nina Chevalier vous a briefé : ne jamais baisser le prix sans contrepartie.",activites:[{t:"Analyser et argumenter",q:["1.1  Identifier les 2 critères sur lesquels LABORO est objectivement supérieur à Decathlon Pro dans ce contexte précis.","1.2  M. Moreau dit : \"LABORO c'est 35 € de plus pour la même chose.\" Rédiger votre réponse argumentée complète en 5 à 8 phrases — sans dénigrer Decathlon."]},{t:"Conclure ou proposer une alternative",q:["2.1  M. Moreau semble convaincu sur la qualité mais hésite encore sur le prix. Proposer une offre d'entrée de gamme permettant de le faire rentrer chez LABORO sans sacrifier la marge durablement.","2.2  La vente se conclut. Rédiger les 3 phrases de prise de congé professionnelle en valorisant la relation naissante avec l'AS Palaiseau."]}],livrable:"2 critères de supériorité + réponse à l'objection rédigée + offre d'entrée proposée + prise de congé",criteres:[{"c":"Identification des composantes de l'offre","i":"Je décris les éléments clés d'une offre commerciale B2B (produits, prix, conditions, délais)"},{"c":"Compréhension des enjeux","i":"J'explique pourquoi la valorisation de l'offre est cruciale dans la vente B2B"},{"c":"Lecture d'une offre existante","i":"Je lis et décris correctement une offre commerciale LABORO fournie"}],reflexivite:0},
  {id:"B45-P2",titre:"Construire une proposition de valeur pour un appel d\"offres B2B",comp:"B4.5",comp_ref:"C4B.5",comp_libelle:"Bloc 4B — Valoriser les produits et/ou les services",objectif:"Dans cette mission, tu vas construire une offre commerciale argumentée adaptée à un client B2B de LABORO.",palier:2,option:"PVOC",dossier:{l:"Appel d'offres informel — MJC de Massy",rows:[["Budget annuel sport municipal","14 000 €/an"],["Contact","Camille Dufour — responsable sport municipal"],["Fournisseur actuel","Decathlon Pro — relation 2 ans"],["Critères annoncés","Prix 35% · Délais 30% · Conseil 20% · Proximité 15%"],["Concurrents en lice","LABORO · Decathlon Pro · SportRun Pro"],["Délai de décision","3 semaines"]]},contexte:"La MJC de Massy consulte 3 fournisseurs pour ses achats sportifs annuels. C'est une opportunité de 14 000 €/an. Camille Dufour attend une proposition complète d'ici vendredi.",activites:[{t:"Analyser et concevoir la proposition",q:["1.1  Analyser les critères de décision de la MJC de Massy. Sur lesquels LABORO peut-il gagner face à Decathlon Pro ? Justifier avec des données concrètes.","1.2  Concevoir la proposition commerciale LABORO pour ce marché — 2 offres à des niveaux différents permettant à Camille Dufour de choisir.","1.3  Préparer 3 objections probables de Camille Dufour et une réponse argumentée pour chacune."]},{t:"Défendre et conclure",q:["2.1  Camille Dufour annonce que Decathlon Pro est moins cher sur les équipements collectifs. Rédiger votre réponse pour valoriser l'offre LABORO sans brader.","2.2  Le RDV se conclut favorablement. Rédiger le mail de synthèse envoyé dans les 2 heures après la réunion."]}],livrable:"Analyse critères + 2 offres + 3 objections/réponses + réponse objection prix + mail post-RDV",criteres:[{"c":"Structure de l'offre","i":"Mon offre est complète et bien structurée (présentation, produits, prix, conditions)"},{"c":"Argumentation","i":"L'offre met en valeur les points forts de LABORO adaptés aux besoins du client"},{"c":"Présentation professionnelle","i":"La présentation est claire, professionnelle et adaptée à un client B2B"}],reflexivite:0},
  {id:"B45-P3",titre:"Piloter la valorisation de l\"offre LABORO a l\"échelle du portefeuille",comp:"B4.5",comp_ref:"C4B.5",comp_libelle:"Bloc 4B — Valoriser les produits et/ou les services",objectif:"Dans cette mission, tu vas élaborer et présenter une offre commerciale complexe pour LABORO, en intégrant les besoins spécifiques du client.",palier:3,option:"PVOC",dossier:{l:"Analyse concurrentielle LABORO — marché B2B Essonne",rows:[["Part de marché LABORO estimée","8% — objectif 12% en N+1"],["Principal concurrent","Decathlon Pro — 31% de PDM"],["Avantage prix Decathlon Pro","- 8% à - 15% sur équipements standards"],["Taux de perte face à Decathlon","43% des devis perdus — cause prix 61%"],["Taux de fidélisation LABORO","74% — vs 58% Decathlon Pro estimé"],["CA moyen client LABORO","19 500 € vs 11 200 € Decathlon Pro estimé"]]},contexte:"Pascal Berruelle veut que LABORO gagne systématiquement sur la valeur et non sur le prix. Il vous demande de concevoir la stratégie de valorisation de l'offre pour l'ensemble du portefeuille B2B.",activites:[{t:"Analyser et concevoir la strategie",q:["1.1  Analyse le positionnement prix de LABORO face aux 3 concurrents du dossier. Quelle marge de manoeuvre as-tu ? Propose une stratégie de prix argumentée.","1.2  Identifie les 3 arguments de valorisation les plus percutants pour LABORO auprès des CE. Appuie-toi sur les données du dossier.","1.3  Anticipe les 3 principales objections des CE et prépare une réponse pour chacune intégrant des éléments chiffrés."]},{t:"Former et déployer",q:["2.1  Comment mesurerais-tu l'efficacité de cette stratégie de valorisation après 3 mois ? Définis 3 indicateurs précis.","2.2  Rédige le plan de formation de 2 heures pour former l'équipe à la valorisation de l'offre B2B."]}],criteres:[{"c":"Offre complète et personnalisée","i":"L'offre est entièrement adaptée aux besoins spécifiques du client B2B"},{"c":"Argumentation experte","i":"L'argumentation mobilise des techniques avancées (ROI, références clients, garanties)"},{"c":"Présentation convaincante","i":"La présentation est structurée pour maximiser l'impact sur le décideur"},{"c":"Gestion des objections anticipée","i":"J'anticipe les objections probables et prépare des réponses adaptées"}],reflexivite_q:"En quoi la personnalisation d'une offre B2B est-elle un avantage concurrentiel pour LABORO ? Qu'est-ce qui fait qu'une offre convainc vraiment un décideur ?",reflexivite:3},
  {id:"M075",titre:"Gérer les stocks du rayon et calculer la démarque",comp:"C4A.1",comp_ref:"C4A.1",objectif:"Dans cette mission, tu vas analyser les opérations préalables à la mise en vente chez LABORO — gestion des prix, des marges et de l'assortiment.",comp_libelle:"Bloc 4A — Assurer les opérations préalables à la vente",palier:2,option:"AGEC",dossier:{l:"État des stocks rayon chaussures — LABORO — 1er avril 2026",rows:[["Chaussures running EasyRun T42","Stock : 3 · PAHT : 24 € · DDM : n/a · État : OK"],["Chaussures running Velocity T40","Stock : 8 · PAHT : 38 € · DDM : n/a · État : OK"],["tapis de yoga 6mm","Stock : 2 · PAHT : 35 € · DDM : n/a · État : emballage abîmé"],["Ceinture porte-bidon LABORO 2x250ml","Stock : 45 · PAHT : 1,20 € · DDM : 15/04/2026 · État : OK"],["Barres énergétiques LABORO","Stock : 23 · PAHT : 1,80 € · DDM : 20/04/2026 · État : OK"],["Chaussettes anti-ampoules LABORO x3","Stock : 12 · PAHT : 8,50 € · DDM : 01/05/2026 · État : OK"],["PVTTC imposé","6 €"],["TVA","20%"],["Seuil alerte fournisseur","Stock < 5 unités = réassort obligatoire"]]},contexte:"Romain Sauzet te demande de faire le point sur les stocks du rayon nutrition/accessoires avant le changement de saison. Certains produits posent problème.",activites:[{t:"Identifier les produits à traiter",q:["1.1  Identifier tous les produits qui nécessitent une action particulière au 1er avril. Pour chacun, préciser la raison et l'action à mener — en t'appuyant sur les données du dossier.","1.2  Calculer le taux de démarque connue HT de la tapis de yoga 6mm (emballage abîmé). Commenter le résultat. Rappel : taux démarque = (valeur démarque HT ÷ CA HT total) × 100."]},{t:"Gérer les produits à DDM courte",q:["2.1  Romain Sauzet décide d'écouler les ceintures porte-bidon et chaussettes dont la DDM est inférieure à 30 jours par une opération promotionnelle. Il hésite entre : 3 achetés = le 4e à 1 € TTC · ou −30% sur l'ensemble. Calculer le CA HT et la marge dégagée pour chaque option. Arrondir à 2 décimales.","2.2  Identifier l'opération la plus rentable et justifier ton choix. Proposer en plus une action éco-responsable pour les invendus restants."]}],livrable:"Produits identifiés + actions + calcul taux démarque + calcul CA/marge 2 promos + choix justifié + action éco",criteres:[{"c":"Maîtrise du calcul de prix","i":"Je calcule correctement PVHT et PVTTC à partir du PAHT et des taux fournis"},{"c":"Analyse concurrentielle","i":"Je compare les prix LABORO avec la concurrence de façon structurée"},{"c":"Justification des choix de prix","i":"Je justifie la politique tarifaire retenue en m'appuyant sur des données concrètes"}],reflexivite:0},
  {id:"M076",titre:"Sélectionner un fournisseur et établir une commande",comp:"C4A.1",comp_ref:"C4A.1",comp_libelle:"Bloc 4A — Assurer les opérations préalables à la vente",objectif:"Dans cette mission, tu vas analyser les opérations préalables à la mise en vente chez LABORO — gestion des prix, des marges et de l'assortiment.",palier:2,option:"AGEC",dossier:{l:"Renouvellement fournisseur — chaussures sport été 2026",rows:[["Objectif ventes été","405 paires (ventes N-1 : 350 paires · objectif +15%)"],["Fournisseur A — SportPro","PAHT : 75 € · colisage : par 6 paires · remise : 5% de 1 à 60 paires / 10% dès 61 · délai livraison : 48h · franco de port"],["Fournisseur B — MontagneSport","PAHT : 70 € · colisage : par 4 paires · remise : aucune · délai livraison : 7 jours · frais de port : 18 € par commande"],["Politique LABORO","Made in Europe privilégié · délai livraison < 5 jours · marge min 40%"],["SportPro","Fabriqué en Portugal"],["MontagneSport","Fabriqué en Chine"]]},contexte:"Le contrat avec le fournisseur de chaussures sport prend fin. Romain Sauzet te demande d'analyser deux nouveaux fournisseurs et d'établir la commande auprès du plus adapté.",activites:[{t:"Calculer et comparer",q:["1.1  Calculer le nombre total de paires à commander (arrondir à l'entier supérieur tenant compte du colisage de chaque fournisseur).","1.2  Pour chaque fournisseur, calculer : le nombre de colis à commander · le montant total de la commande (remise et frais de port inclus). Arrondir à 2 décimales."]},{t:"Choisir et argumenter",q:["2.1  Sélectionner le fournisseur le plus adapté à la politique commerciale de LABORO. Justifier en prenant en compte tous les critères — pas seulement le prix.","2.2  Rédiger le bon de commande synthétique à envoyer au fournisseur retenu : références, quantités, modalités."]}],livrable:"Calcul paires + calcul colis et montants pour chaque fournisseur + choix argumenté + bon de commande",criteres:[{"c":"Maîtrise du calcul de prix","i":"Je calcule correctement PVHT et PVTTC à partir du PAHT et des taux fournis"},{"c":"Analyse concurrentielle","i":"Je compare les prix LABORO avec la concurrence de façon structurée"},{"c":"Justification des choix de prix","i":"Je justifie la politique tarifaire retenue en m'appuyant sur des données concrètes"}],reflexivite:0},
  {id:"M096",titre:"Piloter le changement de saison du rayon chaussures",comp:"C4A.1",comp_ref:"C4A.1",objectif:"Dans cette mission, tu vas gérer de façon autonome les opérations préalables à la vente en intégrant plusieurs contraintes — prix, stocks, concurrence.",comp_libelle:"Bloc 4A — Assurer les opérations préalables à la vente",palier:3,option:"AGEC",dossier:{l:"Bilan rayon chaussures — fin saison hiver 2026",rows:[["Références hiver à déréférencer","14 références · stock résiduel total : 67 unités"],["Taux de démarque hiver","3,8% — objectif < 2%"],["Taux de rupture","8,2% — objectif < 2%"],["Nouvelles références printemps","22 références sport + 8 références running route"],["Budget merchandising","350 €"],["Date lancement collection printemps","15 avril 2026"],["Fournisseur principal LABORO","Préconisations implantation : best-sellers niveau yeux · nouveautés zone chaude entrée"]]},contexte:"Romain Sauzet te confie la gestion complète du changement de saison du rayon chaussures. C'est la première fois que tu pilotes cette opération seul(e). Objectif : rayon printemps opérationnel le 15 avril.",activites:[{t:"Gérer les stocks sortants",q:["1.1  Le taux de démarque de 3,8% est au-dessus de l'objectif. Identifier 3 causes probables et proposer une action corrective pour chacune.","1.2  Pour écouler les 67 unités restantes avant le 15 avril, concevoir une opération promotionnelle : type de promotion, calcul de la remise maximale acceptable (marge minimale 25%), support de communication.","1.3  Rédiger le bon de retour fournisseur pour les 14 références déréférencées — structure professionnelle, motif, conditions."]},{t:"Mettre en place la nouvelle collection",q:["2.1  Concevoir l'implantation du rayon printemps : plan de masse avec zones chaudes/froides, niveaux de présentation, facings des best-sellers, PLV. Justifier chaque choix par une règle de merchandising.","2.2  Définir 4 indicateurs pour évaluer la performance du rayon au bout de 30 jours — formule et objectif cible.","2.3  Réflexivité : qu'aurais-tu fait différemment si tu avais piloté ce rayon dès le début de la saison hiver ?"]}],livrable:"3 causes démarque + promo écoulement + bon de retour + plan implantation + 4 indicateurs + réflexivité",criteres:[{"c":"Maîtrise des calculs","i":"Tous les calculs sont corrects, détaillés et bien présentés"},{"c":"Analyse multi-critères","i":"Mon analyse intègre marge, concurrence, positionnement et image LABORO"},{"c":"Recommandations argumentées","i":"Mes recommandations de prix sont justifiées et cohérentes avec la stratégie LABORO"},{"c":"Gestion de la rentabilité","i":"Je calcule et interprète correctement les indicateurs de rentabilité demandés"}],reflexivite_q:"En quoi la politique tarifaire d'une enseigne comme LABORO est-elle un équilibre entre rentabilité, positionnement et satisfaction client ? Illustre par un exemple tiré de cette mission.",reflexivite:3},
  {id:"M097",titre:"Analyser et améliorer les performances de laboro-sport.fr",comp:"C4A.3",comp_ref:"C4A.3",comp_libelle:"Bloc 4A — Développer la clientèle",objectif:"Dans cette mission, tu vas concevoir et mettre en œuvre des actions de développement de la clientèle adaptées au contexte LABORO.",palier:3,option:"AGEC",dossier:{l:"Résultats e-commerce LABORO — T1 2026",rows:[["CA site internet","18 400 € HT"],["CA total LABORO","278 000 € HT"],["Visiteurs uniques","24 680"],["Commandes passées","312"],["Panier moyen en ligne","58,97 €"],["Panier moyen showroom","187 €"],["Taux de conversion e-commerce moyen national","2,96%"],["Taux d'abandon de panier","71%"],["Avis clients sur le site","3 — note moyenne 4,2/5"],["Délai affiché sur le site","Non mentionné"],["FAQ","Inexistante"],["Réseaux sociaux","Instagram 1 240 abonnés — dernière publication : 3 semaines"]]},contexte:"Pascal Berruelle constate que le site laboro-sport.fr génère moins de 7% du CA total alors que l'e-commerce représente en moyenne 18% du CA dans le secteur sportif. Il te demande un diagnostic complet et un plan d'action.",activites:[{t:"Calculer et analyser",q:["1.1  Calculer le pourcentage des ventes en ligne dans le CA total et le taux de conversion du site. Arrondir à 2 décimales.","1.2  Comparer ces résultats avec la moyenne nationale e-commerce (2,96%). Que conclure sur la performance de laboro-sport.fr ?","1.3  Identifier 4 points faibles du site à partir des données du dossier. Pour chacun, proposer une amélioration concrète et justifiée."]},{t:"Construire le plan d'action",q:["2.1  Proposer 3 actions prioritaires pour améliorer le taux de conversion — par ordre d'impact décroissant. Pour chaque action : description, coût estimé, indicateur de suivi.","2.2  Rédiger la note de recommandation complète à Pascal Berruelle — diagnostic, priorités, objectif de taux de conversion à 6 mois.","2.3  Réflexivité : en quoi la performance d'un site e-commerce dépend-elle autant du travail en magasin que du travail digital ?"]}],livrable:"Calculs + comparaison nationale + 4 points faibles + 3 actions + note Pascal Berruelle + réflexivité",criteres:[{"c":"Conception de l'action","i":"L'action proposée est cohérente avec les objectifs et la cible de LABORO"},{"c":"Plan opérationnel","i":"Le plan d'action est détaillé, priorisé et réaliste"},{"c":"Argumentation","i":"Chaque choix est justifié par des données ou des arguments professionnels"},{"c":"Indicateurs de suivi","i":"Je définis des indicateurs précis pour évaluer l'efficacité de l'action"}],reflexivite_q:"En quoi les actions de développement clientèle que tu as proposées s'inscrivent-elles dans une logique de long terme pour LABORO ?",reflexivite:3},
  {id:"M098",titre:"Concevoir et déployer une communication digitale pour développer la clientèle",comp:"C4A.3",comp_ref:"C4A.3",comp_libelle:"Bloc 4A — Développer la clientèle",objectif:"Dans cette mission, tu vas concevoir et mettre en œuvre des actions de développement de la clientèle adaptées au contexte LABORO.",palier:3,option:"AGEC",dossier:{l:"Opération Sport en Essonne — LABORO partenaire",rows:[["Événement","Sport en Essonne — 800 coureurs — dimanche 18 mai"],["Objectif LABORO","Gagner 40 nouveaux clients sportifs · CA événement 4 000 €"],["Canaux disponibles","Instagram (1 240 abonnés) · Facebook (890 abonnés) · Newsletter (680 inscrits) · Google My Business"],["Budget communication","200 €"],["Délai","3 semaines avant l'événement"],["Données marché","87% des coureurs sport consultent les réseaux sociaux avant d'acheter leur équipement"]]},contexte:"LABORO est partenaire officiel du Sport en Essonne. Pascal Berruelle te confie la stratégie de communication digitale pour maximiser la visibilité et attirer de nouveaux clients.",activites:[{t:"Concevoir la stratégie",q:["1.1  Choisir les 2 canaux les plus adaptés parmi les 4 disponibles pour toucher les coureurs sport en Essonne. Justifier chaque choix avec un argument chiffré ou factuel.","1.2  Rédiger le post Instagram de lancement de l'opération — visuel décrit, texte (150 mots max), hashtags, call-to-action. Respecter les règles d'un post efficace.","1.3  Planifier le calendrier de communication sur 3 semaines — 6 actions minimum, canal, contenu, objectif de chaque publication."]},{t:"Mesurer et capitaliser",q:["2.1  Définir 4 indicateurs pour mesurer l'efficacité de la campagne — formule et objectif cible.","2.2  Ventiler les 200 € de budget entre les actions. Justifier chaque allocation.","2.3  Réflexivité : en quoi la communication digitale est-elle indissociable de l'animation en point de vente ? Illustrer par un exemple LABORO."]}],livrable:"2 canaux justifiés + post Instagram + planning 3 semaines + 4 indicateurs + budget ventilé + réflexivité",criteres:[{"c":"Conception de l'action","i":"L'action proposée est cohérente avec les objectifs et la cible de LABORO"},{"c":"Plan opérationnel","i":"Le plan d'action est détaillé, priorisé et réaliste"},{"c":"Argumentation","i":"Chaque choix est justifié par des données ou des arguments professionnels"},{"c":"Indicateurs de suivi","i":"Je définis des indicateurs précis pour évaluer l'efficacité de l'action"}],reflexivite_q:"En quoi les actions de développement clientèle que tu as proposées s'inscrivent-elles dans une logique de long terme pour LABORO ?",reflexivite:3},
  {id:"M099",titre:"Piloter la performance globale de l'espace commercial LABORO",comp:"C4A.3",comp_ref:"C4A.3",objectif:"Dans cette mission, tu vas piloter une stratégie de développement de la clientèle de LABORO en mesurant les résultats et en ajustant les actions.",comp_libelle:"Bloc 4A — Développer la clientèle",palier:4,option:"AGEC",dossier:{l:"Tableau de bord espace commercial LABORO — bilan annuel",rows:[["CA total","1 120 000 € — objectif 1 300 000 € dans 2 ans"],["Taux de démarque moyen","3,2% — objectif sectoriel < 1,5%"],["Taux de rupture","6,8% — objectif < 2%"],["Taux de conversion showroom","44% — objectif 55%"],["CA site internet","78 400 € — 7% du CA total"],["NPS","+ 22"],["Part des nouveaux clients","18% — objectif 25%"],["Marge moyenne","43,5%"]]},contexte:"Pascal Berruelle te confie la mission la plus stratégique de la plateforme LABORO : concevoir le plan de performance de l'espace commercial sur 2 ans, couvrant à la fois le point de vente physique et le site marchand.",activites:[{t:"Diagnostiquer et prioriser",q:["1.1  Analyser le tableau de bord : identifier les 3 indicateurs les plus préoccupants et leurs conséquences financières estimées pour LABORO.","1.2  Réaliser une analyse SWOT complète de l'espace commercial LABORO en t'appuyant sur toutes les données disponibles dans la plateforme.","1.3  Définir 3 axes stratégiques prioritaires pour les 24 mois, avec un objectif chiffré et un indicateur de suivi pour chacun."]},{t:"Construire et défendre le plan",q:["2.1  Pour chaque axe stratégique, proposer 2 actions concrètes — responsable, délai, budget estimé, indicateur de succès.","2.2  Anticiper les 3 principaux risques de ce plan et proposer une mesure de contingence pour chacun.","2.3  Rédiger le rapport stratégique complet destiné à Pascal Berruelle et aux associés — synthèse du diagnostic, axes prioritaires, plan d'action, objectifs à 24 mois.","2.4  Réflexivité approfondie : en quoi cette mission de pilotage stratégique diffère-t-elle de toutes les missions que tu as réalisées chez LABORO ? Qu'est-ce que ça révèle sur ce que signifie 'gérer un espace commercial' au sens plein du terme ?"]},{t:"Prioriser et décider",q:["3.1  Si vous deviez prioriser une seule action pour ameliorer la performance de LABORO l'an prochain, laquelle serait-ce et pourquoi ?"]}],livrable:"3 indicateurs analysés + SWOT + 3 axes + 6 actions + 3 risques + rapport stratégique + réflexivité",criteres:[{"c":"Vision stratégique","i":"Ma stratégie de développement clientèle est cohérente avec la politique globale de LABORO"},{"c":"Maîtrise des outils","i":"J'utilise les outils de CRM et de pilotage commercial avec expertise"},{"c":"Évaluation des résultats","i":"J'analyse les résultats des actions et propose des ajustements argumentés"},{"c":"Recul professionnel","i":"Je fais le lien entre développement clientèle et fidélisation"}],reflexivite_q:"Comment articuler conquête de nouveaux clients et fidélisation dans la stratégie commerciale de LABORO ?",reflexivite:4},
  {id:"M103",titre:"Mener une veille commerciale et en tirer des conclusions",comp:"C1.1",comp_ref:"C1.1",comp_libelle:"Bloc 1 — Assurer la veille commerciale",objectif:"Dans cette mission, tu vas exploiter une veille commerciale pour formuler des recommandations argumentées sur le positionnement produit ou prix de LABORO.",palier:3,option:"AGEC",dossier:{l:"Observations marché sport — Essonne — mars 2026",rows:[["Decathlon Évry","Ouverture d'un corner running rénové — 3 nouvelles références LABORO"],["SportRun Massy","Promotion -20% sur chaussures sport — valable 2 semaines"],["Forum sport Essonne","Participation de 38 clubs — LABORO présent comme partenaire"],["Tendance marché","Progression de +12% du sport en Île-de-France vs N-1"],["Instagram Decathlon local","42 publications ce mois — taux d'engagement moyen 3,8%"],["Nouveauté fournisseur LABORO","Nouvelle gamme Downshifter 7 disponible à partir d'avril"]]},contexte:"Pascal Berruelle te demande de faire le point sur ce qui se passe autour de LABORO : concurrents, tendances, nouveautés. Il veut une note de veille synthétique avant la réunion de direction de vendredi.",activites:[{t:"Collecter et organiser les informations",q:["1.1  À partir des observations du dossier, classer les informations en 3 catégories : veille concurrentielle · veille produits · veille marché. Présenter le résultat dans un tableau.","1.2  Parmi toutes ces informations, identifier celle qui représente la menace la plus immédiate pour LABORO. Justifier en 3 à 4 phrases.","1.3  Identifier l'opportunité la plus intéressante pour LABORO parmi ces observations. Expliquer comment en profiter concrètement."]},{t:"Produire et transmettre",q:["2.1  Rédiger la note de veille à l'attention de Pascal Berruelle — 15 à 20 lignes maximum. Structure : titre · faits clés · menace principale · opportunité · recommandation.","2.2  Réflexivité : pourquoi surveiller ses concurrents régulièrement est-il indispensable dans le commerce ? Illustrer avec un exemple concret tiré de ce dossier."]}],livrable:"Tableau de classement + menace identifiée + opportunité + note de veille rédigée + réflexivité",criteres:[{"c":"Exploitation complète des données","i":"J'exploite toutes les informations pertinentes du dossier sans omission majeure"},{"c":"Analyse argumentée","i":"Mon analyse distingue faits, interprétations et recommandations"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont concrètes, réalisables et adaptées à LABORO"},{"c":"Rigueur professionnelle","i":"Le vocabulaire utilisé est celui d'un(e) professionnel(le) du commerce"}],reflexivite_q:"Quelles informations du dossier t'ont été les plus utiles pour construire ton analyse ? Qu'aurais-tu cherché en plus si tu avais eu plus de temps ?",reflexivite:3},
  {id:"M104",titre:"Conduire et conclure une vente conseil",comp:"C1.3",comp_ref:"C1.3",comp_libelle:"Bloc 1 — Assurer l’exécution de la vente",objectif:"Dans cette mission, tu vas gérer de façon autonome l'ensemble des opérations post-vente dans des situations complexes ou omnicanales.",palier:3,option:"AGEC",dossier:{l:"Fiche client — Marion Tessier",rows:[["Profil","Femme · 34 ans · reprend la course à pied après 3 ans d'arrêt"],["Budget","150 à 180 € maximum pour les chaussures"],["Pratique","Running route 2 à 3 fois par semaine · 5 à 8 km · terrain plat"],["Point fort","Motivée, déterminée à ne pas se blesser cette fois"],["Point de vigilance","Mauvaise expérience avec des chaussures trop rigides l'an dernier"],["Produits disponibles","Chaussures running Velocity (159 €) · Chaussures route Velocity (179 €) · Chaussures route Velocity (149 €)"]]},contexte:"Marion Tessier entre dans le showroom LABORO. Elle t'explique sa situation. Romain Sauzet t'observe de loin — c'est une évaluation informelle de tes techniques de vente.",activites:[{t:"Découvrir et conseiller",q:["1.1  À partir de la fiche client, identifier les 3 critères de choix prioritaires de Marion. Expliquer pourquoi chacun compte pour elle.","1.2  Parmi les 3 chaussures disponibles, laquelle recommandes-tu à Marion ? Justifier en t'appuyant sur ses critères — pas seulement sur le prix.","1.3  Rédiger le script de présentation du produit recommandé : caractéristique → avantage → bénéfice pour Marion (méthode CAB). 3 arguments minimum."]},{t:"Traiter l'objection et conclure",q:["2.1  Marion dit : 'Je pensais prendre les LABORO, elles sont moins chères.' Rédiger ta réponse complète pour défendre ta recommandation sans la brusquer.","2.2  Comment proposes-tu la vente complémentaire ? Citer 2 produits adaptés à son profil et formuler la proposition naturellement.","2.3  Réflexivité : qu'est-ce qui distingue un vendeur qui conseille d'un vendeur qui vend ? Illustrer avec cette situation."]}],livrable:"3 critères identifiés + recommandation justifiée + 3 arguments CAB + réponse objection + vente complémentaire + réflexivité",criteres:[{"c":"Gestion autonome","i":"Je gère l'ensemble des opérations post-vente de façon autonome, même dans des situations complexes"},{"c":"Maîtrise des procédures","i":"Toutes les procédures sont appliquées correctement et dans le bon ordre"},{"c":"Qualité des documents","i":"Les documents produits sont professionnels et sans erreur"},{"c":"Anticipation des problèmes","i":"Je repère et traite les anomalies avant qu'elles n'affectent la relation client"}],reflexivite_q:"Quelles procédures post-vente t'ont semblé les plus complexes à appliquer ? Comment éviter les erreurs dans ces étapes ?",reflexivite:3},
  {id:"M105",titre:"Gérer le suivi d'une commande et résoudre un problème de livraison",comp:"C2.1",comp_ref:"C2.1",comp_libelle:"Bloc 2 — Assurer le suivi de la commande du produit et/ou du service",objectif:"Dans cette mission, tu vas gérer des situations de commande complexes — rupture de stock, délais, commandes B2B — en proposant des solutions adaptées.",palier:3,option:"AGEC",dossier:{l:"Commande client — Club Sportif Sénart",rows:[["Client","Marc Girault — Club Sportif Forêt de Sénart"],["Commande","20 maillots flocage · LABORO logo · taille assortie · délai annoncé : 3 semaines"],["Date de commande","3 avril 2026"],["Livraison prévue","24 avril 2026"],["Situation actuelle","28 avril — commande non reçue · Marc Girault n'a pas été prévenu"],["Fournisseur notre atelier de flocage","Retard de 10 jours annoncé ce matin — livraison repoussée au 4 mai"],["Événement club","Tournoi régional le 2 mai — les maillots sont indispensables"]]},contexte:"Romain Sauzet te montre un mail de notre atelier de flocage reçu ce matin. Marc Girault ne sait rien encore. Le tournoi est dans 4 jours. Il faut agir vite et de manière professionnelle.",activites:[{t:"Analyser la situation et agir",q:["1.1  Évaluer la gravité de la situation pour Marc Girault et pour LABORO. Quelles sont les conséquences concrètes si on ne fait rien aujourd'hui ?","1.2  Lister toutes les solutions possibles à explorer dans les 2 prochaines heures — du plus rapide au plus complexe.","1.3  Rédiger le mail à envoyer à Marc Girault pour l'informer du retard — honnête, professionnel, avec une solution proposée."]},{t:"Gérer le fournisseur et capitaliser",q:["2.1  Rédiger le mail à notre atelier de flocage pour signaler l'urgence et demander une livraison partielle ou accélérée.","2.2  Réflexivité : qu'aurais-tu pu faire différemment pour éviter cette situation ? Quelle procédure de suivi de commande proposes-tu pour l'avenir ?"]}],livrable:"Analyse gravité + liste solutions + mail Marc Girault + mail notre atelier de flocage + réflexivité",criteres:[{"c":"Gestion des situations complexes","i":"Je traite correctement les situations difficiles (rupture, retard, litige)"},{"c":"Maîtrise des procédures","i":"Toutes les procédures sont appliquées sans erreur"},{"c":"Solutions adaptées","i":"Les solutions proposées sont adaptées, argumentées et acceptables par le client"},{"c":"Communication professionnelle","i":"Ma communication est fluide, professionnelle et préserve la relation client"}],reflexivite_q:"Quelle difficulté as-tu rencontrée dans le traitement de cette commande ? Comment l'aurais-tu gérée différemment en situation réelle ?",reflexivite:3},
  {id:"M106",titre:"Organiser le fichier client et préparer une action de contact",comp:"C3.1",comp_ref:"C3.1",comp_libelle:"Bloc 3 — Traiter et exploiter l’information ou le contact client",objectif:"Dans cette mission, tu vas analyser et segmenter la base clients LABORO pour construire des actions de contact personnalisées et mesurer leur efficacité.",palier:3,option:"AGEC",dossier:{l:"Extrait fichier clients LABORO — rayon chaussures",rows:[["Isabelle Morin","Dernière visite : 8 mois · Achat : Chaussures running EasyRun · Abonnée newsletter : oui"],["Thomas Renard","Dernière visite : 3 semaines · Achat : gel énergétique · Club sport : oui"],["Sophie Aubert","Dernière visite : 14 mois · Aucun achat récent · Abonnée newsletter : non"],["Karim Benali","Dernière visite : 6 semaines · Achat : Chaussures running Velocity · Avis Google laissé : 4/5"],["Cécile Fontaine","Dernière visite : 2 ans · Ancienne cliente régulière · Non joignable par mail"]]},contexte:"Marco Pellini te remet ce fichier de 5 clients et te demande de préparer une action de contact ciblée avant la Semaine du Trail de mai. Objectif : les faire revenir en magasin.",activites:[{t:"Analyser et segmenter",q:["1.1  Classer les 5 clients en 3 catégories : à relancer en priorité · à entretenir · à réactiver. Justifier chaque classement.","1.2  Pour chaque client, indiquer le canal de contact le plus adapté (mail, téléphone, SMS, aucun) et expliquer pourquoi.","1.3  Identifier le client avec le plus fort potentiel de retour en magasin et expliquer ta stratégie pour le convaincre."]},{t:"Rédiger et planifier",q:["2.1  Rédiger le mail de relance à Isabelle Morin — 80 mots maximum, personnalisé, avec une offre ou un événement concret comme prétexte.","2.2  Réflexivité : pourquoi est-il plus rentable de fidéliser un client existant que d'en conquérir un nouveau ? Illustrer avec des chiffres si possible."]}],livrable:"Classement 3 catégories + canaux de contact + client prioritaire + mail Isabelle Morin + réflexivité",criteres:[{"c":"Analyse complète","i":"Mon analyse exploite l'ensemble des données disponibles sans omission"},{"c":"Segmentation argumentée","i":"Mes critères de segmentation sont justifiés et opérationnels"},{"c":"Actions personnalisées","i":"Les actions proposées sont différenciées selon les segments identifiés"},{"c":"Mesure de l'efficacité","i":"Je définis des indicateurs pour évaluer les actions envisagées"}],reflexivite_q:"Comment la segmentation de la base clients que tu as réalisée peut-elle orienter concrètement les actions commerciales de LABORO ?",reflexivite:3},
  {id:"M107",titre:"Concevoir une action de fidélisation pour les clients sportifs",comp:"C3.2",comp_ref:"C3.2",comp_libelle:"Bloc 3 — Contribuer à des actions de fidélisation de la clientèle et de développement de la relation client",objectif:"Dans cette mission, tu vas construire et évaluer un programme de fidélisation complet pour LABORO, en justifiant les choix effectués.",palier:3,option:"AGEC",dossier:{l:"Données clients sportifs LABORO — situation actuelle",rows:[["Clients sport actifs","67 — dont 41 avec achat sport en 2025"],["Taux de fidélisation","58% — objectif 70%"],["Fréquence d'achat moyenne","1,8 fois par an"],["Événement disponible","Semaine du Trail LABORO — 12 au 17 mai 2026"],["Budget alloué","200 €"],["Canal disponible","Newsletter · Instagram · affichage showroom"]]},contexte:"Romain Sauzet te confie la conception d'une action de fidélisation pour les clients sportifs avant la Semaine du Trail de mai. Objectif simple : les faire revenir et acheter.",activites:[{t:"Concevoir l'action",q:["1.1  Choisir un type d'action de fidélisation adapté à ce profil de clients sportifs — justifier ton choix en 3 phrases. Exemples possibles : offre exclusive, invitation, carte de fidélité, atelier, partenariat club.","1.2  Décrire précisément l'action retenue : nom · durée · mécanisme · cible · avantage pour le client · avantage pour LABORO.","1.3  Ventiler les 200 € de budget entre les postes de dépense nécessaires. Justifier chaque ligne."]},{t:"Communiquer et évaluer",q:["2.1  Rédiger le post Instagram annonçant l'action — 80 mots max · 3 hashtags · call-to-action clair.","2.2  Définir 3 indicateurs pour mesurer le succès de cette action à J+15 — formule et objectif pour chacun.","2.3  Réflexivité : en quoi une action de fidélisation bien ciblée est-elle plus efficace qu'une promotion générale ouverte à tous ?"]}],livrable:"Type d'action justifié + description complète + budget ventilé + post Instagram + 3 indicateurs + réflexivité",criteres:[{"c":"Cohérence du programme","i":"Le programme de fidélisation forme un ensemble cohérent et progressif"},{"c":"Argumentation complète","i":"Chaque composante est justifiée par des données ou des arguments solides"},{"c":"Évaluation prévue","i":"Je définis des indicateurs précis pour mesurer l'efficacité du programme"},{"c":"Orientation client","i":"Le programme est centré sur la valeur apportée au client, pas uniquement sur les ventes"}],reflexivite_q:"Qu'est-ce qui distingue une action de fidélisation efficace d'une simple promotion ? Comment mesurer réellement la fidélité d'un client LABORO ?",reflexivite:3},
  {id:"M108",titre:"Analyser les performances du rayon et proposer des améliorations",comp:"C4A.3",comp_ref:"C4A.3",comp_libelle:"Bloc 4A — Développer la clientèle",objectif:"Dans cette mission, tu vas concevoir et mettre en œuvre des actions de développement de la clientèle adaptées au contexte LABORO.",palier:3,option:"AGEC",dossier:{l:"Indicateurs rayon chaussures — LABORO — avril 2026",rows:[["CA rayon chaussures","24 800 € — objectif 28 000 €"],["Taux de transformation","31% — objectif 40%"],["Panier moyen","147 € — vs 162 € le mois précédent"],["Produit sans vente ce mois","Chaussures running EasyRun — 0 vente"],["Taux de rupture","11% — objectif < 2%"],["Satisfaction rayon","3,8/5 sur 24 avis — verbatim : 'pas assez de choix tailles'"],["Facing actuel","Chaussures route Velocity au niveau yeux zone chaude · Chaussures running EasyRun au sol zone froide"]]},contexte:"Romain Sauzet te présente le bilan d'avril du rayon chaussures. Les chiffres sont en dessous des objectifs. Il te demande d'analyser, de comprendre et de proposer un plan d'action concret pour mai.",activites:[{t:"Analyser et diagnostiquer",q:["1.1  Calculer l'écart en euros et en % entre le CA réalisé et l'objectif. Que représente cet écart concrètement pour LABORO ?","1.2  Identifier les 3 problèmes les plus graves à partir des indicateurs. Pour chacun, expliquer la cause probable et la conséquence directe sur le CA.","1.3  Le facing actuel place le LABORO (0 vente) en zone chaude et le LABORO (best-seller) au sol. Expliquer pourquoi c'est une erreur et quel impact elle a sur les ventes."]},{t:"Proposer et planifier",q:["2.1  Proposer 3 actions correctrices concrètes pour améliorer les performances du rayon en mai — pour chaque action : description, responsable, délai, résultat attendu.","2.2  Réflexivité : qu'est-ce que cette analyse t'apprend sur l'importance de lire les indicateurs régulièrement plutôt qu'en fin de mois ?"]}],livrable:"Calcul écart CA + 3 problèmes diagnostiqués + explication erreur facing + 3 actions correctrices + réflexivité",criteres:[{"c":"Conception de l'action","i":"L'action proposée est cohérente avec les objectifs et la cible de LABORO"},{"c":"Plan opérationnel","i":"Le plan d'action est détaillé, priorisé et réaliste"},{"c":"Argumentation","i":"Chaque choix est justifié par des données ou des arguments professionnels"},{"c":"Indicateurs de suivi","i":"Je définis des indicateurs précis pour évaluer l'efficacité de l'action"}],reflexivite_q:"En quoi les actions de développement clientèle que tu as proposées s'inscrivent-elles dans une logique de long terme pour LABORO ?",reflexivite:3},
  {id:"M109",titre:"Concevoir un plan de prospection pour une cible spécifique",comp:"B4.2",comp_ref:"C4B.2",comp_libelle:"Bloc 4B — Participer à la conception d’une opération de prospection",objectif:"Dans cette mission, tu vas construire un plan de prospection complet pour LABORO en intégrant les objectifs, les cibles et les outils.",palier:3,option:"PVOC",dossier:{l:"Cible — associations sportives Essonne",rows:[["Nombre d'associations sportives en Essonne","~320 — dont 180 avec plus de 50 licenciés"],["Budget achat moyen","2 000 à 6 000 €/an"],["Canal d'achat préféré","Mail 52% · Téléphone 31% · Visite 17%"],["Délai moyen de décision","2 à 4 semaines"],["Contacts","Président ou trésorier dans 80% des cas"],["Budget disponible opération","300 €"],["Objectif Nina Chevalier","4 nouveaux contrats en 6 semaines"]]},contexte:"Nina Chevalier te confie la préparation d'une opération de prospection ciblant les associations sportives de l'Essonne qui ne sont pas encore clientes de LABORO. Elle te donne 6 semaines et 300 €.",activites:[{t:"Dimensionner et planifier",q:["1.1  À partir de l'objectif de 4 contrats, calculer le nombre de prospects à contacter en remontant la chaîne de conversion. Utilise les taux suivants : taux de contact 60% · taux de RDV 12% · taux de transformation 25%.","1.2  Choisir les 2 techniques de prospection les plus adaptées à cette cible — justifier chaque choix avec un argument concret lié au profil des associations sportives.","1.3  Établir le planning semaine par semaine sur 6 semaines — actions, volumes, objectifs par semaine."]},{t:"Budgéter et préparer les outils",q:["2.1  Ventiler les 300 € de budget entre les postes de dépense — justifier chaque ligne.","2.2  Rédiger l'e-mailing de prospection destiné aux associations — objet (5 mots max) · corps du message (120 mots max) · call-to-action unique.","2.3  Réflexivité : pourquoi est-il indispensable de calculer le nombre de prospects à contacter avant de lancer une opération, plutôt que de commencer sans objectif chiffré ?"]}],livrable:"Calcul nombre de prospects + 2 techniques justifiées + planning 6 semaines + budget ventilé + e-mailing rédigé + réflexivité",criteres:[{"c":"Plan de prospection complet","i":"Le plan couvre toutes les étapes — ciblage, approche, outils, suivi, indicateurs"},{"c":"Cohérence stratégique","i":"Le plan est cohérent avec les objectifs commerciaux et les ressources de LABORO"},{"c":"Qualité des supports","i":"Les supports produits sont professionnels et directement utilisables"},{"c":"Indicateurs définis","i":"Les indicateurs de performance de la prospection sont précis et mesurables"}],reflexivite_q:"Qu'est-ce qui distingue un bon plan de prospection d'une simple liste de contacts à appeler ? Comment mesureras-tu le succès de ton plan ?",reflexivite:3},
  {id:"M110",titre:"Mener des entretiens de prospection et gérer les objections",comp:"B4.3",comp_ref:"C4B.3",comp_libelle:"Bloc 4B — Mettre en œuvre une opération de prospection",objectif:"Dans cette mission, tu vas conduire une négociation commerciale B2B de bout en bout, de la prise de contact à la proposition commerciale.",palier:3,option:"PVOC",dossier:{l:"Résultats de la semaine — 3 appels de prospection",rows:[["Appel 1 — AS Évry Athlétisme","Contact obtenu · M. Moretti dit : 'On commande tout chez Decathlon depuis 5 ans'"],["Appel 2 — Club Gym Évry","Contact obtenu · la responsable du club dit : 'Votre catalogue, c'est quoi comme produits ?'"],["Appel 3 — Football Club Orsay","Messagerie · pas de retour depuis 3 jours"],["Appel 4 — CE Safran Massy","Contact obtenu · M. Costa dit : 'Vous êtes combien moins cher que Decathlon ?'"],["Ton bilan personnel","Tu trouves les objections difficiles à gérer · tu perds confiance après un refus"]]},contexte:"Fin de ta première semaine de prospection téléphonique. Nina Chevalier t'observe et te demande de faire le bilan et de préparer tes réponses aux objections que tu as rencontrées.",activites:[{t:"Analyser et préparer les réponses",q:["1.1  Pour chacun des 4 contacts, indiquer le statut dans LABORO Connect (prospect froid, tiède, chaud, à rappeler) et la prochaine action à mener.","1.2  Rédiger ta réponse complète à l'objection de M. Moretti (Decathlon depuis 5 ans) — en utilisant la méthode ARA : Accepter · Reformuler · Argumenter.","1.3  Rédiger ta réponse complète à l'objection de M. Costa (prix vs Decathlon) — sans brader le prix, en valorisant ce que LABORO apporte en plus."]},{t:"Progresser et planifier",q:["2.1  Pour le FC Orsay qui ne rappelle pas, rédiger le mail de relance J+3 — court, professionnel, avec un prétexte pour reprendre contact.","2.2  Réflexivité : comment gérer le découragement après plusieurs refus ? Qu'est-ce qui t'aide à rester professionnel(le) et à continuer ?"]}],livrable:"4 statuts LABORO Connect + réponse objection Decathlon + réponse objection prix + mail relance FC Orsay + réflexivité",criteres:[{"c":"Conduite de la négociation","i":"Je mène la négociation de bout en bout avec fluidité et méthode"},{"c":"Adaptation à l'interlocuteur","i":"Mon approche s'adapte au profil et aux enjeux de l'interlocuteur B2B"},{"c":"Proposition commerciale","i":"Ma proposition est construite, argumentée et adaptée aux besoins identifiés"},{"c":"Conclusion","i":"Je concluis la négociation de façon professionnelle (accord, étape suivante, suivi)"}],reflexivite_q:"Qu'as-tu appris sur ta propre façon de gérer une négociation B2B à travers cette mission ? Qu'aurais-tu fait différemment ?",reflexivite:3},
  {id:"M111",titre:"Assurer le suivi des devis et relancer les prospects",comp:"B4.4",comp_ref:"C4B.4",comp_libelle:"Bloc 4B — Suivre et évaluer l’action de prospection",objectif:"Dans cette mission, tu vas évaluer une action de prospection de LABORO, en calculant les indicateurs clés et en formulant des recommandations.",palier:3,option:"PVOC",dossier:{l:"Devis en attente — LABORO — semaine du 28 avril",rows:[["Devis 1 — AS Palaiseau Football","1 476 € HT · envoyé il y a 8 jours · aucune réponse · événement club le 15 mai"],["Devis 2 — CE Safran Massy","3 840 € HT · envoyé il y a 3 jours · M. Costa a dit 'je regarde avec ma direction'"],["Devis 3 — Mairie d'Évry","2 100 € HT · envoyé il y a 15 jours · aucune réponse · délai de décision habituel 3 semaines"],["Devis 4 — Club Gym Évry","890 € HT · envoyé il y a 2 jours · la responsable du club a demandé un délai de réflexion"],["Objectif","Transformer au moins 2 de ces 4 devis en commande cette semaine"]]},contexte:"Nina Chevalier te remet la liste des devis en attente et te dit : 'Tu as une semaine pour en transformer au moins 2. Commence par les bons dans le bon ordre.'",activites:[{t:"Prioriser et relancer",q:["1.1  Tu as 4 devis en attente (AS Palaiseau, CE Safran, Mairie d'Évry, Club Gym Évry). Définis 3 critères de priorisation de la relance et applique-les pour classer ces 4 devis du plus urgent au moins urgent. Justifie.","1.2  Le devis de l'AS Palaiseau (1 476 € HT) est sans réponse depuis 8 jours et l'événement du club est le 15 mai. Rédige le mail de relance — professionnel, personnalisé, avec un élément nouveau pour relancer l'intérêt.","1.3  M. Costa (CE Safran) a dit « je regarde avec ma direction » il y a 3 jours. Quelle est la bonne action de relance pour ce profil, et à quel moment ? Justifie."]},{t:"Analyser et capitaliser",q:["2.1  Sur ces 4 devis, imagine que 2 soient finalement refusés. Quelles en seraient les causes probables ? Propose une action corrective pour améliorer le taux d'acceptation des prochains devis.","2.2  Quel indicateur de suivi des devis mettrais-tu en place dans LABORO Connect pour piloter ce poste ? Définis : nom, formule, fréquence de mise à jour, seuil d'alerte."]}],criteres:[{"c":"Maîtrise des indicateurs","i":"Tous les indicateurs sont calculés et interprétés correctement"},{"c":"Analyse complète","i":"Mon analyse identifie causes, conséquences et leviers d'amélioration"},{"c":"Recommandations opérationnelles","i":"Mes recommandations sont priorisées, justifiées et chiffrées quand possible"},{"c":"Tableau de bord","i":"Le tableau de bord proposé est complet, lisible et exploitable"}],reflexivite_q:"Quels indicateurs te semblent les plus pertinents pour piloter la prospection de LABORO ? Pourquoi le taux de transformation est-il l'indicateur clé ?",reflexivite:3},
  {id:"M100",titre:"Analyser l'inventaire et lutter contre la démarque",comp:"C4A.1",comp_ref:"C4A.1",comp_libelle:"Bloc 4A — Assurer les opérations préalables à la vente",objectif:"Dans cette mission, tu vas gérer de façon autonome les opérations préalables à la vente en intégrant plusieurs contraintes — prix, stocks, concurrence.",palier:3,option:"AGEC",dossier:{l:"État des stocks — opération Printemps du Sport — LABORO — 30 avril 2026",rows:[["Chaussures running EasyRun (sport)","Stock initial : 52 · Livraison op. : 24 · Stock réel au 30/04 : 58 · Qté vendues : 22"],["Chaussures running Velocity (route)","Stock initial : 30 · Livraison op. : 18 · Stock réel au 30/04 : 28 · Qté vendues : 22"],["tapis de yoga 6mm","Stock initial : 12 · Livraison op. : 12 · Stock réel au 30/04 : 8 · Qté vendues : 14"],["Ceinture porte-bidon LABORO 2x250ml","Stock initial : 80 · Livraison op. : 48 · Stock réel au 30/04 : 60 · Qté vendues : 62"],["Gourde isotherme LABORO 750ml","Stock initial : 20 · Livraison op. : 0 · Stock réel au 30/04 : 14 · Qté vendues : 7"],["Chaussettes anti-ampoules LABORO x3","Stock initial : 35 · Livraison op. : 0 · Stock réel au 30/04 : 10 · Qté vendues : 28"],["PAHT moyen rayon","Tous produits confondus : 42 € HT"],["CA HT total opération","6 200 € HT"]]},contexte:"Romain Sauzet vient de clôturer l'opération Printemps du Sport qui s'est déroulée du 20 au 26 avril 2026. Il t'implique dans l'inventaire post-opération et te demande d'analyser les écarts de stock pour préparer la prochaine opération 'Ete Sport & Loisirs' prévue du 15 au 21 juin.",activites:[{t:"Analyser les résultats de l'inventaire",q:["1.1  Pour les six références, calculer : le stock théorique au 30 avril · la démarque ou la surmarque constatée. Présenter les résultats dans un tableau. Rappel : stock théorique = stock initial + livraison − quantités vendues. Démarque = stock théorique − stock réel (si positif) · surmarque = stock réel − stock théorique (si positif).","1.2  Indiquer deux causes et deux conséquences probables de la démarque constatée sur la Ceinture porte-bidon LABORO 2x250ml, qui est le produit présentant l'écart le plus important.","1.3  Rédiger un compte rendu à l'attention de Romain Sauzet dans lequel tu proposes trois actions concrètes pour lutter contre la démarque lors de la prochaine opération Ete Sport & Loisirs. Respecter la forme d'un compte rendu professionnel."]},{t:"Identifier les priorités de réassort",q:["2.1  À partir du stock réel au 30 avril et des ventes observées pendant l'opération (6 jours), estimer la demande journalière pour chaque référence. Identifier les 2 références en situation de risque de rupture pour l'opération de juin et justifier ton choix.","2.2  Romain Sauzet prévoit une augmentation de 25% des ventes pour les références sport (LABORO, Gourde) lors de l'opération de juin en raison d'un partenariat avec le Club Sportif Forêt de Sénart. Il maintient les volumes identiques pour les autres références. Calculer les besoins en quantités pour l'opération de juin pour chacune des six références. Arrondir à l'entier supérieur."]}],livrable:"Tableau démarque/surmarque + 2 causes + 2 conséquences LABORO + compte rendu 3 actions + 2 références risque rupture + calcul besoins juin",criteres:[{"c":"Maîtrise des calculs","i":"Tous les calculs sont corrects, détaillés et bien présentés"},{"c":"Analyse multi-critères","i":"Mon analyse intègre marge, concurrence, positionnement et image LABORO"},{"c":"Recommandations argumentées","i":"Mes recommandations de prix sont justifiées et cohérentes avec la stratégie LABORO"},{"c":"Gestion de la rentabilité","i":"Je calcule et interprète correctement les indicateurs de rentabilité demandés"}],reflexivite_q:"En quoi la politique tarifaire d'une enseigne comme LABORO est-elle un équilibre entre rentabilité, positionnement et satisfaction client ? Illustre par un exemple tiré de cette mission.",reflexivite:3},
  {id:"M101",titre:"Sélectionner un fournisseur par scoring et établir la commande",comp:"C4A.1",comp_ref:"C4A.1",comp_libelle:"Bloc 4A — Assurer les opérations préalables à la vente",objectif:"Dans cette mission, tu vas gérer de façon autonome les opérations préalables à la vente en intégrant plusieurs contraintes — prix, stocks, concurrence.",palier:3,option:"AGEC",dossier:{l:"Données commande opération Ete Sport & Loisirs — LABORO",rows:[["Stock réel actuel (30/04)","Chaussures running EasyRun : 58 · Chaussures running Velocity : 28 · Tapis yoga LABORO : 8 · Ceinture porte-bidon LABORO 2x250ml : 60 · Gourde isotherme LABORO 750ml : 14 · Chaussettes anti-ampoules LABORO x3 : 10"],["Besoins opération juin","LABORO : 28 · LABORO : 28 · Tapis : 14 · Porte-bidon : 78 · Gourde : 9 · Chaussettes : 35"],["Colisage fournisseurs","LABORO : par 4 paires · LABORO : par 6 paires · Tapis : par 2 · Porte-bidon : par 12 · Gourde : par 6 · Chaussettes : par 8"],["Fournisseur A — SportPro Dist.","Livraison : lundi-vendredi · Délai : 24h · Tarifs préférentiels : oui (−8% dès 1 500 €) · Paiement : 30j fin de mois · Note clients : 4,3/5"],["Fournisseur B — SportLogistique","Livraison : tous les jours · Délai : 72h · Tarifs préférentiels : non · Paiement : 60j fin de mois · Note clients : 4,6/5"],["Fournisseur C — MontagnePro","Livraison : lundi, mercredi, vendredi · Délai : 48h · Tarifs préférentiels : oui (−5% dès 2 000 €) · Paiement : comptant · Note clients : 3,8/5"],["Critères de sélection Romain Sauzet","Livraison 7j/7 : 1pt · Tarifs préférentiels : 1pt · Note clients > 4 : 1pt · Délais de paiement (pas comptant) : 1pt · Délai livraison ≤ 48h : 1pt"]]},contexte:"Suite à l'inventaire post-opération Printemps du Sport, Romain Sauzet te demande de préparer la commande pour l'opération Ete Sport & Loisirs (15-21 juin 2026). Il souhaite également changer de fournisseur principal et t'a fourni les résultats d'un appel d'offres avec trois fournisseurs. Il te confie le scoring et la passation de commande.",activites:[{t:"Calculer les quantités à commander",q:["1.1  A partir des données du dossier, calcule la quantité économique de commande pour les 3 références à réapprovisionner. Montre ton calcul.","1.2  Le fournisseur impose un minimum de commande de 50 unités. Quel impact cela a-t-il sur ta commande ? Propose une solution pour optimiser le stock."]},{t:"Choisir le fournisseur et passer commande",q:["2.1  Compare les 3 fournisseurs du dossier selon 4 critères pondérés. Justifie tes pondérations et conclue sur le meilleur choix pour LABORO.","2.2  Rédige le bon de commande officiel au fournisseur retenu. Vérifie que toutes les mentions obligatoires sont présentes."]}],criteres:[{"c":"Maîtrise des calculs","i":"Tous les calculs sont corrects, détaillés et bien présentés"},{"c":"Analyse multi-critères","i":"Mon analyse intègre marge, concurrence, positionnement et image LABORO"},{"c":"Recommandations argumentées","i":"Mes recommandations de prix sont justifiées et cohérentes avec la stratégie LABORO"},{"c":"Gestion de la rentabilité","i":"Je calcule et interprète correctement les indicateurs de rentabilité demandés"}],reflexivite_q:"En quoi la politique tarifaire d'une enseigne comme LABORO est-elle un équilibre entre rentabilité, positionnement et satisfaction client ? Illustre par un exemple tiré de cette mission.",reflexivite:3},
  {id:"M102",titre:"Fixer les prix, organiser un atelier client et piloter Instagram",comp:"C4A.1",comp_ref:"C4A.1",comp_libelle:"Bloc 4A — Assurer les opérations préalables à la vente",objectif:"Dans cette mission, tu vas gérer de façon autonome les opérations préalables à la vente en intégrant plusieurs contraintes — prix, stocks, concurrence.",palier:3,option:"AGEC",dossier:{l:"Données prix, atelier et Instagram — LABORO Sport & Outdoor",rows:[["Chaussures running Velocity T42","PAHT : 46 € · Taux de marge souhaité : 38% · TVA : 20%"],["Accessoire LABORO Shaker protéine LABORO 700ml","PAHT : 5,00 € · Taux de marge souhaité : 57% · TVA : 20%"],["Prix concurrents — Chaussures running EasyRun","Decathlon : 119,99 € TTC · Intersport : 129,99 € TTC · Go Sport : 124,99 € TTC"],["Prix concurrents — LABORO x12","Amazon : 20,90 € TTC · Intersport : 22,50 € TTC · Biocoop : 21,00 € TTC"],["Atelier Entretien & Prolongation équipement","Durée : 2h · Places : 8 par atelier · Prix inscription : 35 € TTC · Animé par Romain Sauzet + intervenant"],["Coûts atelier (pour 10 ateliers)","Tabliers et consommables : 12 € × 10 ateliers · Matériel réutilisable : forfait 280 € · Prestation intervenant : 120 € × atelier · Communication affiches : 150 €"],["Réservations (10 ateliers — 8 places/atelier)","Atelier 1 : 3 · Atelier 2 : 5 · Atelier 3 : 6 · Atelier 4 : 4 · Atelier 5 : 8 · Atelier 6 : 7 · Atelier 7 : 3 · Atelier 8 : 5 · Atelier 9 : 6 · Atelier 10 : 2"],["Compte Instagram LABORO","1 240 abonnés · Likes : 38 · Commentaires : 11 · Partages : 14"]]},contexte:"Pascal Berruelle veut renforcer la stratégie commerciale de LABORO sur trois fronts : la politique de prix sur deux produits clés, le lancement d'ateliers clients 'Entretien & Prolongation de l'équipement sportif', et la présence digitale sur Instagram. Il te confie ces trois dossiers à traiter en une seule journée de travail — comme dans un sujet E2.",activites:[{t:"Fixer les prix et analyser la concurrence",q:["1.1  Calculer, en fonction des taux de marge souhaités par LABORO, le prix de vente TTC de la Chaussures running EasyRun T42 et de la LABORO Shaker protéine LABORO 700ml x12. Détailler les calculs. Arrondir à deux décimales. Rappel : PVHT = PAHT ÷ (1 − taux de marge) · PVTTC = PVHT × (1 + taux de TVA).","1.2  Comparer les prix obtenus pour chaque produit par rapport aux prix pratiqués par la concurrence. LABORO est-il en dessous, dans la moyenne ou au-dessus du marché ? Justifier l'analyse.","1.3  Pascal Berruelle décide de s'aligner sur le concurrent le moins cher pour les deux produits. Calculer les nouveaux taux de marge correspondants. Détailler les calculs. Arrondir à deux décimales. Rappel : taux de marge = (PVHT − PAHT) ÷ PVHT × 100.","1.4  Analyser pour LABORO l'opportunité d'appliquer ces nouveaux prix alignés sur le moins cher — en tenant compte de la marge dégagée, du positionnement LABORO et de la fidélité clients."]},{t:"Piloter les ateliers clients",q:["2.1  Calculer le coût total de l'ensemble des 10 ateliers 'Entretien & Prolongation'. Détailler les calculs en distinguant charges fixes et charges variables.","2.2  Calculer le taux d'occupation actuel de l'ensemble des 10 ateliers à partir des réservations existantes. Arrondir à deux décimales. Rappel : taux d'occupation = inscriptions réelles ÷ places disponibles totales × 100.","2.3  Calculer la prévision de chiffre d'affaires des ateliers à partir des inscriptions actuelles. Détailler les calculs.","2.4  Déterminer le nombre de participants supplémentaires à inscrire pour atteindre le seuil de rentabilité des ateliers. Détailler les calculs.","2.5  Énoncer trois propositions concrètes pour atteindre ce taux d'occupation minimal — adaptées au contexte LABORO et à sa clientèle sport."]},{t:"Piloter la communication Instagram",q:["3.1  Rédiger les éléments de la publication Instagram annonçant les ateliers 'Entretien & Prolongation' : titre accrocheur, texte (120 mots max), 4 hashtags adaptés au compte LABORO, call-to-action.","3.2  Calculer et commenter le taux d'engagement de la publication Instagram existante. Arrondir à deux décimales. Préciser à quelle catégorie de l'échelle il correspond et justifier. Rappel : taux d'engagement = (likes + commentaires + partages) ÷ abonnés × 100. Échelle : < 1% faible · 1–1,5% moyen · 1,5–3,5% bon · 3,5–6% élevé · > 6% très élevé.","3.3  Proposer trois actions pour développer la visibilité de la publication Instagram des ateliers LABORO.","3.4  Réflexivité : en quoi la rentabilité d'un atelier client ne se mesure-t-elle pas uniquement au chiffre d'affaires qu'il génère directement ? Illustrer par un exemple concret."]}],livrable:"Calcul PVTTC × 2 + comparaison concurrence + nouveaux taux de marge + analyse opportunité + coût total ateliers + taux d'occupation + CA prévisionnel + seuil de rentabilité + 3 propositions occupation + publication Instagram + taux d'engagement commenté + 3 actions visibilité + réflexivité",criteres:[{"c":"Maîtrise des calculs","i":"Tous les calculs sont corrects, détaillés et bien présentés"},{"c":"Analyse multi-critères","i":"Mon analyse intègre marge, concurrence, positionnement et image LABORO"},{"c":"Recommandations argumentées","i":"Mes recommandations de prix sont justifiées et cohérentes avec la stratégie LABORO"},{"c":"Gestion de la rentabilité","i":"Je calcule et interprète correctement les indicateurs de rentabilité demandés"}],reflexivite_q:"En quoi la politique tarifaire d'une enseigne comme LABORO est-elle un équilibre entre rentabilité, positionnement et satisfaction client ? Illustre par un exemple tiré de cette mission.",reflexivite:3}
];if (typeof module !== 'undefined') module.exports = { MISSIONS, MISSIONS_2NDE, MISSIONS_AGEC_1, MISSIONS_PVOC_1, MISSIONS_AGEC_T, MISSIONS_PVOC_T };if (typeof module !== 'undefined') module.exports = { MISSIONS, MISSIONS_2NDE, MISSIONS_AGEC_1, MISSIONS_PVOC_1, MISSIONS_AGEC_T, MISSIONS_PVOC_T };
